{
  "name": "AgendaMaster AI",
  "description": "Uma aplicação avançada para criação de miolos de agendas datadas, com integração de IA para conteúdo criativo e gerenciamento de dados anuais."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
