export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

export interface AgendaConfig {
  year: number;
  layout: 'daily' | 'weekly';
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  theme: 'minimal' | 'floral' | 'executive';
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import { DayData, Holiday } from '../types';

// Simple fixed holidays for Brazil (simplified logic for demo)
const getFixedHolidays = (year: number): Holiday[] => [
  { date: `${year}-01-01`, name: 'Confraternização Universal', type: 'national' },
  { date: `${year}-04-21`, name: 'Tiradentes', type: 'national' },
  { date: `${year}-05-01`, name: 'Dia do Trabalho', type: 'national' },
  { date: `${year}-09-07`, name: 'Independência do Brasil', type: 'national' },
  { date: `${year}-10-12`, name: 'Nossa Senhora Aparecida', type: 'national' },
  { date: `${year}-11-02`, name: 'Finados', type: 'national' },
  { date: `${year}-11-15`, name: 'Proclamação da República', type: 'national' },
  { date: `${year}-12-25`, name: 'Natal', type: 'national' },
];

const getMobileHolidays = (year: number): Holiday[] => {
  // Easter calculation (Meeus/Jones/Butcher's algorithm)
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31); // 3 = March, 4 = April
  const day = ((h + l - 7 * m + 114) % 31) + 1;

  const easterDate = new Date(year, month - 1, day);

  // Carnival: 47 days before Easter
  const carnivalDate = new Date(easterDate);
  carnivalDate.setDate(easterDate.getDate() - 47);

  // Corpus Christi: 60 days after Easter
  const corpusDate = new Date(easterDate);
  corpusDate.setDate(easterDate.getDate() + 60);

  // Good Friday: 2 days before Easter
  const goodFridayDate = new Date(easterDate);
  goodFridayDate.setDate(easterDate.getDate() - 2);

  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return [
    { date: formatDate(carnivalDate), name: 'Carnaval', type: 'optional' },
    { date: formatDate(goodFridayDate), name: 'Paixão de Cristo', type: 'national' },
    { date: formatDate(corpusDate), name: 'Corpus Christi', type: 'optional' },
  ];
};

export const generateCalendarYear = (year: number, includeHolidays: boolean): DayData[] => {
  const days: DayData[] = [];
  const start = new Date(year, 0, 1);
  const end = new Date(year, 11, 31);

  const holidays = includeHolidays 
    ? [...getFixedHolidays(year), ...getMobileHolidays(year)]
    : [];

  const holidayMap = new Map(holidays.map(h => [h.date, h.name]));

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const isoDate = d.toISOString().split('T')[0];
    const holidayName = holidayMap.get(isoDate);

    // Simple moon phase simulation (approximate 29.53 days cycle)
    // Reference: Jan 6, 2000 was a New Moon.
    const knownNewMoon = new Date('2000-01-06').getTime();
    const current = d.getTime();
    const diffDays = (current - knownNewMoon) / (1000 * 60 * 60 * 24);
    const cycle = 29.53058867;
    const phasePos = (diffDays % cycle) / cycle;

    let moonPhase = '';
    if (phasePos < 0.05 || phasePos > 0.95) moonPhase = '🌑 Nova';
    else if (phasePos < 0.30 && phasePos > 0.20) moonPhase = '🌓 Crescente';
    else if (phasePos < 0.55 && phasePos > 0.45) moonPhase = '🌕 Cheia';
    else if (phasePos < 0.80 && phasePos > 0.70) moonPhase = '🌗 Minguante';

    days.push({
      date: new Date(d),
      dayOfWeek: d.getDay(),
      dayOfMonth: d.getDate(),
      month: d.getMonth(),
      year: d.getFullYear(),
      holiday: holidayName,
      moonPhase: moonPhase || undefined
    });
  }

  return days;
};

export const getMonthName = (monthIndex: number): string => {
  const months = [
    'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];
  return months[monthIndex];
};

export const getDayName = (dayIndex: number): string => {
  const days = [
    'Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira',
    'Quinta-feira', 'Sexta-feira', 'Sábado'
  ];
  return days[dayIndex];
};

import { GoogleGenAI, Type } from "@google/genai";

// Note: In a real production app, this key should be proxied or strictly env controlled.
// The prompt instructions say to use process.env.API_KEY.
const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
        console.warn("API Key not found in environment. AI features will be disabled.");
        return null;
    }
    return new GoogleGenAI({ apiKey });
}


export const generateMonthlyQuotes = async (year: number): Promise<string[]> => {
  const ai = getClient();
  if (!ai) return Array(12).fill("A criatividade requer coragem.");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Gere 12 frases motivacionais e inspiradoras em Português, uma para cada mês do ano de ${year}. As frases devem ser curtas (máximo 15 palavras) e adequadas para o cabeçalho de uma agenda profissional/estudantil. Retorne APENAS um array JSON de strings.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.STRING
          }
        }
      }
    });

    const jsonStr = response.text;
    if (jsonStr) {
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed) && parsed.length >= 12) {
        return parsed.slice(0, 12);
      }
    }
    return Array(12).fill("Planeje hoje para colher amanhã.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    return Array(12).fill("A persistência é o caminho do êxito.");
  }
};

export const analyzeAgendaTheme = async (themeDescription: string): Promise<string> => {
     const ai = getClient();
     if (!ai) return "Sugestão indisponível (Sem API Key)";

     try {
         const response = await ai.models.generateContent({
             model: 'gemini-3-flash-preview',
             contents: `O usuário quer criar uma agenda com o seguinte tema ou estilo: "${themeDescription}". Sugira uma paleta de cores CSS (hex codes) e uma fonte do Google Fonts que combinaria. Formato curto e direto. Exemplo: "Cores: #F3F4F6, #1F2937. Fonte: Roboto."`
         });
         return response.text || "";
     } catch (e) {
         return "Erro ao analisar tema.";
     }
}

import React, { useState } from 'react';
import { User } from '../types';
import { Lock, Mail, ArrowRight } from 'lucide-react';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    // Simulate API delay
    setTimeout(() => {
      if (email && password.length >= 6) {
        onLogin({
          email,
          name: email.split('@')[0],
          plan: 'pro'
        });
      } else {
        setError('Credenciais inválidas. A senha deve ter no mínimo 6 caracteres.');
        setIsLoading(false);
      }
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-100 via-purple-50 to-pink-100 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden flex flex-col md:flex-row">

        <div className="w-full p-8 md:p-10">
          <div className="text-center mb-8">
            <div className="bg-indigo-600 w-12 h-12 rounded-xl flex items-center justify-center mx-auto mb-4 shadow-lg shadow-indigo-200">
              <Lock className="text-white w-6 h-6" />
            </div>
            <h1 className="text-2xl font-bold text-gray-800">Área do Aluno</h1>
            <p className="text-gray-500 mt-2 text-sm">Acesse para criar seus miolos de agenda</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Mail className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="pl-10 block w-full border-gray-300 rounded-lg border p-2.5 text-gray-900 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
                  placeholder="aluno@exemplo.com"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Senha</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="pl-10 block w-full border-gray-300 rounded-lg border p-2.5 text-gray-900 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
                  placeholder="••••••••"
                />
              </div>
            </div>

            {error && (
              <div className="text-red-500 text-sm bg-red-50 p-3 rounded-lg border border-red-100">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={isLoading}
              className="w-full flex justify-center items-center py-3 px-4 border border-transparent rounded-lg shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all transform hover:scale-[1.02]"
            >
              {isLoading ? (
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : (
                <>
                  Entrar <ArrowRight className="ml-2 h-4 w-4" />
                </>
              )}
            </button>
          </form>

          <div className="mt-6 text-center">
            <p className="text-xs text-gray-500">
              Esqueceu sua senha? <a href="#" className="text-indigo-600 hover:text-indigo-500 font-medium">Recuperar acesso</a>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { AgendaConfig, User, DayData } from '../types';
import { generateCalendarYear, getMonthName } from '../services/calendarService';
import { generateMonthlyQuotes, analyzeAgendaTheme } from '../services/geminiService';
import { Calendar, Settings, Sparkles, Printer, LogOut, ChevronRight, Moon, Type, LayoutTemplate } from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layout: 'daily',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    theme: 'minimal'
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeTab, setActiveTab] = useState<'config' | 'preview'>('config');
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [customThemePrompt, setCustomThemePrompt] = useState('');

  // Auto-generate on config change (debounced)
  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  const handleGenerateQuotes = async () => {
    if (!process.env.API_KEY) {
      alert("Chave de API não configurada. Funcionalidade de IA indisponível.");
      return;
    }
    setIsGenerating(true);
    try {
      const generatedQuotes = await generateMonthlyQuotes(config.year);
      setQuotes(generatedQuotes);
      setConfig(prev => ({ ...prev, includeQuotes: true }));
    } finally {
      setIsGenerating(false);
    }
  };

  const handleAiThemeAnalysis = async () => {
    if(!customThemePrompt) return;
    setIsGenerating(true);
    try {
        const result = await analyzeAgendaTheme(customThemePrompt);
        setAiAnalysis(result);
    } finally {
        setIsGenerating(false);
    }
  }

  const togglePreview = () => {
    setActiveTab('preview');
  };

  // Preview Component helper
  const renderDay = (day: DayData) => {
    const quoteForMonth = config.includeQuotes ? quotes[day.month] : null;

    // Different styles based on theme
    const themeClasses = {
      minimal: "bg-white border-gray-200",
      floral: "bg-pink-50 border-pink-200 font-serif",
      executive: "bg-slate-50 border-slate-300 font-sans"
    };

    return (
      <div key={day.date.toISOString()} className={`break-inside-avoid p-4 mb-4 border rounded-lg shadow-sm ${themeClasses[config.theme]} flex flex-col h-full min-h-[200px]`}>
        <div className="flex justify-between items-start border-b pb-2 mb-2 border-opacity-50 border-gray-400">
          <div>
            <span className="text-3xl font-bold text-gray-800">{day.dayOfMonth}</span>
            <span className="text-sm uppercase tracking-wider text-gray-500 ml-2">{getMonthName(day.month).substring(0, 3)}</span>
          </div>
          <div className="text-right">
             <div className="text-sm font-medium text-gray-600">{['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'][day.dayOfWeek]}</div>
             {config.includeMoonPhases && day.moonPhase && (
               <div className="text-xs text-indigo-600 mt-1">{day.moonPhase}</div>
             )}
          </div>
        </div>

        {day.holiday && (
          <div className="mb-2 inline-block px-2 py-1 bg-red-100 text-red-700 text-xs rounded-full self-start">
            {day.holiday}
          </div>
        )}

        {/* Lines for writing */}
        <div className="flex-grow space-y-4 mt-2">
            {[1, 2, 3, 4, 5].map(i => (
                <div key={i} className="border-b border-gray-200 border-dashed h-4 w-full"></div>
            ))}
        </div>

        {/* Quote only on first day of month or daily if needed (logic simplified here) */}
        {quoteForMonth && day.dayOfMonth === 1 && (
            <div className="mt-4 pt-2 border-t border-gray-200 text-center italic text-gray-500 text-xs">
                "{quoteForMonth}"
            </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex justify-between items-center">
          <div className="flex items-center space-x-3">
            <div className="bg-indigo-600 p-2 rounded-lg">
                <Calendar className="h-5 w-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-gray-900">AgendaMaster AI</h1>
          </div>
          <div className="flex items-center space-x-4">
             <span className="text-sm text-gray-600 hidden sm:block">Olá, <span className="font-semibold">{user.name}</span></span>
             <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors">
                <LogOut className="h-5 w-5" />
             </button>
          </div>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Config - Hidden on Print */}
        <aside className={`bg-white w-full md:w-80 border-r border-gray-200 overflow-y-auto no-print ${activeTab === 'preview' ? 'hidden md:block' : 'block'}`}>
            <div className="p-6 space-y-8">

                {/* Section: Basic Settings */}
                <div>
                    <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 flex items-center">
                        <Settings className="w-4 h-4 mr-2" /> Configurações Básicas
                    </h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Ano da Agenda</label>
                            <input 
                                type="number" 
                                value={config.year}
                                onChange={(e) => setConfig({...config, year: parseInt(e.target.value)})}
                                className="block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm border p-2"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Layout</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button 
                                    onClick={() => setConfig({...config, layout: 'daily'})}
                                    className={`px-3 py-2 text-sm rounded-md border ${config.layout === 'daily' ? 'bg-indigo-50 border-indigo-500 text-indigo-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                                >
                                    1 Dia/Pág
                                </button>
                                <button 
                                    onClick={() => setConfig({...config, layout: 'weekly'})}
                                    className={`px-3 py-2 text-sm rounded-md border ${config.layout === 'weekly' ? 'bg-indigo-50 border-indigo-500 text-indigo-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                                >
                                    Semanal
                                </button>
                            </div>
                        </div>
                        <div>
                           <label className="block text-sm font-medium text-gray-700 mb-1">Tema Visual</label>
                           <select 
                             value={config.theme}
                             onChange={(e) => setConfig({...config, theme: e.target.value as any})}
                             className="block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm border p-2"
                           >
                               <option value="minimal">Minimalista (Clean)</option>
                               <option value="floral">Floral (Delicado)</option>
                               <option value="executive">Executivo (Sóbrio)</option>
                           </select>
                        </div>
                    </div>
                </div>

                <hr className="border-gray-200" />

                {/* Section: Inclusions */}
                <div>
                    <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 flex items-center">
                        <LayoutTemplate className="w-4 h-4 mr-2" /> Dados Variáveis
                    </h2>
                    <div className="space-y-3">
                        <label className="flex items-center space-x-3">
                            <input 
                                type="checkbox" 
                                checked={config.includeHolidays}
                                onChange={(e) => setConfig({...config, includeHolidays: e.target.checked})}
                                className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                            />
                            <span className="text-sm text-gray-700">Feriados Nacionais (BR)</span>
                        </label>
                        <label className="flex items-center space-x-3">
                            <input 
                                type="checkbox" 
                                checked={config.includeMoonPhases}
                                onChange={(e) => setConfig({...config, includeMoonPhases: e.target.checked})}
                                className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                            />
                            <div className="flex items-center">
                                <span className="text-sm text-gray-700 mr-2">Fases da Lua</span>
                                <Moon className="w-3 h-3 text-gray-400" />
                            </div>
                        </label>
                    </div>
                </div>

                <hr className="border-gray-200" />

                {/* Section: AI Power */}
                <div className="bg-gradient-to-br from-purple-50 to-indigo-50 p-4 rounded-xl border border-indigo-100">
                    <h2 className="text-xs font-semibold text-indigo-600 uppercase tracking-wider mb-3 flex items-center">
                        <Sparkles className="w-4 h-4 mr-2" /> Inteligência Artificial
                    </h2>

                    <div className="space-y-4">
                        <p className="text-xs text-gray-600">
                            Enriqueça o miolo da agenda gerando frases motivacionais únicas para cada mês.
                        </p>
                        <button
                            onClick={handleGenerateQuotes}
                            disabled={isGenerating}
                            className="w-full flex items-center justify-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-75 disabled:cursor-not-allowed"
                        >
                            {isGenerating ? 'Gerando...' : 'Gerar Frases Mensais'}
                        </button>
                        {quotes.length > 0 && (
                            <div className="text-xs text-green-600 bg-green-50 p-2 rounded border border-green-100 flex items-center">
                                <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                                12 frases geradas com sucesso!
                            </div>
                        )}

                        <div className="pt-2 border-t border-indigo-100 mt-2">
                             <label className="block text-xs font-medium text-gray-700 mb-1">Consultar Estilo</label>
                             <div className="flex gap-2">
                                 <input 
                                     type="text"
                                     value={customThemePrompt}
                                     onChange={(e) => setCustomThemePrompt(e.target.value)}
                                     placeholder="Ex: Agenda boho chic..."
                                     className="flex-1 text-xs border-gray-300 rounded p-1"
                                 />
                                 <button onClick={handleAiThemeAnalysis} className="bg-white border p-1 rounded hover:bg-gray-50">
                                     <Sparkles className="w-4 h-4 text-indigo-500" />
                                 </button>
                             </div>
                             {aiAnalysis && (
                                 <p className="text-[10px] mt-2 text-gray-600 bg-white p-2 rounded border">{aiAnalysis}</p>
                             )}
                        </div>
                    </div>
                </div>

                <div className="md:hidden">
                    <button 
                        onClick={togglePreview}
                        className="w-full flex items-center justify-center px-4 py-3 border border-transparent text-sm font-medium rounded-md text-indigo-700 bg-indigo-100 hover:bg-indigo-200"
                    >
                        Ver Prévia <ChevronRight className="ml-2 w-4 h-4" />
                    </button>
                </div>

            </div>
        </aside>

        {/* Main Content Area - Preview */}
        <main className={`flex-1 overflow-y-auto bg-gray-100 custom-scrollbar p-4 md:p-8 ${activeTab === 'config' ? 'hidden md:block' : 'block'}`}>

            <div className="max-w-4xl mx-auto">
                {/* Toolbar */}
                <div className="flex justify-between items-center mb-6 no-print">
                    <div className="md:hidden">
                        <button onClick={() => setActiveTab('config')} className="text-sm text-gray-600 hover:text-gray-900 flex items-center">
                            ← Voltar para Configurações
                        </button>
                    </div>
                    <div className="flex items-center space-x-4 ml-auto">
                        <span className="text-sm text-gray-500 hidden sm:inline-block">
                            Total de dias: {generatedData.length}
                        </span>
                        <button 
                            onClick={() => window.print()}
                            className="flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                            <Printer className="w-4 h-4 mr-2" />
                            Imprimir / PDF
                        </button>
                    </div>
                </div>

                {/* Visualization Area */}
                <div id="print-area" className="bg-white shadow-2xl min-h-[29.7cm] p-8 md:p-16 print:shadow-none print:p-0 print:w-full">

                    {/* Cover / Header Example */}
                    <div className="text-center mb-12 pb-8 border-b-2 border-gray-100">
                        <h1 className={`text-4xl md:text-6xl font-bold text-gray-800 mb-2 ${config.theme === 'floral' ? 'font-serif text-pink-900' : ''}`}>
                            {config.year}
                        </h1>
                        <p className="text-gray-500 uppercase tracking-[0.2em] text-sm">
                            Agenda {config.layout === 'daily' ? 'Diária' : 'Semanal'}
                        </p>
                    </div>

                    {/* Grid of Days */}
                    <div className={`grid gap-4 ${config.layout === 'daily' ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'}`}>
                        {/* Rendering a subset for performance in preview, but logic handles all */}
                        {/* In a real "print" scenario, we'd render all, but for DOM performance we limit the preview */}
                        {generatedData.slice(0, config.layout === 'daily' ? 6 : 4).map((day) => renderDay(day))}

                        {/* Info for user */}
                        <div className="col-span-full py-12 text-center no-print">
                           <p className="text-gray-400 italic">
                               ... Visualizando apenas os primeiros dias para performance ...<br/>
                               Use o botão "Imprimir / PDF" para gerar o documento completo.
                           </p>
                        </div>
                    </div>

                    {/* Hidden div that contains everything only for print media */}
                    <div className="hidden print-only">
                         <div className={`grid gap-8 ${config.layout === 'daily' ? 'grid-cols-1' : 'grid-cols-1'}`}>
                             {/* Render first month for print demo to save paper if user tests */}
                             {generatedData.slice(0, 31).map((day, idx) => (
                                 <div key={`print-${idx}`} className={`${idx > 0 && idx % 2 === 0 ? 'page-break' : ''}`}>
                                    {renderDay(day)}
                                 </div>
                             ))}
                         </div>
                    </div>

                </div>
            </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import { User, AppState } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.LOGIN);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setAppState(AppState.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAppState(AppState.LOGIN);
  };

  return (
    <>
      {appState === AppState.LOGIN && (
        <Login onLogin={handleLogin} />
      )}

      {appState === AppState.DASHBOARD && currentUser && (
        <Dashboard user={currentUser} onLogout={handleLogout} />
      )}
    </>
  );
};

export default App;

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

export interface DesignConfig {
  fontFamily: string;
  primaryColor: string; // Textos principais, dias
  accentColor: string; // Detalhes, feriados
  lineColor: string; // Linhas do miolo
  backgroundColor: string; // Fundo do dia (se aplicável)
  headerStyle: 'minimal' | 'boxed' | 'circle' | 'banner';
  bodyStyle: 'lines' | 'grid' | 'dots' | 'blank';
  lineSpacing: number;
}

export interface AgendaConfig {
  year: number;
  layout: 'daily' | 'weekly';
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  design: DesignConfig; // New design object
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import React, { useState, useEffect } from 'react';
import { AgendaConfig, User, DayData } from '../types';
import { generateCalendarYear, getMonthName } from '../services/calendarService';
import { generateMonthlyQuotes, analyzeAgendaTheme } from '../services/geminiService';
import { Calendar, Settings, Sparkles, Printer, LogOut, ChevronRight, Moon, LayoutTemplate, Palette, Type, Grid, PaintBucket } from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const fontOptions = [
  { name: 'Inter (Moderno)', value: "'Inter', sans-serif" },
  { name: 'Playfair Display (Elegante)', value: "'Playfair Display', serif" },
  { name: 'Merriweather (Clássico)', value: "'Merriweather', serif" },
  { name: 'Lato (Neutro)', value: "'Lato', sans-serif" },
  { name: 'Dancing Script (Manuscrito)', value: "'Dancing Script', cursive" },
];

const headerStyles = [
  { id: 'minimal', name: 'Minimalista', icon: 'M' },
  { id: 'boxed', name: 'Caixa Sólida', icon: '■' },
  { id: 'circle', name: 'Círculo', icon: '●' },
  { id: 'banner', name: 'Banner', icon: '⚑' },
];

const bodyStyles = [
  { id: 'lines', name: 'Pautado' },
  { id: 'grid', name: 'Quadriculado' },
  { id: 'dots', name: 'Pontilhado' },
  { id: 'blank', name: 'Em Branco' },
];

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layout: 'daily',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    design: {
      fontFamily: "'Inter', sans-serif",
      primaryColor: '#1f2937',
      accentColor: '#4f46e5',
      lineColor: '#e5e7eb',
      backgroundColor: '#ffffff',
      headerStyle: 'minimal',
      bodyStyle: 'lines',
      lineSpacing: 24
    }
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeTab, setActiveTab] = useState<'config' | 'preview'>('config');
  const [sidebarTab, setSidebarTab] = useState<'data' | 'design'>('data');
  const [aiAnalysis, setAiAnalysis] = useState<string>('');
  const [customThemePrompt, setCustomThemePrompt] = useState('');

  // Auto-generate on config change (debounced)
  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  const handleGenerateQuotes = async () => {
    if (!process.env.API_KEY) {
      alert("Chave de API não configurada. Funcionalidade de IA indisponível.");
      return;
    }
    setIsGenerating(true);
    try {
      const generatedQuotes = await generateMonthlyQuotes(config.year);
      setQuotes(generatedQuotes);
      setConfig(prev => ({ ...prev, includeQuotes: true }));
    } finally {
      setIsGenerating(false);
    }
  };

  const handleAiThemeAnalysis = async () => {
    if(!customThemePrompt) return;
    setIsGenerating(true);
    try {
        const result = await analyzeAgendaTheme(customThemePrompt);
        setAiAnalysis(result);
    } finally {
        setIsGenerating(false);
    }
  }

  const togglePreview = () => {
    setActiveTab('preview');
  };

  const updateDesign = (key: keyof typeof config.design, value: any) => {
    setConfig(prev => ({
      ...prev,
      design: { ...prev.design, [key]: value }
    }));
  };

  // Preview Component helper
  const renderDay = (day: DayData) => {
    const quoteForMonth = config.includeQuotes ? quotes[day.month] : null;
    const { design } = config;

    // Dynamic styles based on design config
    const containerStyle = {
      fontFamily: design.fontFamily,
      backgroundColor: design.backgroundColor,
      color: design.primaryColor,
      borderColor: design.lineColor
    };

    const headerContent = (
      <div className="flex justify-between items-start w-full">
        <div className="flex items-center">
            {/* Header Style Logic */}
            {design.headerStyle === 'minimal' && (
                <div className="flex items-baseline">
                    <span className="text-4xl font-bold mr-2" style={{ color: design.primaryColor }}>{day.dayOfMonth}</span>
                    <span className="text-sm uppercase tracking-wider opacity-60">{getMonthName(day.month).substring(0, 3)}</span>
                </div>
            )}

            {design.headerStyle === 'boxed' && (
                <div className="flex items-center">
                    <div className="w-12 h-12 flex items-center justify-center rounded-lg mr-3 text-white font-bold text-2xl shadow-sm" style={{ backgroundColor: design.accentColor }}>
                        {day.dayOfMonth}
                    </div>
                    <span className="text-sm uppercase font-semibold tracking-wide" style={{ color: design.accentColor }}>{getMonthName(day.month)}</span>
                </div>
            )}

            {design.headerStyle === 'circle' && (
                <div className="flex items-center flex-col mr-4">
                    <div className="w-14 h-14 flex items-center justify-center rounded-full border-2 font-bold text-2xl" style={{ borderColor: design.accentColor, color: design.accentColor }}>
                        {day.dayOfMonth}
                    </div>
                </div>
            )}

             {design.headerStyle === 'banner' && (
                <div className="relative pl-3 pr-6 py-1 -ml-6 mt-1 shadow-sm" style={{ backgroundColor: design.accentColor, color: '#fff' }}>
                    <span className="text-2xl font-bold">{day.dayOfMonth}</span>
                    <span className="ml-2 text-sm uppercase">{getMonthName(day.month).substring(0, 3)}</span>
                    <div className="absolute top-0 right-0 -mr-4 w-0 h-0 border-t-[16px] border-b-[16px] border-l-[16px] border-t-transparent border-b-transparent" style={{ borderLeftColor: design.accentColor }}></div>
                </div>
            )}
        </div>

        <div className="text-right">
             <div className="text-sm font-medium opacity-75">{['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'][day.dayOfWeek]}</div>
             {config.includeMoonPhases && day.moonPhase && (
               <div className="text-xs mt-1" style={{ color: design.accentColor }}>{day.moonPhase}</div>
             )}
        </div>
      </div>
    );

    // Body Style Logic (Lines/Grid)
    const renderBody = () => {
        const lineCount = 6;
        const lines = [];

        if (design.bodyStyle === 'blank') return <div className="h-full w-full" />;

        for (let i = 0; i < lineCount; i++) {
            if (design.bodyStyle === 'lines') {
                lines.push(
                    <div key={i} 
                        className="w-full border-b" 
                        style={{ 
                            height: `${design.lineSpacing}px`, 
                            borderColor: design.lineColor,
                            borderStyle: 'solid'
                        }} 
                    />
                );
            } else if (design.bodyStyle === 'dots') {
                 lines.push(
                    <div key={i} 
                        className="w-full border-b" 
                        style={{ 
                            height: `${design.lineSpacing}px`, 
                            borderColor: design.lineColor,
                            borderStyle: 'dotted'
                        }} 
                    />
                );
            } else if (design.bodyStyle === 'grid') {
                 // Grid is tricky with just divs, using a background pattern approach for the container usually better, 
                 // but for this simple loop let's do lines + vertical borders if possible, or just horizontal lines for now
                 // Simulating grid with CSS background in the parent container is better
            }
        }

        if (design.bodyStyle === 'grid') {
            return (
                 <div className="flex-grow w-full h-full opacity-50" style={{
                    backgroundImage: `linear-gradient(${design.lineColor} 1px, transparent 1px), linear-gradient(90deg, ${design.lineColor} 1px, transparent 1px)`,
                    backgroundSize: `${design.lineSpacing}px ${design.lineSpacing}px`
                 }}></div>
            );
        }

        return <div className="flex-grow w-full mt-2">{lines}</div>;
    };

    return (
      <div key={day.date.toISOString()} className="break-inside-avoid p-6 mb-4 border rounded-lg shadow-sm flex flex-col h-full min-h-[220px]" style={containerStyle}>
        <div className="border-b pb-3 mb-2" style={{ borderColor: design.lineColor }}>
            {headerContent}
        </div>

        {day.holiday && (
          <div className="mb-2 inline-block px-2 py-0.5 text-xs rounded-md font-medium self-start" style={{ backgroundColor: `${design.accentColor}20`, color: design.accentColor }}>
            {day.holiday}
          </div>
        )}

        {renderBody()}

        {/* Quote */}
        {quoteForMonth && day.dayOfMonth === 1 && (
            <div className="mt-4 pt-2 border-t text-center italic text-xs opacity-60" style={{ borderColor: design.lineColor }}>
                "{quoteForMonth}"
            </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-10 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex justify-between items-center">
          <div className="flex items-center space-x-3">
            <div className="bg-indigo-600 p-2 rounded-lg">
                <Calendar className="h-5 w-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-gray-900">AgendaMaster AI</h1>
          </div>
          <div className="flex items-center space-x-4">
             <span className="text-sm text-gray-600 hidden sm:block">Olá, <span className="font-semibold">{user.name}</span></span>
             <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors">
                <LogOut className="h-5 w-5" />
             </button>
          </div>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar Config - Hidden on Print */}
        <aside className={`bg-white w-full md:w-80 border-r border-gray-200 flex flex-col no-print ${activeTab === 'preview' ? 'hidden md:flex' : 'flex'}`}>

            {/* Sidebar Tabs */}
            <div className="flex border-b border-gray-200">
                <button 
                    onClick={() => setSidebarTab('data')}
                    className={`flex-1 py-3 text-sm font-medium flex items-center justify-center ${sidebarTab === 'data' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <Settings className="w-4 h-4 mr-2" /> Dados
                </button>
                <button 
                    onClick={() => setSidebarTab('design')}
                    className={`flex-1 py-3 text-sm font-medium flex items-center justify-center ${sidebarTab === 'design' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <Palette className="w-4 h-4 mr-2" /> Design
                </button>
            </div>

            <div className="p-6 space-y-8 overflow-y-auto flex-1 custom-scrollbar">

                {sidebarTab === 'data' && (
                    <>
                    {/* Section: Basic Settings */}
                    <div>
                        <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 flex items-center">
                            Configurações Básicas
                        </h2>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Ano da Agenda</label>
                                <input 
                                    type="number" 
                                    value={config.year}
                                    onChange={(e) => setConfig({...config, year: parseInt(e.target.value)})}
                                    className="block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm border p-2"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Layout</label>
                                <div className="grid grid-cols-2 gap-2">
                                    <button 
                                        onClick={() => setConfig({...config, layout: 'daily'})}
                                        className={`px-3 py-2 text-sm rounded-md border ${config.layout === 'daily' ? 'bg-indigo-50 border-indigo-500 text-indigo-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                                    >
                                        1 Dia/Pág
                                    </button>
                                    <button 
                                        onClick={() => setConfig({...config, layout: 'weekly'})}
                                        className={`px-3 py-2 text-sm rounded-md border ${config.layout === 'weekly' ? 'bg-indigo-50 border-indigo-500 text-indigo-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                                    >
                                        Semanal
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>

                    <hr className="border-gray-200" />

                    {/* Section: Inclusions */}
                    <div>
                        <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-4 flex items-center">
                            <LayoutTemplate className="w-4 h-4 mr-2" /> Dados Variáveis
                        </h2>
                        <div className="space-y-3">
                            <label className="flex items-center space-x-3">
                                <input 
                                    type="checkbox" 
                                    checked={config.includeHolidays}
                                    onChange={(e) => setConfig({...config, includeHolidays: e.target.checked})}
                                    className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                                />
                                <span className="text-sm text-gray-700">Feriados Nacionais (BR)</span>
                            </label>
                            <label className="flex items-center space-x-3">
                                <input 
                                    type="checkbox" 
                                    checked={config.includeMoonPhases}
                                    onChange={(e) => setConfig({...config, includeMoonPhases: e.target.checked})}
                                    className="h-4 w-4 text-indigo-600 focus:ring-indigo-500 border-gray-300 rounded"
                                />
                                <div className="flex items-center">
                                    <span className="text-sm text-gray-700 mr-2">Fases da Lua</span>
                                    <Moon className="w-3 h-3 text-gray-400" />
                                </div>
                            </label>
                        </div>
                    </div>

                    <hr className="border-gray-200" />

                    {/* Section: AI Power */}
                    <div className="bg-gradient-to-br from-purple-50 to-indigo-50 p-4 rounded-xl border border-indigo-100">
                        <h2 className="text-xs font-semibold text-indigo-600 uppercase tracking-wider mb-3 flex items-center">
                            <Sparkles className="w-4 h-4 mr-2" /> Inteligência Artificial
                        </h2>

                        <div className="space-y-4">
                            <p className="text-xs text-gray-600">
                                Enriqueça o miolo da agenda gerando frases motivacionais únicas para cada mês.
                            </p>
                            <button
                                onClick={handleGenerateQuotes}
                                disabled={isGenerating}
                                className="w-full flex items-center justify-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 disabled:opacity-75 disabled:cursor-not-allowed"
                            >
                                {isGenerating ? 'Gerando...' : 'Gerar Frases Mensais'}
                            </button>
                            {quotes.length > 0 && (
                                <div className="text-xs text-green-600 bg-green-50 p-2 rounded border border-green-100 flex items-center">
                                    <span className="w-2 h-2 bg-green-500 rounded-full mr-2"></span>
                                    12 frases geradas com sucesso!
                                </div>
                            )}

                            <div className="pt-2 border-t border-indigo-100 mt-2">
                                <label className="block text-xs font-medium text-gray-700 mb-1">Consultar Estilo</label>
                                <div className="flex gap-2">
                                    <input 
                                        type="text"
                                        value={customThemePrompt}
                                        onChange={(e) => setCustomThemePrompt(e.target.value)}
                                        placeholder="Ex: Agenda boho chic..."
                                        className="flex-1 text-xs border-gray-300 rounded p-1"
                                    />
                                    <button onClick={handleAiThemeAnalysis} className="bg-white border p-1 rounded hover:bg-gray-50">
                                        <Sparkles className="w-4 h-4 text-indigo-500" />
                                    </button>
                                </div>
                                {aiAnalysis && (
                                    <p className="text-[10px] mt-2 text-gray-600 bg-white p-2 rounded border">{aiAnalysis}</p>
                                )}
                            </div>
                        </div>
                    </div>
                    </>
                )}

                {sidebarTab === 'design' && (
                    <>
                        {/* Library of Elements */}

                        {/* 1. Header Styles */}
                        <div>
                             <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 flex items-center">
                                <LayoutTemplate className="w-4 h-4 mr-2" /> Estilo de Cabeçalho
                            </h2>
                            <div className="grid grid-cols-2 gap-3">
                                {headerStyles.map(style => (
                                    <button
                                        key={style.id}
                                        onClick={() => updateDesign('headerStyle', style.id)}
                                        className={`flex items-center p-2 rounded-lg border text-sm transition-all ${config.design.headerStyle === style.id ? 'border-indigo-500 bg-indigo-50 ring-1 ring-indigo-500' : 'border-gray-200 hover:bg-gray-50'}`}
                                    >
                                        <span className="w-6 h-6 flex items-center justify-center bg-gray-100 rounded text-gray-600 font-bold mr-2 text-xs">
                                            {style.icon}
                                        </span>
                                        {style.name}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <hr className="border-gray-200" />

                        {/* 2. Body Styles */}
                        <div>
                             <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 flex items-center">
                                <Grid className="w-4 h-4 mr-2" /> Estilo de Miolo
                            </h2>
                            <div className="grid grid-cols-2 gap-3">
                                {bodyStyles.map(style => (
                                    <button
                                        key={style.id}
                                        onClick={() => updateDesign('bodyStyle', style.id)}
                                        className={`p-2 rounded-lg border text-sm text-center transition-all ${config.design.bodyStyle === style.id ? 'border-indigo-500 bg-indigo-50 ring-1 ring-indigo-500' : 'border-gray-200 hover:bg-gray-50'}`}
                                    >
                                        {style.name}
                                    </button>
                                ))}
                            </div>
                            {config.design.bodyStyle !== 'blank' && (
                                <div className="mt-3">
                                    <label className="block text-xs text-gray-500 mb-1">Espaçamento das linhas</label>
                                    <input 
                                        type="range" 
                                        min="16" 
                                        max="40" 
                                        value={config.design.lineSpacing}
                                        onChange={(e) => updateDesign('lineSpacing', parseInt(e.target.value))}
                                        className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                                    />
                                </div>
                            )}
                        </div>

                        <hr className="border-gray-200" />

                        {/* 3. Typography */}
                        <div>
                            <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 flex items-center">
                                <Type className="w-4 h-4 mr-2" /> Tipografia
                            </h2>
                            <select
                                value={config.design.fontFamily}
                                onChange={(e) => updateDesign('fontFamily', e.target.value)}
                                className="block w-full border-gray-300 rounded-md shadow-sm focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm border p-2"
                            >
                                {fontOptions.map(font => (
                                    <option key={font.name} value={font.value}>{font.name}</option>
                                ))}
                            </select>
                        </div>

                        <hr className="border-gray-200" />

                        {/* 4. Colors */}
                        <div>
                            <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3 flex items-center">
                                <PaintBucket className="w-4 h-4 mr-2" /> Paleta de Cores
                            </h2>
                            <div className="space-y-3">
                                <div className="flex items-center justify-between">
                                    <span className="text-sm text-gray-700">Texto Principal</span>
                                    <div className="flex items-center">
                                        <span className="text-xs text-gray-400 mr-2 uppercase">{config.design.primaryColor}</span>
                                        <input 
                                            type="color" 
                                            value={config.design.primaryColor}
                                            onChange={(e) => updateDesign('primaryColor', e.target.value)}
                                            className="h-8 w-8 rounded cursor-pointer border-0 p-0"
                                        />
                                    </div>
                                </div>
                                <div className="flex items-center justify-between">
                                    <span className="text-sm text-gray-700">Destaques / Feriados</span>
                                    <div className="flex items-center">
                                        <span className="text-xs text-gray-400 mr-2 uppercase">{config.design.accentColor}</span>
                                        <input 
                                            type="color" 
                                            value={config.design.accentColor}
                                            onChange={(e) => updateDesign('accentColor', e.target.value)}
                                            className="h-8 w-8 rounded cursor-pointer border-0 p-0"
                                        />
                                    </div>
                                </div>
                                <div className="flex items-center justify-between">
                                    <span className="text-sm text-gray-700">Linhas / Bordas</span>
                                    <div className="flex items-center">
                                        <span className="text-xs text-gray-400 mr-2 uppercase">{config.design.lineColor}</span>
                                        <input 
                                            type="color" 
                                            value={config.design.lineColor}
                                            onChange={(e) => updateDesign('lineColor', e.target.value)}
                                            className="h-8 w-8 rounded cursor-pointer border-0 p-0"
                                        />
                                    </div>
                                </div>
                                <div className="flex items-center justify-between">
                                    <span className="text-sm text-gray-700">Fundo da Página</span>
                                    <div className="flex items-center">
                                        <span className="text-xs text-gray-400 mr-2 uppercase">{config.design.backgroundColor}</span>
                                        <input 
                                            type="color" 
                                            value={config.design.backgroundColor}
                                            onChange={(e) => updateDesign('backgroundColor', e.target.value)}
                                            className="h-8 w-8 rounded cursor-pointer border-0 p-0"
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </>
                )}

                <div className="md:hidden pt-4">
                    <button 
                        onClick={togglePreview}
                        className="w-full flex items-center justify-center px-4 py-3 border border-transparent text-sm font-medium rounded-md text-indigo-700 bg-indigo-100 hover:bg-indigo-200"
                    >
                        Ver Prévia <ChevronRight className="ml-2 w-4 h-4" />
                    </button>
                </div>

            </div>
        </aside>

        {/* Main Content Area - Preview */}
        <main className={`flex-1 overflow-y-auto bg-gray-100 custom-scrollbar p-4 md:p-8 ${activeTab === 'config' ? 'hidden md:block' : 'block'}`}>

            <div className="max-w-4xl mx-auto">
                {/* Toolbar */}
                <div className="flex justify-between items-center mb-6 no-print">
                    <div className="md:hidden">
                        <button onClick={() => setActiveTab('config')} className="text-sm text-gray-600 hover:text-gray-900 flex items-center">
                            ← Voltar para Configurações
                        </button>
                    </div>
                    <div className="flex items-center space-x-4 ml-auto">
                        <span className="text-sm text-gray-500 hidden sm:inline-block">
                            Total de dias: {generatedData.length}
                        </span>
                        <button 
                            onClick={() => window.print()}
                            className="flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                            <Printer className="w-4 h-4 mr-2" />
                            Imprimir / PDF
                        </button>
                    </div>
                </div>

                {/* Visualization Area */}
                <div id="print-area" className="bg-white shadow-2xl min-h-[29.7cm] p-8 md:p-16 print:shadow-none print:p-0 print:w-full" style={{ fontFamily: config.design.fontFamily }}>

                    {/* Cover / Header Example */}
                    <div className="text-center mb-12 pb-8 border-b-2" style={{ borderColor: config.design.lineColor }}>
                        <h1 className="text-4xl md:text-6xl font-bold mb-2" style={{ color: config.design.primaryColor }}>
                            {config.year}
                        </h1>
                        <p className="uppercase tracking-[0.2em] text-sm" style={{ color: config.design.accentColor }}>
                            Agenda {config.layout === 'daily' ? 'Diária' : 'Semanal'}
                        </p>
                    </div>

                    {/* Grid of Days */}
                    <div className={`grid gap-4 ${config.layout === 'daily' ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'}`}>
                        {/* Rendering a subset for performance in preview, but logic handles all */}
                        {generatedData.slice(0, config.layout === 'daily' ? 6 : 4).map((day) => renderDay(day))}

                        {/* Info for user */}
                        <div className="col-span-full py-12 text-center no-print">
                           <p className="text-gray-400 italic">
                               ... Visualizando apenas os primeiros dias para performance ...<br/>
                               Use o botão "Imprimir / PDF" para gerar o documento completo.
                           </p>
                        </div>
                    </div>

                    {/* Hidden div that contains everything only for print media */}
                    <div className="hidden print-only">
                         <div className={`grid gap-8 ${config.layout === 'daily' ? 'grid-cols-1' : 'grid-cols-1'}`}>
                             {generatedData.slice(0, 31).map((day, idx) => (
                                 <div key={`print-${idx}`} className={`${idx > 0 && idx % 2 === 0 ? 'page-break' : ''}`}>
                                    {renderDay(day)}
                                 </div>
                             ))}
                         </div>
                    </div>

                </div>
            </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string;
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados
export type ElementType = 'day_number' | 'day_name' | 'month_name' | 'year' | 'lines' | 'box' | 'quote' | 'moon' | 'holiday';

export interface LayoutElement {
  id: string;
  type: ElementType;
  x: number; // Posição X em % (0-100) para ser responsivo na impressão
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string;
    backgroundColor?: string;
    borderColor?: string;
    borderWidth?: number;
    textAlign?: 'left' | 'center' | 'right';
    lineSpacing?: number; // Para elementos do tipo 'lines'
  };
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_with_weekend';

export interface AgendaConfig {
  year: number;
  layoutType: PageLayoutType;
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  elements: LayoutElement[]; // Lista de elementos que compõem o template do dia
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import React, { useState, useEffect, useRef } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType } from '../types';
import { generateCalendarYear, getMonthName, getDayName } from '../services/calendarService';
import { generateMonthlyQuotes } from '../services/geminiService';
import { 
  Calendar, Printer, LogOut, Moon, Type, GripHorizontal, 
  Plus, Trash2, Move, AlignLeft, AlignCenter, AlignRight, Layout
} from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

// Default templates
const getDefaultElements = (): LayoutElement[] => [
  { id: '1', type: 'day_number', x: 5, y: 5, w: 15, h: 10, style: { fontSize: 48, fontWeight: 'bold', color: '#1f2937', textAlign: 'left' } },
  { id: '2', type: 'month_name', x: 22, y: 8, w: 30, h: 5, style: { fontSize: 14, fontWeight: 'normal', color: '#6b7280', textAlign: 'left' } },
  { id: '3', type: 'day_name', x: 70, y: 8, w: 25, h: 5, style: { fontSize: 14, fontWeight: '600', color: '#4b5563', textAlign: 'right' } },
  { id: '4', type: 'lines', x: 5, y: 20, w: 90, h: 70, style: { color: '#e5e7eb', lineSpacing: 24 } }
];

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layoutType: '1_per_page',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    elements: getDefaultElements()
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');

  // Dragging state
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; initialEleX: number; initialEleY: number } | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Generate data
  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  // --- Element Management ---

  const addElement = (type: ElementType) => {
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      x: 40,
      y: 40,
      w: 20,
      h: 10,
      style: {
        fontSize: 16,
        color: '#000000',
        textAlign: 'left',
        lineSpacing: 24,
        borderColor: '#000000',
        borderWidth: 1
      }
    };

    // Defaults based on type
    if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; }
    if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; }
    if (type === 'day_number') { newElement.w = 15; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; }

    setConfig(prev => ({ ...prev, elements: [...prev.elements, newElement] }));
    setSelectedId(newElement.id);
  };

  const removeElement = (id: string) => {
    setConfig(prev => ({ ...prev, elements: prev.elements.filter(e => e.id !== id) }));
    setSelectedId(null);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e)
    }));
  };

  // --- Drag Logic ---

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const element = config.elements.find(el => el.id === id);
    if (!element || !editorRef.current) return;

    setSelectedId(id);
    setIsDragging(true);

    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialEleX: element.x,
      initialEleY: element.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current || !selectedId || !editorRef.current) return;

    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaXPixels = e.clientX - dragRef.current.startX;
    const deltaYPixels = e.clientY - dragRef.current.startY;

    // Convert pixels to percentage based on editor size
    const deltaXPercent = (deltaXPixels / editorRect.width) * 100;
    const deltaYPercent = (deltaYPixels / editorRect.height) * 100;

    let newX = dragRef.current.initialEleX + deltaXPercent;
    let newY = dragRef.current.initialEleY + deltaYPercent;

    // Snap to grid (optional, simple 1% snap)
    newX = Math.round(newX);
    newY = Math.round(newY);

    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(el => 
        el.id === selectedId ? { ...el, x: newX, y: newY } : el
      )
    }));
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  // --- Rendering Helpers ---

  // Renders a single "Day Module" (the template)
  const renderTemplate = (day: DayData | null, isEditor: boolean = false, scale: number = 1) => {
    // If day is null, we are just rendering the template structure (for editor bg or blank spaces)
    const d = day || {
      dayOfMonth: 24,
      month: 7,
      year: 2025,
      dayOfWeek: 3,
      holiday: 'Exemplo de Feriado',
      moonPhase: '🌕 Cheia',
      date: new Date()
    } as DayData;

    return (
      <div 
        ref={isEditor ? editorRef : null}
        className={`relative bg-white shadow-sm overflow-hidden ${isEditor ? 'w-full h-full' : 'w-full h-full'}`}
        style={{ 
          // A5 Aspect Ratio approx 1:1.41
          aspectRatio: isEditor ? '1 / 1.414' : 'auto', 
        }}
        onMouseMove={isEditor ? handleMouseMove : undefined}
        onMouseUp={isEditor ? handleMouseUp : undefined}
        onMouseLeave={isEditor ? handleMouseUp : undefined}
      >
        {isEditor && (
           // Grid Background for Editor
           <div className="absolute inset-0 pointer-events-none opacity-10" 
                style={{ 
                  backgroundImage: 'linear-gradient(#000 1px, transparent 1px), linear-gradient(90deg, #000 1px, transparent 1px)', 
                  backgroundSize: '5% 5%' 
                }}>
           </div>
        )}

        {config.elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;

          let content: React.ReactNode = '';

          switch (el.type) {
            case 'day_number': content = d.dayOfMonth; break;
            case 'month_name': content = getMonthName(d.month); break;
            case 'day_name': content = getDayName(d.dayOfWeek); break;
            case 'year': content = d.year; break;
            case 'moon': content = d.moonPhase || (isEditor ? 'Lua' : ''); break;
            case 'holiday': content = d.holiday || (isEditor ? 'Feriado' : ''); break;
            case 'quote': content = config.includeQuotes && quotes[d.month] ? `"${quotes[d.month]}"` : (isEditor ? '"Frase Motivacional"' : ''); break;
            case 'lines': 
              const lineCount = Math.floor((el.h / 100 * (isEditor ? 800 : 1000)) / (el.style.lineSpacing || 24)); // Approx height calc
              content = Array(Math.max(2, lineCount)).fill(0).map((_, i) => (
                <div key={i} className="w-full border-b" style={{ height: el.style.lineSpacing, borderColor: el.style.color }}></div>
              ));
              break;
            case 'box':
               content = <div className="w-full h-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}` }}></div>;
               break;
          }

          if (el.type === 'lines') {
              return (
                <div
                    key={el.id}
                    onMouseDown={(e) => handleMouseDown(e, el.id)}
                    className={`absolute ${isSelected ? 'ring-2 ring-indigo-500 cursor-move z-50' : ''}`}
                    style={{
                        left: `${el.x}%`,
                        top: `${el.y}%`,
                        width: `${el.w}%`,
                        height: `${el.h}%`,
                    }}
                >
                    <div className="w-full h-full overflow-hidden flex flex-col">
                        {content}
                    </div>
                </div>
              );
          }

          return (
            <div
              key={el.id}
              onMouseDown={(e) => handleMouseDown(e, el.id)}
              className={`absolute flex items-center ${isSelected ? 'ring-2 ring-indigo-500 cursor-move z-50' : ''}`}
              style={{
                left: `${el.x}%`,
                top: `${el.y}%`,
                width: `${el.w}%`,
                height: `${el.h}%`,
                ...el.style,
                // Adjust justifyContent based on textAlign
                justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start')
              }}
            >
              {content}
            </div>
          );
        })}
      </div>
    );
  };

  // --- Preview & Print Logic ---

  const renderPrintLayout = () => {
    // Logic to group days into pages based on layoutType
    const pages: React.ReactNode[] = [];
    const days = generatedData;

    if (config.layoutType === '1_per_page') {
        days.forEach(day => {
            pages.push(
                <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white p-8 mb-8 shadow print:shadow-none print:mb-0 print:break-after-page relative box-border overflow-hidden">
                    {renderTemplate(day, false)}
                </div>
            );
        });
    } 
    else if (config.layoutType === '2_per_page') {
        for (let i = 0; i < days.length; i += 2) {
            pages.push(
                <div key={i} className="w-full h-[210mm] bg-white p-8 mb-8 shadow print:shadow-none print:mb-0 print:break-after-page flex flex-col gap-4 box-border">
                    <div className="flex-1 border-b border-dashed border-gray-300 pb-4 relative overflow-hidden">
                         {renderTemplate(days[i], false)}
                    </div>
                    <div className="flex-1 pt-4 relative overflow-hidden">
                         {days[i+1] ? renderTemplate(days[i+1], false) : null}
                    </div>
                </div>
            );
        }
    }
    else if (config.layoutType === '1_per_page_with_weekend') {
        // Mon-Fri = 1 page. Sat+Sun = 1 page.
        let i = 0;
        while (i < days.length) {
            const day = days[i];
            const isWeekend = day.dayOfWeek === 6; // Saturday

            if (isWeekend) {
                // Render Sat & Sun on one page
                pages.push(
                    <div key={`we-${i}`} className="w-full h-[210mm] bg-white p-8 mb-8 shadow print:shadow-none print:mb-0 print:break-after-page flex flex-col gap-4 box-border">
                        <div className="flex-1 border-b border-dashed border-gray-300 pb-4 relative overflow-hidden">
                            {renderTemplate(day, false)}
                        </div>
                        <div className="flex-1 pt-4 relative overflow-hidden">
                            {days[i+1] ? renderTemplate(days[i+1], false) : null}
                        </div>
                    </div>
                );
                i += 2; // Skip Sat and Sun
            } else {
                // Weekday
                pages.push(
                    <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white p-8 mb-8 shadow print:shadow-none print:mb-0 print:break-after-page relative box-border overflow-hidden">
                         {renderTemplate(day, false)}
                    </div>
                );
                i += 1;
            }
        }
    }

    return pages;
  };

  const selectedElement = config.elements.find(e => e.id === selectedId);

  return (
    <div className="h-screen flex flex-col bg-gray-100 overflow-hidden">
      {/* Top Bar */}
      <header className="bg-white border-b border-gray-200 h-14 flex items-center justify-between px-4 z-20 shrink-0">
        <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-1.5 rounded">
                <Calendar className="h-4 w-4 text-white" />
            </div>
            <span className="font-bold text-gray-800">AgendaMaster AI</span>
            <span className="px-2 py-0.5 rounded-full bg-gray-100 text-xs text-gray-500 border border-gray-200">Editor Visual</span>
        </div>

        <div className="flex items-center space-x-2 bg-gray-100 p-1 rounded-lg">
            <button 
                onClick={() => setActiveTab('editor')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'editor' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Editar Template
            </button>
            <button 
                onClick={() => setActiveTab('preview')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'preview' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Visualizar & Imprimir
            </button>
        </div>

        <div className="flex items-center space-x-3">
             <button onClick={() => window.print()} className="flex items-center text-xs font-medium text-gray-700 hover:text-indigo-600">
                <Printer className="w-4 h-4 mr-1" /> Imprimir
             </button>
             <button onClick={onLogout} className="text-gray-400 hover:text-red-500">
                <LogOut className="w-4 h-4" />
             </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">

        {/* LEFT SIDEBAR: Tools & Config */}
        <aside className="w-64 bg-white border-r border-gray-200 flex flex-col shrink-0 z-10 no-print">
            <div className="p-4 border-b border-gray-100">
                <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3">Layout da Página</h3>
                <div className="space-y-2">
                    <button 
                        onClick={() => setConfig(c => ({...c, layoutType: '1_per_page'}))}
                        className={`w-full text-left px-3 py-2 text-xs rounded-md border flex items-center ${config.layoutType === '1_per_page' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-200 hover:bg-gray-50'}`}
                    >
                        <Layout className="w-3 h-3 mr-2" /> 1 Dia por Pág.
                    </button>
                    <button 
                        onClick={() => setConfig(c => ({...c, layoutType: '2_per_page'}))}
                        className={`w-full text-left px-3 py-2 text-xs rounded-md border flex items-center ${config.layoutType === '2_per_page' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-200 hover:bg-gray-50'}`}
                    >
                        <Layout className="w-3 h-3 mr-2" /> 2 Dias por Pág.
                    </button>
                    <button 
                        onClick={() => setConfig(c => ({...c, layoutType: '1_per_page_with_weekend'}))}
                        className={`w-full text-left px-3 py-2 text-xs rounded-md border flex items-center ${config.layoutType === '1_per_page_with_weekend' ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-200 hover:bg-gray-50'}`}
                    >
                         <Layout className="w-3 h-3 mr-2" /> 1 Dia + FDS Junto
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3">Elementos</h3>
                <div className="grid grid-cols-2 gap-2">
                    <button onClick={() => addElement('day_number')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <span className="text-xl font-bold text-gray-800">24</span>
                        <span className="text-[10px] text-gray-500 mt-1">Dia (Nº)</span>
                    </button>
                    <button onClick={() => addElement('day_name')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <Type className="w-5 h-5 text-gray-600" />
                        <span className="text-[10px] text-gray-500 mt-1">Dia (Nome)</span>
                    </button>
                    <button onClick={() => addElement('month_name')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <span className="text-sm font-semibold text-gray-600">Jan</span>
                        <span className="text-[10px] text-gray-500 mt-1">Mês</span>
                    </button>
                    <button onClick={() => addElement('lines')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <div className="w-6 h-4 border-b-2 border-dashed border-gray-400 mb-1"></div>
                        <span className="text-[10px] text-gray-500">Pauta</span>
                    </button>
                     <button onClick={() => addElement('box')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <div className="w-5 h-5 border border-gray-400 mb-1 bg-gray-100"></div>
                        <span className="text-[10px] text-gray-500">Caixa</span>
                    </button>
                    <button onClick={() => addElement('moon')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <Moon className="w-5 h-5 text-gray-600" />
                        <span className="text-[10px] text-gray-500 mt-1">Lua</span>
                    </button>
                    <button onClick={() => addElement('holiday')} className="flex flex-col items-center justify-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 hover:border-indigo-300 transition-all">
                        <span className="text-xs text-red-500 font-bold">FER</span>
                        <span className="text-[10px] text-gray-500 mt-1">Feriado</span>
                    </button>
                </div>

                <hr className="my-4 border-gray-200"/>

                <div className="bg-indigo-50 p-3 rounded-lg border border-indigo-100">
                    <h4 className="text-xs font-bold text-indigo-700 mb-2">Opções Avançadas</h4>
                    <label className="flex items-center space-x-2 mb-2">
                        <input type="checkbox" checked={config.includeHolidays} onChange={(e) => setConfig(c => ({...c, includeHolidays: e.target.checked}))} className="rounded text-indigo-600" />
                        <span className="text-xs text-gray-600">Gerar Feriados</span>
                    </label>
                    <label className="flex items-center space-x-2">
                         <input type="checkbox" checked={config.includeQuotes} onChange={(e) => setConfig(c => ({...c, includeQuotes: e.target.checked}))} className="rounded text-indigo-600" />
                        <span className="text-xs text-gray-600">Gerar Frases (IA)</span>
                    </label>
                </div>
            </div>
        </aside>

        {/* MAIN AREA */}
        <main className="flex-1 bg-gray-100 overflow-hidden relative flex flex-col items-center">

            {activeTab === 'editor' && (
                <div className="flex-1 w-full flex items-center justify-center p-8 overflow-auto custom-scrollbar">
                    {/* The Canvas - Simulating A5 proportions for the template */}
                    <div className="relative shadow-2xl bg-white" style={{ width: '400px', height: '565px' }}>
                        {renderTemplate(null, true)}

                        <div className="absolute -top-6 left-0 text-xs text-gray-400">Template (A5)</div>
                        <div className="absolute -bottom-6 right-0 text-xs text-gray-400 w-full text-center">
                            Arraste os elementos para posicionar
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'preview' && (
                <div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar">
                    <div className="max-w-[210mm] mx-auto">
                        <div id="print-area">
                             {/* Generates all pages */}
                             {generatedData.length === 0 ? (
                                 <div className="text-center py-20 text-gray-500">Carregando visualização...</div>
                             ) : (
                                 // Render only first 6 pages for preview performance, unless printing
                                 <div className="space-y-8">
                                    <div className="p-4 bg-yellow-50 border border-yellow-200 text-yellow-800 text-sm rounded mb-4 no-print text-center">
                                        Visualização parcial (primeiras páginas). Clique em <b>Imprimir</b> para gerar o PDF completo.
                                    </div>
                                    <div className="print-only hidden">
                                         {renderPrintLayout()}
                                    </div>
                                    <div className="no-print">
                                         {renderPrintLayout().slice(0, 4)}
                                    </div>
                                 </div>
                             )}
                        </div>
                    </div>
                </div>
            )}
        </main>

        {/* RIGHT SIDEBAR: Properties */}
        {activeTab === 'editor' && (
            <aside className="w-64 bg-white border-l border-gray-200 flex flex-col shrink-0 z-10 no-print">
                <div className="p-4 border-b border-gray-100">
                     <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Propriedades</h3>
                </div>

                {selectedElement ? (
                    <div className="p-4 space-y-4 overflow-y-auto">
                         <div className="text-xs text-gray-500 mb-2 font-mono bg-gray-50 p-1 rounded">
                             ID: {selectedElement.type}
                         </div>

                         {/* Common Styles */}
                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">Tamanho da Fonte</label>
                             <input 
                                type="number" 
                                value={selectedElement.style.fontSize} 
                                onChange={(e) => updateElementStyle(selectedElement.id, { fontSize: parseInt(e.target.value) })}
                                className="w-full border border-gray-300 rounded p-1 text-sm"
                             />
                         </div>

                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">Cor</label>
                             <div className="flex space-x-2">
                                 <input 
                                    type="color" 
                                    value={selectedElement.style.color || '#000000'}
                                    onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })}
                                    className="h-8 w-8 rounded cursor-pointer p-0 border-0"
                                 />
                                 <input 
                                    type="text" 
                                    value={selectedElement.style.color}
                                    onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })}
                                    className="flex-1 border border-gray-300 rounded p-1 text-sm uppercase"
                                 />
                             </div>
                         </div>

                         <div>
                             <label className="block text-xs font-medium text-gray-700 mb-1">Alinhamento</label>
                             <div className="flex border border-gray-300 rounded overflow-hidden">
                                 <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'left' })} className={`flex-1 p-2 hover:bg-gray-50 ${selectedElement.style.textAlign === 'left' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignLeft className="w-4 h-4 mx-auto"/></button>
                                 <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'center' })} className={`flex-1 p-2 hover:bg-gray-50 ${selectedElement.style.textAlign === 'center' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignCenter className="w-4 h-4 mx-auto"/></button>
                                 <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'right' })} className={`flex-1 p-2 hover:bg-gray-50 ${selectedElement.style.textAlign === 'right' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignRight className="w-4 h-4 mx-auto"/></button>
                             </div>
                         </div>

                         {/* Specific Styles */}
                         {selectedElement.type === 'lines' && (
                             <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">Espaçamento das Linhas</label>
                                <input 
                                    type="range" min="10" max="60"
                                    value={selectedElement.style.lineSpacing}
                                    onChange={(e) => updateElementStyle(selectedElement.id, { lineSpacing: parseInt(e.target.value) })}
                                    className="w-full"
                                />
                             </div>
                         )}

                         {(selectedElement.type === 'box' || selectedElement.type === 'day_number') && (
                             <>
                                <div>
                                    <label className="block text-xs font-medium text-gray-700 mb-1">Cor de Fundo</label>
                                    <div className="flex items-center space-x-2">
                                        <input type="checkbox" checked={!!selectedElement.style.backgroundColor} onChange={(e) => updateElementStyle(selectedElement.id, { backgroundColor: e.target.checked ? '#f3f4f6' : 'transparent' })} />
                                        <span className="text-xs">Ativar</span>
                                        {selectedElement.style.backgroundColor && selectedElement.style.backgroundColor !== 'transparent' && (
                                             <input type="color" value={selectedElement.style.backgroundColor} onChange={(e) => updateElementStyle(selectedElement.id, { backgroundColor: e.target.value })} className="h-6 w-6 rounded border-0 p-0" />
                                        )}
                                    </div>
                                </div>
                             </>
                         )}

                         <hr className="my-2 border-gray-100" />

                         <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">Largura (%)</label>
                                <input 
                                    type="number" 
                                    value={Math.round(selectedElement.w)} 
                                    onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el)}))}
                                    className="w-full border border-gray-300 rounded p-1 text-sm"
                                />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-700 mb-1">Altura (%)</label>
                                <input 
                                    type="number" 
                                    value={Math.round(selectedElement.h)} 
                                    onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el)}))}
                                    className="w-full border border-gray-300 rounded p-1 text-sm"
                                />
                            </div>
                         </div>

                         <button 
                            onClick={() => removeElement(selectedElement.id)}
                            className="w-full mt-6 py-2 px-4 bg-red-50 text-red-600 rounded hover:bg-red-100 flex items-center justify-center text-sm transition-colors"
                         >
                             <Trash2 className="w-4 h-4 mr-2" /> Remover Elemento
                         </button>
                    </div>
                ) : (
                    <div className="p-8 text-center text-gray-400">
                        <Move className="w-12 h-12 mx-auto mb-2 opacity-20" />
                        <p className="text-sm">Selecione um elemento no layout para editar suas propriedades.</p>
                    </div>
                )}
            </aside>
        )}

      </div>
    </div>
  );
};

export default Dashboard;

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados para a página
export type ElementType = 
  | 'day_number' 
  | 'day_name' 
  | 'month_name' 
  | 'year' 
  | 'lines' 
  | 'box' 
  | 'circle' 
  | 'quote' 
  | 'moon' 
  | 'holiday' 
  | 'habit_tracker' 
  | 'vector_flower' 
  | 'note_grid';

export interface LayoutElement {
  id: string;
  type: ElementType;
  x: number; // Posição X em % (0-100) relativo à área útil da página
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  zIndex: number;
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string; // Cor do texto ou preenchimento
    backgroundColor?: string;
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    lineSpacing?: number; // Para pautas
    rotation?: number; // Em graus
  };
}

export interface PageMargins {
  top: number;    // mm
  bottom: number; // mm
  left: number;   // mm
  right: number;  // mm
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_weekend_shared';

export interface AgendaConfig {
  year: number;
  layoutType: PageLayoutType;
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  margins: PageMargins;
  elements: LayoutElement[]; // Lista de elementos que compõem o template do dia
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import React, { useState, useEffect, useRef } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType } from '../types';
import { generateCalendarYear, getMonthName, getDayName } from '../services/calendarService';
import { generateMonthlyQuotes } from '../services/geminiService';
import { 
  Calendar, Printer, LogOut, Moon, Type, 
  Trash2, Move, AlignLeft, AlignCenter, AlignRight, Layout,
  Square, Circle, Flower, ListTodo, Grid3X3, ArrowDownAZ,
  Maximize, Minimize, Settings2
} from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

// Default template elements
const getDefaultElements = (): LayoutElement[] => [
  { id: '1', type: 'day_number', x: 5, y: 3, w: 15, h: 8, zIndex: 10, style: { fontSize: 42, fontWeight: 'bold', color: '#1f2937', textAlign: 'left' } },
  { id: '2', type: 'day_name', x: 22, y: 5, w: 40, h: 5, zIndex: 10, style: { fontSize: 14, fontWeight: '600', color: '#4b5563', textAlign: 'left',  } },
  { id: '3', type: 'month_name', x: 22, y: 8, w: 30, h: 4, zIndex: 10, style: { fontSize: 12, fontWeight: 'normal', color: '#9ca3af', textAlign: 'left' } },
  { id: '4', type: 'lines', x: 5, y: 18, w: 90, h: 75, zIndex: 5, style: { color: '#e5e7eb', lineSpacing: 24 } }
];

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layoutType: '1_per_page',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    margins: { top: 15, bottom: 15, left: 15, right: 15 },
    elements: getDefaultElements()
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');

  // Dragging state
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; initialEleX: number; initialEleY: number } | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Generate data
  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  // --- Element Management ---

  const addElement = (type: ElementType) => {
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      x: 35,
      y: 40,
      w: 20,
      h: 10,
      zIndex: config.elements.length + 1,
      style: {
        fontSize: 14,
        color: '#000000',
        textAlign: 'left',
        lineSpacing: 24,
        borderColor: '#000000',
        borderWidth: 1,
        backgroundColor: 'transparent',
        rotation: 0,
        opacity: 1
      }
    };

    // Defaults based on type
    if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
    if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
    if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
    if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
    if (type === 'vector_flower') { newElement.w = 20; newElement.h = 20; newElement.style.color = '#e5e7eb'; newElement.style.borderWidth = 0; }
    if (type === 'habit_tracker') { newElement.w = 40; newElement.h = 15; newElement.style.borderWidth = 1; newElement.style.borderColor = '#d1d5db'; }
    if (type === 'note_grid') { newElement.w = 40; newElement.h = 20; newElement.style.opacity = 0.5; newElement.style.borderWidth = 0; }

    setConfig(prev => ({ ...prev, elements: [...prev.elements, newElement] }));
    setSelectedId(newElement.id);
  };

  const removeElement = (id: string) => {
    setConfig(prev => ({ ...prev, elements: prev.elements.filter(e => e.id !== id) }));
    setSelectedId(null);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e)
    }));
  };

  const updateConfig = (key: string, value: any) => {
      // Helper for deep updates
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          setConfig(prev => ({
              ...prev,
              [parent]: {
                  ...prev[parent as keyof AgendaConfig] as any,
                  [child]: value
              }
          }));
      } else {
          setConfig(prev => ({ ...prev, [key]: value }));
      }
  }

  // --- Drag Logic ---

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const element = config.elements.find(el => el.id === id);
    if (!element || !editorRef.current) return;

    setSelectedId(id);
    setIsDragging(true);

    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialEleX: element.x,
      initialEleY: element.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current || !selectedId || !editorRef.current) return;

    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaXPixels = e.clientX - dragRef.current.startX;
    const deltaYPixels = e.clientY - dragRef.current.startY;

    // Convert pixels to percentage based on editor size
    const deltaXPercent = (deltaXPixels / editorRect.width) * 100;
    const deltaYPercent = (deltaYPixels / editorRect.height) * 100;

    let newX = dragRef.current.initialEleX + deltaXPercent;
    let newY = dragRef.current.initialEleY + deltaYPercent;

    // Optional: Snap to grid (0.5%)
    newX = Math.round(newX * 2) / 2;
    newY = Math.round(newY * 2) / 2;

    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(el => 
        el.id === selectedId ? { ...el, x: newX, y: newY } : el
      )
    }));
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  // --- Rendering Helpers ---

  const renderVector = (type: ElementType, style: any) => {
      if (type === 'vector_flower') {
          return (
              <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full" style={{ color: style.color }}>
                  <path d="M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C21 14 24 10.5 24 7.5C24 4.5 22.5 2 20 2C17.5 2 16 4 16 6C16 4 14.5 2 12 2Z" opacity="0.5"/>
              </svg>
          ); // Actually a heart/flower abstraction
      }
      return null;
  }

  // Renders a single "Day Module" (The Template)
  // scale parameter is used to fit the template visually in the sidebar editor
  const renderTemplate = (day: DayData | null, isEditor: boolean = false) => {
    const d = day || {
      dayOfMonth: 24,
      month: 7,
      year: 2025,
      dayOfWeek: 3,
      holiday: 'Feriado Exemplo',
      moonPhase: '🌕',
      date: new Date()
    } as DayData;

    return (
      <div 
        ref={isEditor ? editorRef : null}
        className={`relative overflow-hidden ${isEditor ? 'w-full h-full bg-white shadow-md' : 'w-full h-full'}`}
        style={{ 
            // In editor mode, we rely on parent container sizing. In print mode, it fills the slot.
        }}
        onMouseMove={isEditor ? handleMouseMove : undefined}
        onMouseUp={isEditor ? handleMouseUp : undefined}
        onMouseLeave={isEditor ? handleMouseUp : undefined}
      >
        {isEditor && (
           // Grid Background for Editor
           <div className="absolute inset-0 pointer-events-none opacity-10 z-0" 
                style={{ 
                  backgroundImage: 'linear-gradient(#000 0.5px, transparent 0.5px), linear-gradient(90deg, #000 0.5px, transparent 0.5px)', 
                  backgroundSize: '10% 10%' 
                }}>
           </div>
        )}

        {config.elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;

          let content: React.ReactNode = '';

          switch (el.type) {
            case 'day_number': content = d.dayOfMonth; break;
            case 'month_name': content = getMonthName(d.month); break;
            case 'day_name': content = getDayName(d.dayOfWeek); break;
            case 'year': content = d.year; break;
            case 'moon': content = d.moonPhase || (isEditor ? 'Lua' : ''); break;
            case 'holiday': content = d.holiday || (isEditor ? 'Nome do Feriado' : ''); break;
            case 'quote': content = config.includeQuotes && quotes[d.month] ? `"${quotes[d.month]}"` : (isEditor ? '"Frase Inspiradora"' : ''); break;
            case 'vector_flower': content = renderVector(el.type, el.style); break;

            case 'lines': 
              const lineCount = Math.floor((el.h / 100 * (isEditor ? 600 : 800)) / (el.style.lineSpacing || 24)); 
              content = Array(Math.max(2, lineCount)).fill(0).map((_, i) => (
                <div key={i} className="w-full border-b" style={{ height: el.style.lineSpacing, borderColor: el.style.color }}></div>
              ));
              break;

            case 'box':
               content = <div className="w-full h-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}`, borderRadius: el.style.borderRadius }}></div>;
               break;

            case 'circle':
               content = <div className="w-full h-full rounded-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}` }}></div>;
               break;

            case 'habit_tracker':
               content = (
                   <div className="w-full h-full flex flex-col justify-between" style={{ opacity: el.style.opacity }}>
                       <div className="text-[10px] text-gray-500 mb-1">HÁBITOS</div>
                       <div className="flex-1 grid grid-rows-3 gap-1">
                           {[1,2,3].map(i => (
                               <div key={i} className="flex items-center border-b border-gray-200">
                                   <div className="w-4 h-4 border border-gray-300 rounded mr-2"></div>
                                   <div className="h-2 w-full bg-gray-100 rounded"></div>
                               </div>
                           ))}
                       </div>
                   </div>
               );
               break;

            case 'note_grid':
                content = (
                    <div className="w-full h-full" style={{ 
                        backgroundImage: `radial-gradient(${el.style.color || '#ccc'} 1px, transparent 1px)`,
                        backgroundSize: '15px 15px',
                        opacity: el.style.opacity
                    }}></div>
                )
                break;
          }

          // Common wrapper style
          const wrapperStyle: React.CSSProperties = {
            left: `${el.x}%`,
            top: `${el.y}%`,
            width: `${el.w}%`,
            height: `${el.h}%`,
            zIndex: el.zIndex,
            transform: `rotate(${el.style.rotation || 0}deg)`,
          };

          if (el.type === 'lines' || el.type === 'box' || el.type === 'circle' || el.type === 'vector_flower' || el.type === 'note_grid' || el.type === 'habit_tracker') {
               // Non-text elements
              return (
                <div
                    key={el.id}
                    onMouseDown={(e) => handleMouseDown(e, el.id)}
                    className={`absolute ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`}
                    style={wrapperStyle}
                >
                    <div className="w-full h-full overflow-hidden flex flex-col relative">
                        {content}
                    </div>
                </div>
              );
          }

          // Text elements
          return (
            <div
              key={el.id}
              onMouseDown={(e) => handleMouseDown(e, el.id)}
              className={`absolute flex items-center ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`}
              style={{
                ...wrapperStyle,
                ...el.style,
                justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start')
              }}
            >
              {content}
            </div>
          );
        })}
      </div>
    );
  };

  // --- Preview & Print Logic ---

  const renderPrintLayout = () => {
    const pages: React.ReactNode[] = [];
    const days = generatedData;
    const { margins, layoutType } = config;

    // Convert margins (mm) to CSS padding (approx conversion for screen, standard for print)
    // We use padding on the container div to simulate margins.
    const pagePadding = `${margins.top}mm ${margins.right}mm ${margins.bottom}mm ${margins.left}mm`;

    if (layoutType === '1_per_page') {
        days.forEach(day => {
            pages.push(
                <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}>
                    <div className="w-full h-full relative border border-gray-100 border-dashed print:border-none">
                         {renderTemplate(day, false)}
                    </div>
                </div>
            );
        });
    } 
    else if (layoutType === '2_per_page') {
        // We use the SAME template but rendered twice. The user designs "half a page".
        // Wait, to make it WYSIWYG, the Editor should represent the "Module". 
        // In 2_per_page, the module height is effectively half the printable area.
        for (let i = 0; i < days.length; i += 2) {
            pages.push(
                <div key={i} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}>
                    <div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden">
                         {renderTemplate(days[i], false)}
                    </div>
                    <div className="flex-1 relative pt-2 overflow-hidden">
                         {days[i+1] ? renderTemplate(days[i+1], false) : null}
                    </div>
                </div>
            );
        }
    }
    else if (layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < days.length) {
            const day = days[i];
            const isWeekend = day.dayOfWeek === 6; // Saturday

            if (isWeekend) {
                // Render Sat & Sun on one page
                pages.push(
                    <div key={`we-${i}`} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}>
                        <div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden">
                            {renderTemplate(day, false)}
                        </div>
                        <div className="flex-1 relative pt-2 overflow-hidden">
                            {days[i+1] ? renderTemplate(days[i+1], false) : null}
                        </div>
                    </div>
                );
                i += 2;
            } else {
                // Weekday - Full Page
                pages.push(
                    <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}>
                         {renderTemplate(day, false)}
                    </div>
                );
                i += 1;
            }
        }
    }

    return pages;
  };

  const selectedElement = config.elements.find(e => e.id === selectedId);

