];

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layoutType: '1_per_page',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    margins: { top: 15, bottom: 15, left: 15, right: 15 },
    elements: getDefaultElements()
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showMargins, setShowMargins] = useState(true);
  const [customFonts, setCustomFonts] = useState<string[]>([]);

  // Editor View State (Weekday vs Weekend for shared layouts)
  const [editorViewMode, setEditorViewMode] = useState<'standard' | 'weekend'>('standard');

  // Dragging state
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; initialEleX: number; initialEleY: number } | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Generate data
  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  // Load quotes if enabled
  useEffect(() => {
    if (config.includeQuotes && quotes.length === 0) {
       generateMonthlyQuotes(config.year).then(setQuotes);
    }
  }, [config.includeQuotes, config.year]);

  // --- Font Management ---
  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const fontData = event.target?.result as string;
          const fontName = file.name.split('.')[0].replace(/[^a-zA-Z0-9]/g, '');

          // Create FontFace API object
          const newFont = new FontFace(fontName, `url(${fontData})`);

          newFont.load().then((loadedFont) => {
              (document.fonts as any).add(loadedFont);
              setCustomFonts(prev => [...prev, fontName]);
              // Apply to selected element immediately
              if (selectedId) {
                  updateElementStyle(selectedId, { fontFamily: fontName });
              }
          }).catch(err => {
              console.error("Failed to load font:", err);
              alert("Erro ao carregar a fonte. Verifique se é um arquivo válido (TTF, OTF, WOFF).");
          });
      };
      reader.readAsDataURL(file);
  };

  // --- Element Management ---

  const addElement = (type: ElementType, label: string) => {
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      name: `${label} ${config.elements.length + 1}`,
      x: 35,
      y: 40,
      w: 20,
      h: 10,
      zIndex: config.elements.length + 1,
      style: {
        fontSize: 14,
        color: '#000000',
        textAlign: 'left',
        lineSpacing: 24,
        borderColor: '#000000',
        borderWidth: 1,
        backgroundColor: 'transparent',
        rotation: 0,
        opacity: 1,
        flipX: false,
        flipY: false,
        fontFamily: 'Inter',
        // Defaults for specific types
        showTimes: false,
        startHour: 7
      }
    };

    // Defaults based on type
    if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
    if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
    if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
    if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
    if (type === 'text') { newElement.w = 30; newElement.h = 8; newElement.style.fontSize = 16; newElement.style.borderWidth = 0; }
    if (type === 'holiday') { newElement.w = 40; newElement.h = 5; newElement.style.fontSize = 10; newElement.style.color = '#ef4444'; newElement.style.borderWidth = 0; newElement.style.fontWeight = '500'; }

    if (type === 'moon') { 
        newElement.w = 20; // Slightly wider for text + icon
        newElement.h = 5; 
        newElement.style.fontSize = 12; 
        newElement.style.color = '#6b7280'; 
        newElement.style.borderWidth = 0; 
    }

    if (type === 'vector_flower') { 
        newElement.w = 20; 
        newElement.h = 20; 
        newElement.style.color = '#1f2937'; // Stroke
        newElement.style.backgroundColor = '#e5e7eb'; // Fill
        newElement.style.borderWidth = 0; 
    }
    if (type === 'habit_tracker') { newElement.w = 40; newElement.h = 15; newElement.style.borderWidth = 1; newElement.style.borderColor = '#d1d5db'; }
    if (type === 'note_grid') { newElement.w = 40; newElement.h = 20; newElement.style.opacity = 0.5; newElement.style.borderWidth = 0; }

    // Auto-enable config flags if adding specific elements
    if (type === 'holiday') setConfig(prev => ({ ...prev, includeHolidays: true }));
    if (type === 'moon') setConfig(prev => ({ ...prev, includeMoonPhases: true }));
    if (type === 'quote') setConfig(prev => ({ ...prev, includeQuotes: true }));

    setConfig(prev => ({ ...prev, elements: [...prev.elements, newElement] }));
    setSelectedId(newElement.id);
  };

  const removeElement = (id: string) => {
    setConfig(prev => ({ ...prev, elements: prev.elements.filter(e => e.id !== id) }));
    setSelectedId(null);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e)
    }));
  };

  const updateElementName = (id: string, name: string) => {
    setConfig(prev => ({
        ...prev,
        elements: prev.elements.map(e => e.id === id ? { ...e, name } : e)
    }));
  };

  const updateConfig = (key: string, value: any) => {
      // Helper for deep updates
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          setConfig(prev => ({
              ...prev,
              [parent]: {
                  ...prev[parent as keyof AgendaConfig] as any,
                  [child]: value
              }
          }));
      } else {
          setConfig(prev => ({ ...prev, [key]: value }));
      }
  }

  // --- Drag Logic ---

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const element = config.elements.find(el => el.id === id);
    if (!element) return;

    setSelectedId(id);
    setIsDragging(true);

    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialEleX: element.x,
      initialEleY: element.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current || !selectedId) return;

    if (!editorRef.current) return;

    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaXPixels = e.clientX - dragRef.current.startX;
    const deltaYPixels = e.clientY - dragRef.current.startY;

    // Convert pixels to percentage based on editor size
    const deltaXPercent = (deltaXPixels / editorRect.width) * 100;
    const deltaYPercent = (deltaYPixels / editorRect.height) * 100;

    let newX = dragRef.current.initialEleX + deltaXPercent;
    let newY = dragRef.current.initialEleY + deltaYPercent;

    // Optional: Snap to grid (0.5%)
    newX = Math.round(newX * 2) / 2;
    newY = Math.round(newY * 2) / 2;

    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(el => 
        el.id === selectedId ? { ...el, x: newX, y: newY } : el
      )
    }));
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  // --- Rendering Helpers ---

  const renderMoonIcon = (phase: string, color: string) => {
      const p = phase.toLowerCase();
      // Using currentColor via style prop of parent usually, but explicit color passed here
      if (p.includes('nova')) {
          return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
      }
      if (p.includes('cheia')) {
          return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><circle cx="12" cy="12" r="10"/></svg>;
      }
      if (p.includes('crescente')) {
          return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C14.5 22 17 20 17 12C17 4 14.5 2 12 2Z"/></svg>; 
          // Simplified crescent shape
          return (
             <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none">
                 <path d="M12 3a9 9 0 1 0 0 18 7 7 0 0 1 0-14 7 7 0 0 1 0-4z" />
             </svg>
          )
      }
      if (p.includes('minguante')) {
          return (
             <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none">
                 <path d="M12 3a7 7 0 0 0 0 14 7 7 0 0 0 0 4 9 9 0 1 1 0-18z" />
             </svg>
          )
      }
      // Default circle
      return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
  }

  const renderVector = (type: ElementType, style: any) => {
      if (type === 'vector_flower') {
          return (
              <svg 
                viewBox="0 0 24 24" 
                className="w-full h-full" 
                style={{ overflow: 'visible' }}
              >
                  <path 
                    d="M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C21 14 24 10.5 24 7.5C24 4.5 22.5 2 20 2C17.5 2 16 4 16 6C16 4 14.5 2 12 2Z" 
                    fill={style.backgroundColor || 'transparent'}
                    stroke={style.color || 'none'}
                    strokeWidth="1.5"
                    strokeLinejoin="round"
                  />
              </svg>
          ); 
      }
      return null;
  }

  // Renders a single "Day Module" (The Template)
  // attachRef: should we attach the editorRef to this specific instance? 
  // In 2-up view, we attach it to the Top one usually for calculation reference.
  const renderTemplate = (day: DayData | null, isEditor: boolean = false, attachRef: boolean = false) => {
    const d = day || {
      dayOfMonth: 24,
      month: 7,
      year: config.year, 
      dayOfWeek: 3,
      holiday: 'Feriado Exemplo',
      moonPhase: 'Lua cheia',
      date: new Date()
    } as DayData;

    return (
      <div 
        ref={attachRef ? editorRef : null}
        className={`relative overflow-hidden ${isEditor ? 'w-full h-full' : 'w-full h-full'}`}
        onMouseMove={isEditor ? handleMouseMove : undefined}
        onMouseUp={isEditor ? handleMouseUp : undefined}
        onMouseLeave={isEditor ? handleMouseUp : undefined}
      >
        {config.elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;

          let content: React.ReactNode = '';

          switch (el.type) {
            case 'day_number': content = d.dayOfMonth; break;
            case 'month_name': content = getMonthName(d.month); break;
            case 'day_name': content = getDayName(d.dayOfWeek); break;
            case 'year': content = d.year; break;
            case 'holiday': content = d.holiday || (isEditor ? 'Nome do Feriado' : ''); break;
            case 'text': content = (isEditor ? 'Texto Livre' : ''); break;
            case 'quote': content = config.includeQuotes && quotes[d.month] ? `"${quotes[d.month]}"` : (isEditor ? '"Frase Inspiradora"' : ''); break;
            case 'vector_flower': content = renderVector(el.type, el.style); break;

            case 'moon': 
                // Special handling for Moon: Vector + Text
                const phase = d.moonPhase || (isEditor ? 'Lua cheia' : '');
                if (phase) {
                    content = (
                        <div className="flex items-center gap-1.5 h-full">
                            <div className="shrink-0" style={{ width: el.style.fontSize, height: el.style.fontSize }}>
                                {renderMoonIcon(phase, el.style.color || '#000')}
                            </div>
                            <span className="whitespace-nowrap">{phase}</span>
                        </div>
                    );
                }
                break;

            case 'lines': 
              // Calculate available lines based on height
              const lineCount = Math.floor((el.h / 100 * (isEditor ? 600 : 800)) / (el.style.lineSpacing || 24)); 
              const startHour = el.style.startHour || 7;

              content = Array(Math.max(2, lineCount)).fill(0).map((_, i) => (
                <div key={i} className="w-full border-b relative" style={{ height: el.style.lineSpacing, borderColor: el.style.color }}>
                     {el.style.showTimes && (
                         <span 
                            className="absolute -top-2 left-0 text-[10px] font-mono text-gray-500 bg-white/50 pr-1"
                            style={{ fontSize: (el.style.fontSize ? el.style.fontSize * 0.7 : 10) }}
                         >
                             {String(startHour + i).padStart(2, '0')}:00
                         </span>
                     )}
                </div>
              ));
              break;

            case 'box':
               content = <div className="w-full h-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}`, borderRadius: el.style.borderRadius }}></div>;
               break;

            case 'circle':
               content = <div className="w-full h-full rounded-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}` }}></div>;
               break;

            case 'habit_tracker':
               // Dynamic Habit Tracker: Rows depend on height
               // Assume approx 20px per row for calculation
               const habitRowHeight = 20;
               const estimatedHeight = (el.h / 100 * (isEditor ? 600 : 800));
               // Reserve space for Header "HABITOS" (approx 20px)
               const availableHeight = Math.max(0, estimatedHeight - 20);
               const habitCount = Math.max(1, Math.floor(availableHeight / habitRowHeight));
               const habits = Array(habitCount).fill(0);

               content = (
                   <div className="w-full h-full flex flex-col" style={{ opacity: el.style.opacity }}>
                       <div className="text-[10px] text-gray-500 mb-1 font-bold tracking-wider uppercase">Hábitos</div>
                       <div className="flex-1 flex flex-col gap-1 overflow-hidden">
                           {habits.map((_, i) => (
                               <div key={i} className="flex items-center border-b border-gray-200 h-5 shrink-0">
                                   <div className="w-4 h-4 border border-gray-300 rounded mr-2"></div>
                                   <div className="h-2 w-full bg-gray-100 rounded"></div>
                               </div>
                           ))}
                       </div>
                   </div>
               );
               break;

            case 'note_grid':
                content = (
                    <div className="w-full h-full" style={{ 
                        backgroundImage: `radial-gradient(${el.style.color || '#ccc'} 1px, transparent 1px)`,
                        backgroundSize: '15px 15px',
                        opacity: el.style.opacity
                    }}></div>
                )
                break;
          }

          // Common wrapper style with Transformations
          const wrapperStyle: React.CSSProperties = {
            left: `${el.x}%`,
            top: `${el.y}%`,
            width: `${el.w}%`,
            height: `${el.h}%`,
            zIndex: el.zIndex,
            transform: `rotate(${el.style.rotation || 0}deg) scaleX(${el.style.flipX ? -1 : 1}) scaleY(${el.style.flipY ? -1 : 1})`,
          };

          if (el.type === 'lines' || el.type === 'box' || el.type === 'circle' || el.type === 'vector_flower' || el.type === 'note_grid' || el.type === 'habit_tracker') {
               // Non-text elements
              return (
                <div
                    key={el.id}
                    onMouseDown={(e) => handleMouseDown(e, el.id)}
                    className={`absolute ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`}
                    style={wrapperStyle}
                    title={el.name}
                >
                    <div className="w-full h-full overflow-hidden flex flex-col relative">
                        {content}
                    </div>
                </div>
              );
          }

          // Text elements (includes moon now as it wraps text)
          return (
            <div
              key={el.id}
              onMouseDown={(e) => handleMouseDown(e, el.id)}
              className={`absolute flex items-center ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`}
              title={el.name}
              style={{
                ...wrapperStyle,
                ...el.style,
                // Remove transformations from style spread to avoid double application
                transform: wrapperStyle.transform,
                justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start')
              }}
            >
              {content}
            </div>
          );
        })}
      </div>
    );
  };

  // --- Layout Visualizer Logic for Editor ---

  const renderEditorPage = () => {
    // We simulate an A5 page by default.
    // If layout is 2 per page, we assume the USER is designing the A5 page that contains 2 dates.
    // (Or 2 dates on A4? Usually agendas are A5. Let's assume A5 page size).

    // Apply Margins as Padding to the Container
    const paddingStyle = {
        paddingTop: `${config.margins.top * EDITOR_SCALE}px`,
        paddingBottom: `${config.margins.bottom * EDITOR_SCALE}px`,
        paddingLeft: `${config.margins.left * EDITOR_SCALE}px`,
        paddingRight: `${config.margins.right * EDITOR_SCALE}px`,
    };

    const containerClass = `bg-white shadow-2xl relative transition-all duration-300 ease-in-out flex flex-col`;
    const containerStyle = {
        width: `${EDITOR_WIDTH_PX}px`,
        height: `${A5_HEIGHT_MM * EDITOR_SCALE}px`,
        ...paddingStyle
    };

    const usefulAreaClass = `w-full h-full relative ${showMargins ? 'outline outline-1 outline-dashed outline-indigo-300' : ''}`;

    // Layout 1: 1 Day Per Page (Standard)
    if (config.layoutType === '1_per_page') {
        return (
            <div className={containerClass} style={containerStyle}>
                <div className={usefulAreaClass}>
                    {renderTemplate(null, true, true)}
                </div>
            </div>
        );
    }

    // Layout 2: 2 Days Per Page (Split vertically usually for A5 portrait)
    if (config.layoutType === '2_per_page') {
        return (
            <div className={containerClass} style={containerStyle}>
                <div className={`${usefulAreaClass} flex flex-col`}>
                    {/* Top Day */}
                    <div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">
                        {renderTemplate(null, true, true)}
                         <div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA 1</div>
                    </div>
                    {/* Bottom Day */}
                    <div className="flex-1 relative overflow-hidden">
                        {renderTemplate(null, true, false)} 
                        <div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA 2</div>
                    </div>
                </div>
            </div>
        );
    }

    // Layout 3: Weekend Shared
    if (config.layoutType === '1_per_page_weekend_shared') {
        // Toggle between Weekday View (1 per page) and Weekend View (2 per page)
        if (editorViewMode === 'standard') {
             return (
                <div className={containerClass} style={containerStyle}>
                    <div className={usefulAreaClass}>
                        {renderTemplate(null, true, true)}
                        <div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA DE SEMANA</div>
                    </div>
                </div>
            );
        } else {
            // Weekend View (Split)
            return (
                <div className={containerClass} style={containerStyle}>
                    <div className={`${usefulAreaClass} flex flex-col`}>
                        <div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">
                            {renderTemplate(null, true, true)}
                            <div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">SÁBADO</div>
                        </div>
                        <div className="flex-1 relative overflow-hidden">
                            {renderTemplate(null, true, false)}
                            <div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DOMINGO</div>
                        </div>
                    </div>
                </div>
            );
        }
    }

    return null;
  };

  // --- Preview & Print Logic ---

  const renderPrintLayout = () => {
    const pages: React.ReactNode[] = [];
    const days = generatedData;
    const { margins, layoutType } = config;
    const pagePadding = `${margins.top}mm ${margins.right}mm ${margins.bottom}mm ${margins.left}mm`;
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';

    if (layoutType === '1_per_page') {
        days.forEach(day => {
            pages.push(
                <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}>
                    <div className={`w-full h-full relative ${borderStyle} print:border-none`}>
                         {renderTemplate(day, false)}
                    </div>
                </div>
            );
        });
    } 
    else if (layoutType === '2_per_page') {
        for (let i = 0; i < days.length; i += 2) {
            pages.push(
                <div key={i} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}>
                    <div className={`flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>
                         <div className={`w-full h-full ${borderStyle} print:border-none`}>
                            {renderTemplate(days[i], false)}
                         </div>
                    </div>
                    <div className={`flex-1 relative pt-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>
                         {days[i+1] ? (
                            <div className={`w-full h-full ${borderStyle} print:border-none`}>
                                {renderTemplate(days[i+1], false)}
                            </div>
                         ) : null}
                    </div>
                </div>
            );
        }
    }
    else if (layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < days.length) {
            const day = days[i];
            const isWeekend = day.dayOfWeek === 6; // Saturday

            if (isWeekend) {
                // Render Sat & Sun on one page
                pages.push(
                    <div key={`we-${i}`} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}>
                        <div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden">
                            <div className={`w-full h-full ${borderStyle} print:border-none`}>
                                {renderTemplate(day, false)}
                            </div>
                        </div>
                        <div className="flex-1 relative pt-2 overflow-hidden">
                            {days[i+1] ? (
                                <div className={`w-full h-full ${borderStyle} print:border-none`}>
                                    {renderTemplate(days[i+1], false)}
                                </div>
                            ) : null}
                        </div>
                    </div>
                );
                i += 2;
            } else {
                // Weekday - Full Page
                pages.push(
                    <div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}>
                         <div className={`w-full h-full ${borderStyle} print:border-none`}>
                            {renderTemplate(day, false)}
                         </div>
                    </div>
                );
                i += 1;
            }
        }
    }

    return pages;
  };

  const selectedElement = config.elements.find(e => e.id === selectedId);

  // Constants for visual editor scaling
  const EDITOR_WIDTH_PX = 400; 
  const A5_WIDTH_MM = 148;
  const A5_HEIGHT_MM = 210;
  const EDITOR_SCALE = EDITOR_WIDTH_PX / A5_WIDTH_MM;

  return (
    <div className="h-screen flex flex-col bg-gray-100 overflow-hidden font-sans">
      {/* Top Bar */}
      <header className="bg-white border-b border-gray-200 h-14 flex items-center justify-between px-4 z-20 shrink-0">
        <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-1.5 rounded">
                <Calendar className="h-4 w-4 text-white" />
            </div>
            <span className="font-bold text-gray-800 hidden md:block">AgendaMaster AI</span>
            <span className="px-2 py-0.5 rounded-full bg-gray-100 text-xs text-gray-500 border border-gray-200">Editor</span>
        </div>

        <div className="flex items-center space-x-2 bg-gray-100 p-1 rounded-lg">
            <button 
                onClick={() => setActiveTab('editor')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'editor' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Editar Template
            </button>
            <button 
                onClick={() => setActiveTab('preview')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'preview' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Visualizar & Imprimir
            </button>
        </div>

        <div className="flex items-center space-x-3">
             <button 
                onClick={() => setShowMargins(!showMargins)}
                className={`p-1.5 rounded-md transition-all ${showMargins ? 'bg-indigo-50 text-indigo-600 ring-1 ring-indigo-200' : 'text-gray-400 hover:text-gray-600'}`}
                title={showMargins ? "Ocultar Guias de Margem" : "Mostrar Guias de Margem"}
             >
                <ScanLine className="w-5 h-5" />
             </button>
             <div className="h-5 w-px bg-gray-200"></div>
             <button onClick={() => window.print()} className="flex items-center text-xs font-medium text-gray-700 hover:text-indigo-600 bg-gray-50 px-3 py-1.5 rounded border border-gray-200">
                <Printer className="w-4 h-4 mr-1" /> Imprimir
             </button>
             <button onClick={onLogout} className="text-gray-400 hover:text-red-500">
                <LogOut className="w-4 h-4" />
             </button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">

        {/* LEFT SIDEBAR: Tools & Config */}
        <aside className="w-72 bg-white border-r border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">

            {/* Page Setup */}
            <div className="p-4 border-b border-gray-100">
                <div className="flex items-center mb-3 text-gray-400">
                     <Settings2 className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Configuração</h3>
                </div>

                <div className="space-y-3 mb-6">
                    <div>
                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Ano da Agenda</label>
                        <input 
                            type="number" 
                            value={config.year} 
                            onChange={(e) => setConfig(prev => ({...prev, year: parseInt(e.target.value) || new Date().getFullYear()}))}
                            className="w-full text-xs border border-gray-300 rounded-md shadow-sm p-2 bg-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500"
                        />
                    </div>

                    <div>
                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Tipo de Layout</label>
                        <select 
                            value={config.layoutType}
                            onChange={(e) => setConfig(c => ({...c, layoutType: e.target.value as PageLayoutType}))}
                            className="w-full text-xs border border-gray-300 rounded-md shadow-sm p-2 bg-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500"
                        >
                            <option value="1_per_page">1 Dia por Página</option>
                            <option value="2_per_page">2 Dias por Página</option>
                            <option value="1_per_page_weekend_shared">1 Dia + FDS Dividido</option>
                        </select>
                    </div>

                    <div className="space-y-2 pt-2 border-t border-gray-100">
                        <label className="flex items-center space-x-2 cursor-pointer">
                            <input 
                                type="checkbox" 
                                checked={config.includeHolidays}
                                onChange={(e) => setConfig(prev => ({...prev, includeHolidays: e.target.checked}))}
                                className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300"
                            />
                            <span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Feriados</span>
                        </label>
                        <label className="flex items-center space-x-2 cursor-pointer">
                            <input 
                                type="checkbox" 
                                checked={config.includeMoonPhases}
                                onChange={(e) => setConfig(prev => ({...prev, includeMoonPhases: e.target.checked}))}
                                className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300"
                            />
                            <span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Fases da Lua</span>
                        </label>
                        <label className="flex items-center space-x-2 cursor-pointer">
                            <input 
                                type="checkbox" 
                                checked={config.includeQuotes}
                                onChange={(e) => setConfig(prev => ({...prev, includeQuotes: e.target.checked}))}
                                className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300"
                            />
                            <span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Frases (IA)</span>
                        </label>
                    </div>
                </div>

                <div className="bg-gray-50 p-3 rounded border border-gray-200">
                     <div className="text-[10px] font-bold text-gray-500 mb-2 uppercase">Margens (mm)</div>
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                            <label className="text-[10px] text-gray-400">Topo</label>
                            <input type="number" value={config.margins.top} onChange={(e) => updateConfig('margins.top', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" />
                        </div>
                        <div>
                            <label className="text-[10px] text-gray-400">Base</label>
                            <input type="number" value={config.margins.bottom} onChange={(e) => updateConfig('margins.bottom', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" />
                        </div>
                        <div>
                            <label className="text-[10px] text-gray-400">Esq</label>
                            <input type="number" value={config.margins.left} onChange={(e) => updateConfig('margins.left', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" />
                        </div>
                        <div>
                            <label className="text-[10px] text-gray-400">Dir</label>
                            <input type="number" value={config.margins.right} onChange={(e) => updateConfig('margins.right', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" />
                        </div>
                     </div>
                </div>
            </div>

            {/* Draggable Elements */}
            <div className="p-4 border-b border-gray-100">
                <div className="flex items-center mb-3 text-gray-400">
                     <Layout className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Adicionar Elemento</h3>
                </div>

                <div className="grid grid-cols-3 gap-2">
                    {/* Basic Info */}
                    <button onClick={() => addElement('day_number', 'Número do Dia')} title="Número do Dia" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <span className="text-lg font-bold text-gray-800">24</span>
                    </button>
                    <button onClick={() => addElement('day_name', 'Dia da Semana')} title="Nome do Dia" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <span className="text-xs font-bold text-gray-600">Sábado</span>
                    </button>
                    <button onClick={() => addElement('month_name', 'Mês')} title="Mês" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <span className="text-xs text-gray-500">Julho</span>
                    </button>
                    <button onClick={() => addElement('text', 'Texto')} title="Texto Livre" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Type className="w-5 h-5 text-gray-500" />
                    </button>

                    {/* Shapes */}
                    <button onClick={() => addElement('box', 'Caixa')} title="Caixa" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Square className="w-5 h-5 text-gray-400" />
                    </button>
                    <button onClick={() => addElement('circle', 'Círculo')} title="Círculo" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Circle className="w-5 h-5 text-gray-400" />
                    </button>
                    <button onClick={() => addElement('lines', 'Pautas')} title="Pauta" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <ListTodo className="w-5 h-5 text-gray-400" />
                    </button>

                    {/* Vectors / Advanced */}
                    <button onClick={() => addElement('note_grid', 'Grid')} title="Grid de Anotação" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Grid3X3 className="w-5 h-5 text-gray-400" />
                    </button>
                    <button onClick={() => addElement('habit_tracker', 'Habit Tracker')} title="Habit Tracker" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <span className="text-[8px] text-gray-500 font-bold">HABITS</span>
                    </button>
                    <button onClick={() => addElement('vector_flower', 'Vetor')} title="Flor/Vetor" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Flower className="w-5 h-5 text-gray-400" />
                    </button>

                    {/* Dynamic */}
                    <button onClick={() => addElement('holiday', 'Feriado')} title="Feriado" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Palmtree className="w-5 h-5 text-red-400" />
                    </button>
                    <button onClick={() => addElement('moon', 'Fase da Lua')} title="Fase da Lua" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <Moon className="w-5 h-5 text-gray-400" />
                    </button>
                    <button onClick={() => addElement('quote', 'Frase IA')} title="Frase (IA)" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all">
                        <ArrowDownAZ className="w-5 h-5 text-indigo-400" />
                    </button>
                </div>
            </div>

            {/* Layers List (Separate Elements) */}
            <div className="p-4 flex-1 overflow-y-auto">
                 <div className="flex items-center mb-3 text-gray-400">
                     <Layers className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Camadas</h3>
                </div>
                <div className="space-y-1">
                    {config.elements.slice().reverse().map((el) => (
                        <div 
                            key={el.id} 
                            onClick={() => setSelectedId(el.id)}
                            className={`flex items-center p-2 rounded text-xs cursor-pointer border ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}
                        >
                            <span className="flex-1 truncate font-medium">{el.name || el.type}</span>
                            <button 
                                onClick={(e) => { e.stopPropagation(); removeElement(el.id); }}
                                className="text-gray-400 hover:text-red-500 p-1"
                            >
                                <Trash2 className="w-3 h-3" />
                            </button>
                        </div>
                    ))}
                    {config.elements.length === 0 && (
                        <p className="text-center text-gray-400 text-xs py-4 italic">Sem elementos</p>
                    )}
                </div>
            </div>
        </aside>

        {/* MAIN AREA */}
        <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">

            {activeTab === 'editor' && (
                <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden">
                    {/* View Controls for Layouts */}
                    {config.layoutType === '1_per_page_weekend_shared' && (
                        <div className="mb-4 bg-white p-1 rounded-lg shadow-sm flex space-x-1">
                            <button 
                                onClick={() => setEditorViewMode('standard')}
                                className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'standard' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}
                            >
                                Dias da Semana (Pág Inteira)
                            </button>
                            <button 
                                onClick={() => setEditorViewMode('weekend')}
                                className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'weekend' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}
                            >
                                Fim de Semana (Dividido)
                            </button>
                        </div>
                    )}

                    <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar">
                         {/* The Canvas */}
                        <div className="flex flex-col items-center">
                             <div className="text-xs text-gray-500 mb-2 font-mono uppercase tracking-wide">
                                 {config.layoutType === '2_per_page' ? 'Visualização: 2 Dias / Pág' : 
                                  config.layoutType === '1_per_page_weekend_shared' && editorViewMode === 'weekend' ? 'Visualização: Fim de Semana' : 
                                  'Visualização: Pág Inteira'}
                             </div>

                             {renderEditorPage()}

                            <div className="text-xs text-gray-400 mt-4 text-center max-w-md">
                                {config.layoutType === '2_per_page' ? 'As alterações são espelhadas nos dois blocos.' : 'Edite o layout do dia.'}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'preview' && (
                <div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500">
                    <div className="max-w-[210mm] mx-auto">
                        <div id="print-area">
                             {generatedData.length === 0 ? (
                                 <div className="text-center py-20 text-white">Carregando visualização...</div>
                             ) : (
                                 <div className="space-y-8">
                                    <div className="p-4 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 text-sm mb-4 no-print shadow-lg">
                                        <p className="font-bold">Modo de Pré-visualização</p>
                                        <p>Mostrando as primeiras 4 páginas. Clique em "Imprimir" para gerar o PDF completo de 365 dias.</p>
                                    </div>
                                    <div className="print-only hidden">
                                         {renderPrintLayout()}
                                    </div>
                                    <div className="no-print">
                                         {renderPrintLayout().slice(0, 4)}
                                    </div>
                                 </div>
                             )}
                        </div>
                    </div>
                </div>
            )}
        </main>

        {/* RIGHT SIDEBAR: Properties */}
        {activeTab === 'editor' && (
            <aside className="w-72 bg-white border-l border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">
                <div className="p-4 border-b border-gray-100 bg-gray-50">
                     <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Propriedades</h3>
                </div>

                {selectedElement ? (
                    <div className="p-4 space-y-5">
                         <div className="space-y-2">
                             <label className="block text-[10px] font-bold text-gray-500 uppercase">Nome da Camada</label>
                             <input 
                                type="text" 
                                value={selectedElement.name || selectedElement.type}
                                onChange={(e) => updateElementName(selectedElement.id, e.target.value)}
                                className="w-full text-xs p-2 border border-gray-200 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
                             />
                         </div>

                         <div className="h-px bg-gray-100"></div>

                         {/* Position & Size */}
                         <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Largura %</label>
                                <div className="flex items-center">
                                    <input 
                                        type="range" min="5" max="100"
                                        value={Math.round(selectedElement.w)} 
                                        onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el)}))}
                                        className="w-full mr-2"
                                    />
                                    <span className="text-xs w-6">{Math.round(selectedElement.w)}</span>
                                </div>
                            </div>
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Altura %</label>
                                <div className="flex items-center">
                                    <input 
                                        type="range" min="2" max="100"
                                        value={Math.round(selectedElement.h)} 
                                        onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el)}))}
                                        className="w-full mr-2"
                                    />
                                    <span className="text-xs w-6">{Math.round(selectedElement.h)}</span>
                                </div>
                            </div>
                         </div>

                         {/* Typography */}
                         {['day_number', 'day_name', 'month_name', 'year', 'quote', 'text', 'holiday', 'moon'].includes(selectedElement.type) && (
                             <div className="space-y-3 pt-3 border-t border-gray-100">
                                 {/* Font Selector */}
                                 <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Fonte</label>
                                    <div className="relative">
                                        <select
                                            value={selectedElement.style.fontFamily || 'Inter'}
                                            onChange={(e) => updateElementStyle(selectedElement.id, { fontFamily: e.target.value })}
                                            className="w-full text-xs p-2 border border-gray-200 rounded appearance-none bg-white"
                                            style={{ fontFamily: selectedElement.style.fontFamily }}
                                        >
                                            <optgroup label="Padrão">
                                                {AVAILABLE_FONTS.map(font => (
                                                    <option key={font} value={font} style={{ fontFamily: font }}>{font}</option>
                                                ))}
                                            </optgroup>
                                            {customFonts.length > 0 && (
                                                <optgroup label="Minhas Fontes">
                                                    {customFonts.map(font => (
                                                        <option key={font} value={font} style={{ fontFamily: font }}>{font}</option>
                                                    ))}
                                                </optgroup>
                                            )}
                                        </select>
                                        <ChevronDown className="w-3 h-3 text-gray-400 absolute right-2 top-2.5 pointer-events-none" />
                                    </div>
                                    <button 
                                        onClick={() => fileInputRef.current?.click()}
                                        className="mt-2 w-full flex items-center justify-center px-2 py-1.5 border border-dashed border-gray-300 rounded text-[10px] text-gray-500 hover:bg-gray-50 hover:text-indigo-600 transition-colors"
                                    >
                                        <Upload className="w-3 h-3 mr-1.5" /> Carregar Fonte (.ttf/.otf)
                                    </button>
                                    <input 
                                        type="file" 
                                        accept=".ttf,.otf,.woff,.woff2" 
                                        ref={fileInputRef} 
                                        className="hidden" 
                                        onChange={handleFontUpload}
                                    />
                                 </div>

                                 <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Tamanho</label>
                                    <input 
                                        type="range" min="8" max="120"
                                        value={selectedElement.style.fontSize} 
                                        onChange={(e) => updateElementStyle(selectedElement.id, { fontSize: parseInt(e.target.value) })}
                                        className="w-full"
                                    />
                                 </div>

                                 <div>
                                     <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Alinhamento</label>
                                     <div className="flex border border-gray-200 rounded overflow-hidden">
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'left' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'left' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignLeft className="w-4 h-4 mx-auto"/></button>
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'center' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'center' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignCenter className="w-4 h-4 mx-auto"/></button>
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'right' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'right' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignRight className="w-4 h-4 mx-auto"/></button>
                                     </div>
                                 </div>
                             </div>
                         )}

                         {/* Colors & Appearance */}
                         <div className="space-y-3 pt-3 border-t border-gray-100">
                             <div>
                                 <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">
                                     {selectedElement.type === 'vector_flower' ? 'Cor do Contorno' : 'Cor Principal'}
                                 </label>
                                 <div className="flex space-x-2">
                                     <input 
                                        type="color" 
                                        value={selectedElement.style.color || '#000000'}
                                        onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })}
                                        className="h-8 w-8 rounded cursor-pointer p-0 border-0"
                                     />
                                     <input 
                                        type="text" 
                                        value={selectedElement.style.color}
                                        onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })}
                                        className="flex-1 border border-gray-200 rounded px-2 text-xs uppercase"
                                     />
                                 </div>
                             </div>

                             {(selectedElement.type === 'box' || selectedElement.type === 'circle' || selectedElement.type === 'vector_flower') && (
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">
                                        {selectedElement.type === 'vector_flower' ? 'Cor do Preenchimento' : 'Cor de Fundo'}
                                    </label>
                                    <div className="flex space-x-2">
                                        <input 
                                            type="color" 
                                            value={selectedElement.style.backgroundColor || '#ffffff'}
                                            onChange={(e) => updateElementStyle(selectedElement.id, { backgroundColor: e.target.value })}
                                            className="h-8 w-8 rounded cursor-pointer p-0 border-0"
                                        />
                                        <button 
                                            onClick={() => updateElementStyle(selectedElement.id, { backgroundColor: 'transparent' })}
                                            className="text-xs px-2 border border-gray-200 rounded hover:bg-gray-50"
                                        >
                                            Transparente
                                        </button>
                                    </div>
                                </div>
                             )}

                             <div>
                                 <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Opacidade</label>
                                 <input 
                                     type="range" min="0" max="1" step="0.1"
                                     value={selectedElement.style.opacity ?? 1} 
                                     onChange={(e) => updateElementStyle(selectedElement.id, { opacity: parseFloat(e.target.value) })}
                                     className="w-full"
                                 />
                             </div>

                             {/* Transformations */}
                             <div className="pt-3 border-t border-gray-100">
                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Transformação</label>

                                <div className="mb-2">
                                    <span className="text-[10px] text-gray-400">Rotação</span>
                                    <input 
                                        type="range" min="0" max="360"
                                        value={selectedElement.style.rotation || 0} 
                                        onChange={(e) => updateElementStyle(selectedElement.id, { rotation: parseInt(e.target.value) })}
                                        className="w-full"
                                    />
                                </div>

                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => updateElementStyle(selectedElement.id, { flipX: !selectedElement.style.flipX })}
                                        className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipX ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                                        title="Espelhar Horizontalmente"
                                    >
                                        <FlipHorizontal className="w-4 h-4 mr-1" /> Horiz.
                                    </button>
                                    <button 
                                        onClick={() => updateElementStyle(selectedElement.id, { flipY: !selectedElement.style.flipY })}
                                        className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipY ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`}
                                        title="Espelhar Verticalmente"
                                    >
                                        <FlipVertical className="w-4 h-4 mr-1" /> Vert.
                                    </button>
                                </div>
                             </div>
                         </div>

                         {/* Specifics */}
                         {selectedElement.type === 'lines' && (
                             <div className="pt-3 border-t border-gray-100 space-y-3">
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Espaçamento das Linhas</label>
                                    <input 
                                        type="range" min="10" max="60"
                                        value={selectedElement.style.lineSpacing}
                                        onChange={(e) => updateElementStyle(selectedElement.id, { lineSpacing: parseInt(e.target.value) })}
                                        className="w-full"
                                    />
                                </div>

                                <div className="bg-gray-50 p-2 rounded border border-gray-200">
                                    <div className="flex items-center justify-between mb-2">
                                        <label className="text-[10px] font-bold text-gray-500 uppercase flex items-center">
                                            <Clock className="w-3 h-3 mr-1" /> Horários
                                        </label>
                                        <input 
                                            type="checkbox"
                                            checked={selectedElement.style.showTimes || false}
                                            onChange={(e) => updateElementStyle(selectedElement.id, { showTimes: e.target.checked })}
                                            className="h-4 w-4 text-indigo-600 rounded"
                                        />
                                    </div>

                                    {selectedElement.style.showTimes && (
                                        <div className="flex items-center space-x-2">
                                            <label className="text-[10px] text-gray-400">Início (h)</label>
                                            <input 
                                                type="number" min="0" max="23"
                                                value={selectedElement.style.startHour || 7}
                                                onChange={(e) => updateElementStyle(selectedElement.id, { startHour: parseInt(e.target.value) })}
                                                className="w-16 text-xs p-1 border rounded"
                                            />
                                        </div>
                                    )}
                                </div>
                             </div>
                         )}

                         <div className="pt-6">
                            <button 
                                onClick={() => removeElement(selectedElement.id)}
                                className="w-full py-2 px-4 bg-white border border-red-200 text-red-600 rounded hover:bg-red-50 flex items-center justify-center text-sm transition-colors"
                            >
                                <Trash2 className="w-4 h-4 mr-2" /> Excluir Elemento
                            </button>
                         </div>
                    </div>
                ) : (
                    <div className="p-8 text-center text-gray-400 flex flex-col items-center justify-center h-full">
                        <Move className="w-12 h-12 mb-4 opacity-20" />
                        <p className="text-sm font-medium">Nenhum elemento selecionado</p>
                        <p className="text-xs mt-2 opacity-70">Clique em um elemento na lista de camadas ou no layout para editar.</p>
                    </div>
                )}
            </aside>
        )}

      </div>
    </div>
  );
};

export default Dashboard;

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados para a página
export type ElementType = 
  | 'text'
  | 'day_number' 
  | 'day_name' 
  | 'month_name' 
  | 'year' 
  | 'lines' 
  | 'box' 
  | 'circle' 
  | 'quote' 
  | 'moon' 
  | 'holiday' 
  | 'habit_tracker' 
  | 'vector_flower' 
  | 'note_grid';

export interface LayoutElement {
  id: string;
  name?: string; // Nome legível para a camada
  type: ElementType;
  x: number; // Posição X em % (0-100) relativo à área útil da página
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  zIndex: number;
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string; // Cor do texto ou contorno (Stroke para vetores)
    backgroundColor?: string; // Preenchimento (Fill para vetores)
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    lineSpacing?: number; // Para pautas
    showTimes?: boolean; // Para pautas com horário
    startHour?: number; // Hora inicial para pautas
    rotation?: number; // Em graus
    flipX?: boolean; // Espelhar horizontalmente
    flipY?: boolean; // Espelhar verticalmente
    variant?: string; // Identificador de variação visual (ex: 'star', 'heart', 'outline')
  };
}

export interface PageMargins {
  top: number;    // mm
  bottom: number; // mm
  left: number;   // mm
  right: number;  // mm
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_weekend_shared';

export interface AgendaConfig {
  year: number;
  layoutType: PageLayoutType;
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  margins: PageMargins;
  elements: LayoutElement[]; // Lista de elementos que compõem o template do dia
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import React, { useState, useEffect, useRef } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType } from '../types';
import { generateCalendarYear, getMonthName, getDayName } from '../services/calendarService';
import { generateMonthlyQuotes } from '../services/geminiService';
import { 
  Calendar, Printer, LogOut, Moon, Type, 
  Trash2, Move, AlignLeft, AlignCenter, AlignRight, Layout,
  Square, Circle, Flower, ListTodo, Grid3X3, ArrowDownAZ,
  Maximize, Minimize, Settings2, ScanLine, FlipHorizontal, FlipVertical,
  Layers, Upload, ChevronRight, ChevronDown, Plus, FontInput, Clock,
  CalendarDays, Palmtree, X, Star, Heart, Leaf
} from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

// Standard Web Fonts
const AVAILABLE_FONTS = [
  'Inter', 'Arial', 'Helvetica', 'Times New Roman', 'Courier New', 
  'Georgia', 'Verdana', 'Playfair Display', 'Merriweather', 'Dancing Script', 'Lato'
];

// --- Element Variants Definitions ---
interface ElementVariant {
    name: string;
    description: string;
    preview?: React.ReactNode;
    styleOverride: Partial<LayoutElement['style']>;
    defaultSize?: { w: number, h: number };
}

const ELEMENT_VARIANTS: Record<string, ElementVariant[]> = {
    'day_number': [
        { name: 'Padrão', description: 'Simples e direto', styleOverride: { fontSize: 42, fontWeight: 'bold', fontFamily: 'Inter' } },
        { name: 'Elegante', description: 'Fonte Serifada', styleOverride: { fontSize: 56, fontWeight: 'normal', fontFamily: 'Playfair Display', color: '#374151' } },
        { name: 'Badge Circular', description: 'Fundo circular', styleOverride: { fontSize: 24, fontWeight: 'bold', color: '#ffffff', backgroundColor: '#1f2937', borderRadius: 999, textAlign: 'center', fontFamily: 'Inter' }, defaultSize: { w: 10, h: 6.5 } },
        { name: 'Badge Quadrado', description: 'Fundo quadrado', styleOverride: { fontSize: 24, fontWeight: 'bold', color: '#ffffff', backgroundColor: '#1f2937', borderRadius: 4, textAlign: 'center', fontFamily: 'Inter' }, defaultSize: { w: 10, h: 6.5 } },
    ],
    'day_name': [
        { name: 'Simples', description: 'Texto cinza', styleOverride: { fontSize: 14, fontWeight: '600', color: '#4b5563', fontFamily: 'Inter', textAlign: 'left' } },
        { name: 'Caixa Alta', description: 'Espaçado', styleOverride: { fontSize: 12, fontWeight: 'bold', color: '#1f2937', fontFamily: 'Inter', textAlign: 'center' } }, // letterSpacing simulated via font selection or generic css usually, here just style
        { name: 'Cursiva', description: 'Estilo manuscrito', styleOverride: { fontSize: 22, fontWeight: 'normal', color: '#374151', fontFamily: 'Dancing Script', textAlign: 'left' } },
    ],
    'month_name': [
         { name: 'Padrão', description: 'Pequeno', styleOverride: { fontSize: 12, fontWeight: 'normal', color: '#9ca3af', textAlign: 'left' } },
         { name: 'Destaque', description: 'Grande e Bold', styleOverride: { fontSize: 28, fontWeight: 'bold', color: '#e5e7eb', textAlign: 'right' } },
    ],
    'moon': [
        { name: 'Completo', description: 'Ícone + Texto', styleOverride: { variant: 'full_info', fontSize: 12, color: '#6b7280' }, defaultSize: { w: 20, h: 5 } },
        { name: 'Ícone', description: 'Apenas desenho', styleOverride: { variant: 'icon_only', fontSize: 24, color: '#6b7280' }, defaultSize: { w: 8, h: 5 } },
        { name: 'Minimalista', description: 'Traço fino', styleOverride: { variant: 'minimal', fontSize: 12, color: '#000000' }, defaultSize: { w: 20, h: 5 } },
    ],
    'vector_flower': [
        { name: 'Flor', description: 'Pétalas arredondadas', styleOverride: { variant: 'flower_1', color: '#1f2937', backgroundColor: '#e5e7eb' } },
        { name: 'Estrela', description: '5 pontas', styleOverride: { variant: 'star', color: '#1f2937', backgroundColor: '#e5e7eb' } },
        { name: 'Coração', description: 'Formato coração', styleOverride: { variant: 'heart', color: '#ef4444', backgroundColor: '#fee2e2' } },
        { name: 'Folha', description: 'Orgânico', styleOverride: { variant: 'leaf', color: '#059669', backgroundColor: '#d1fae5' } },
    ],
    'lines': [
        { name: 'Padrão', description: 'Linhas cinzas', styleOverride: { color: '#e5e7eb', lineSpacing: 24 } },
        { name: 'Com Horário', description: 'Marcação de hora', styleOverride: { color: '#e5e7eb', lineSpacing: 30, showTimes: true, startHour: 8 } },
        { name: 'Pontilhado', description: 'Linhas discretas', styleOverride: { color: '#d1d5db', lineSpacing: 24 } }, // Render logic needs to support this, simplified for now
    ]
};


const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const getDefaultElements = (): LayoutElement[] => [
      { id: '1', name: 'Número do Dia', type: 'day_number', x: 5, y: 3, w: 15, h: 8, zIndex: 10, style: { fontSize: 42, fontWeight: 'bold', color: '#1f2937', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '2', name: 'Dia da Semana', type: 'day_name', x: 22, y: 5, w: 40, h: 5, zIndex: 10, style: { fontSize: 14, fontWeight: '600', color: '#4b5563', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '3', name: 'Mês', type: 'month_name', x: 22, y: 8, w: 30, h: 4, zIndex: 10, style: { fontSize: 12, fontWeight: 'normal', color: '#9ca3af', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '4', name: 'Pautas', type: 'lines', x: 5, y: 18, w: 90, h: 75, zIndex: 5, style: { color: '#e5e7eb', lineSpacing: 24, showTimes: false, startHour: 7 } }
  ];

  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layoutType: '1_per_page',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    margins: { top: 15, bottom: 15, left: 15, right: 15 },
    elements: getDefaultElements()
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showMargins, setShowMargins] = useState(true);
  const [customFonts, setCustomFonts] = useState<string[]>([]);

  // Variant Modal State
  const [variantModal, setVariantModal] = useState<{type: ElementType, label: string} | null>(null);

  // Editor View State
  const [editorViewMode, setEditorViewMode] = useState<'standard' | 'weekend'>('standard');

  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; initialEleX: number; initialEleY: number } | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  useEffect(() => {
    if (config.includeQuotes && quotes.length === 0) {
       generateMonthlyQuotes(config.year).then(setQuotes);
    }
  }, [config.includeQuotes, config.year]);

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (event) => {
          const fontData = event.target?.result as string;
          const fontName = file.name.split('.')[0].replace(/[^a-zA-Z0-9]/g, '');
          const newFont = new FontFace(fontName, `url(${fontData})`);
          newFont.load().then((loadedFont) => {
              (document.fonts as any).add(loadedFont);
              setCustomFonts(prev => [...prev, fontName]);
              if (selectedId) {
                  updateElementStyle(selectedId, { fontFamily: fontName });
              }
          }).catch(err => {
              console.error("Failed to load font:", err);
              alert("Erro ao carregar a fonte.");
          });
      };
      reader.readAsDataURL(file);
  };

  const openElementSelector = (type: ElementType, label: string) => {
      // Check if this type has variants
      if (ELEMENT_VARIANTS[type]) {
          setVariantModal({ type, label });
      } else {
          // No variants, add directly
          addElement(type, label);
      }
  };

  const addElement = (type: ElementType, label: string, styleOverride: any = {}, sizeOverride: any = {}) => {
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      name: `${label} ${config.elements.length + 1}`,
      x: 35,
      y: 40,
      w: sizeOverride.w || 20,
      h: sizeOverride.h || 10,
      zIndex: config.elements.length + 1,
      style: {
        fontSize: 14,
        color: '#000000',
        textAlign: 'left',
        lineSpacing: 24,
        borderColor: '#000000',
        borderWidth: 1,
        backgroundColor: 'transparent',
        rotation: 0,
        opacity: 1,
        flipX: false,
        flipY: false,
        fontFamily: 'Inter',
        showTimes: false,
        startHour: 7,
        ...styleOverride
      }
    };

    // Default Sizes if not overridden
    if (!sizeOverride.w) {
        if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
        if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
        if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
        if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
        if (type === 'text') { newElement.w = 30; newElement.h = 8; newElement.style.fontSize = 16; newElement.style.borderWidth = 0; }
        if (type === 'holiday') { newElement.w = 40; newElement.h = 5; newElement.style.fontSize = 10; newElement.style.color = '#ef4444'; newElement.style.borderWidth = 0; newElement.style.fontWeight = '500'; }
        if (type === 'moon') { newElement.w = 20; newElement.h = 5; newElement.style.fontSize = 12; newElement.style.color = '#6b7280'; newElement.style.borderWidth = 0; }
        if (type === 'vector_flower') { newElement.w = 20; newElement.h = 20; newElement.style.color = '#1f2937'; newElement.style.backgroundColor = '#e5e7eb'; newElement.style.borderWidth = 0; }
        if (type === 'habit_tracker') { newElement.w = 40; newElement.h = 15; newElement.style.borderWidth = 1; newElement.style.borderColor = '#d1d5db'; }
        if (type === 'note_grid') { newElement.w = 40; newElement.h = 20; newElement.style.opacity = 0.5; newElement.style.borderWidth = 0; }
    }

    // Auto-enable config flags
    if (type === 'holiday') setConfig(prev => ({ ...prev, includeHolidays: true }));
    if (type === 'moon') setConfig(prev => ({ ...prev, includeMoonPhases: true }));
    if (type === 'quote') setConfig(prev => ({ ...prev, includeQuotes: true }));

    setConfig(prev => ({ ...prev, elements: [...prev.elements, newElement] }));
    setSelectedId(newElement.id);
    setVariantModal(null); // Close modal if open
  };

  const removeElement = (id: string) => {
    setConfig(prev => ({ ...prev, elements: prev.elements.filter(e => e.id !== id) }));
    setSelectedId(null);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e)
    }));
  };

  const updateElementName = (id: string, name: string) => {
    setConfig(prev => ({
        ...prev,
        elements: prev.elements.map(e => e.id === id ? { ...e, name } : e)
    }));
  };

  const updateConfig = (key: string, value: any) => {
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          setConfig(prev => ({
              ...prev,
              [parent]: {
                  ...prev[parent as keyof AgendaConfig] as any,
                  [child]: value
              }
          }));
      } else {
          setConfig(prev => ({ ...prev, [key]: value }));
      }
  }

  const handleMouseDown = (e: React.MouseEvent, id: string) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const element = config.elements.find(el => el.id === id);
    if (!element) return;

    setSelectedId(id);
    setIsDragging(true);

    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      initialEleX: element.x,
      initialEleY: element.y
    };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !dragRef.current || !selectedId) return;
    if (!editorRef.current) return;

    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaXPixels = e.clientX - dragRef.current.startX;
    const deltaYPixels = e.clientY - dragRef.current.startY;
    const deltaXPercent = (deltaXPixels / editorRect.width) * 100;
    const deltaYPercent = (deltaYPixels / editorRect.height) * 100;

    let newX = dragRef.current.initialEleX + deltaXPercent;
    let newY = dragRef.current.initialEleY + deltaYPercent;

    newX = Math.round(newX * 2) / 2;
    newY = Math.round(newY * 2) / 2;

    setConfig(prev => ({
      ...prev,
      elements: prev.elements.map(el => 
        el.id === selectedId ? { ...el, x: newX, y: newY } : el
      )
    }));
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragRef.current = null;
  };

  const renderMoonIcon = (phase: string, color: string) => {
      const p = phase.toLowerCase();
      if (p.includes('nova')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
      if (p.includes('cheia')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><circle cx="12" cy="12" r="10"/></svg>;
      if (p.includes('crescente')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a9 9 0 1 0 0 18 7 7 0 0 1 0-14 7 7 0 0 1 0-4z" /></svg>;
      if (p.includes('minguante')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a7 7 0 0 0 0 14 7 7 0 0 0 0 4 9 9 0 1 1 0-18z" /></svg>;
      return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
  }

  const renderVector = (style: any) => {
      const variant = style.variant || 'flower_1';

      let path = "M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C21 14 24 10.5 24 7.5C24 4.5 22.5 2 20 2C17.5 2 16 4 16 6C16 4 14.5 2 12 2Z"; // Flower 1

      if (variant === 'star') {
          path = "M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z";
      } else if (variant === 'heart') {
          path = "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";
      } else if (variant === 'leaf') {
          path = "M17 8C8 10 5.9 16.17 3.82 21.34 9.17 19.8 15 17 17 8zm-7.05 5.55A3.99 3.99 0 0 0 12 13a4 4 0 0 0 0 8C9.5 16.5 9.5 16 9.95 13.55zM12 2C9.5 2 8 4 8 6c0 4 6 7 4 7s4-3 4-7c0-2-1.5-4-4-4z"; // Simplified organic shape
      }

      return (
          <svg viewBox="0 0 24 24" className="w-full h-full" style={{ overflow: 'visible' }}>
              <path 
                d={path} 
                fill={style.backgroundColor || 'transparent'}
                stroke={style.color || 'none'}
                strokeWidth="1.5"
                strokeLinejoin="round"
              />
          </svg>
      ); 
  }

  const renderTemplate = (day: DayData | null, isEditor: boolean = false, attachRef: boolean = false) => {
    const d = day || { dayOfMonth: 24, month: 7, year: config.year, dayOfWeek: 3, holiday: 'Feriado Exemplo', moonPhase: 'Lua cheia', date: new Date() } as DayData;

    return (
      <div 
        ref={attachRef ? editorRef : null}
        className={`relative overflow-hidden ${isEditor ? 'w-full h-full' : 'w-full h-full'}`}
        onMouseMove={isEditor ? handleMouseMove : undefined}
        onMouseUp={isEditor ? handleMouseUp : undefined}
        onMouseLeave={isEditor ? handleMouseUp : undefined}
      >
        {config.elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;
          let content: React.ReactNode = '';

          switch (el.type) {
            case 'day_number': content = d.dayOfMonth; break;
            case 'month_name': content = getMonthName(d.month); break;
            case 'day_name': content = getDayName(d.dayOfWeek); break;
            case 'year': content = d.year; break;
            case 'holiday': content = d.holiday || (isEditor ? 'Nome do Feriado' : ''); break;
            case 'text': content = (isEditor ? 'Texto Livre' : ''); break;
            case 'quote': content = config.includeQuotes && quotes[d.month] ? `"${quotes[d.month]}"` : (isEditor ? '"Frase Inspiradora"' : ''); break;
            case 'vector_flower': content = renderVector(el.style); break;

            case 'moon': 
                const phase = d.moonPhase || (isEditor ? 'Lua cheia' : '');
                if (phase) {
                    const variant = el.style.variant || 'full_info';

                    if (variant === 'icon_only') {
                        content = <div className="w-full h-full flex items-center justify-center">{renderMoonIcon(phase, el.style.color || '#000')}</div>;
                    } else {
                        // full_info or default
                        content = (
                            <div className="flex items-center gap-1.5 h-full">
                                <div className="shrink-0" style={{ width: el.style.fontSize, height: el.style.fontSize }}>
                                    {renderMoonIcon(phase, el.style.color || '#000')}
                                </div>
                                <span className="whitespace-nowrap">{phase}</span>
                            </div>
                        );
                    }
                }
                break;

            case 'lines': 
              const lineCount = Math.floor((el.h / 100 * (isEditor ? 600 : 800)) / (el.style.lineSpacing || 24)); 
              const startHour = el.style.startHour || 7;
              content = Array(Math.max(2, lineCount)).fill(0).map((_, i) => (
                <div key={i} className="w-full border-b relative" style={{ height: el.style.lineSpacing, borderColor: el.style.color }}>
                     {el.style.showTimes && (
                         <span className="absolute -top-2 left-0 text-[10px] font-mono text-gray-500 bg-white/50 pr-1" style={{ fontSize: (el.style.fontSize ? el.style.fontSize * 0.7 : 10) }}>
                             {String(startHour + i).padStart(2, '0')}:00
                         </span>
                     )}
                </div>
              ));
              break;

            case 'box': content = <div className="w-full h-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}`, borderRadius: el.style.borderRadius }}></div>; break;
            case 'circle': content = <div className="w-full h-full rounded-full" style={{ backgroundColor: el.style.backgroundColor, border: `${el.style.borderWidth}px solid ${el.style.borderColor}` }}></div>; break;
            case 'habit_tracker':
               const habitRowHeight = 20;
               const estimatedHeight = (el.h / 100 * (isEditor ? 600 : 800));
               const availableHeight = Math.max(0, estimatedHeight - 20);
               const habitCount = Math.max(1, Math.floor(availableHeight / habitRowHeight));
               const habits = Array(habitCount).fill(0);
               content = (
                   <div className="w-full h-full flex flex-col" style={{ opacity: el.style.opacity }}>
                       <div className="text-[10px] text-gray-500 mb-1 font-bold tracking-wider uppercase">Hábitos</div>
                       <div className="flex-1 flex flex-col gap-1 overflow-hidden">
                           {habits.map((_, i) => (
                               <div key={i} className="flex items-center border-b border-gray-200 h-5 shrink-0">
                                   <div className="w-4 h-4 border border-gray-300 rounded mr-2"></div>
                                   <div className="h-2 w-full bg-gray-100 rounded"></div>
                               </div>
                           ))}
                       </div>
                   </div>
               );
               break;
            case 'note_grid':
                content = <div className="w-full h-full" style={{ backgroundImage: `radial-gradient(${el.style.color || '#ccc'} 1px, transparent 1px)`, backgroundSize: '15px 15px', opacity: el.style.opacity }}></div>;
                break;
          }

          const wrapperStyle: React.CSSProperties = {
            left: `${el.x}%`,
            top: `${el.y}%`,
            width: `${el.w}%`,
            height: `${el.h}%`,
            zIndex: el.zIndex,
            transform: `rotate(${el.style.rotation || 0}deg) scaleX(${el.style.flipX ? -1 : 1}) scaleY(${el.style.flipY ? -1 : 1})`,
          };

          if (['lines','box','circle','vector_flower','note_grid','habit_tracker'].includes(el.type)) {
              return (
                <div key={el.id} onMouseDown={(e) => handleMouseDown(e, el.id)} className={`absolute ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`} style={wrapperStyle} title={el.name}>
                    <div className="w-full h-full overflow-hidden flex flex-col relative">{content}</div>
                </div>
              );
          }

          return (
            <div key={el.id} onMouseDown={(e) => handleMouseDown(e, el.id)} className={`absolute flex items-center ${isSelected ? 'ring-2 ring-indigo-500 cursor-move' : ''}`} title={el.name} style={{ ...wrapperStyle, ...el.style, transform: wrapperStyle.transform, justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start') }}>
              {content}
            </div>
          );
        })}
      </div>
    );
  };

  // --- Render Helpers ---
  const renderEditorPage = () => {
    const paddingStyle = { paddingTop: `${config.margins.top * EDITOR_SCALE}px`, paddingBottom: `${config.margins.bottom * EDITOR_SCALE}px`, paddingLeft: `${config.margins.left * EDITOR_SCALE}px`, paddingRight: `${config.margins.right * EDITOR_SCALE}px` };
    const containerClass = `bg-white shadow-2xl relative transition-all duration-300 ease-in-out flex flex-col`;
    const containerStyle = { width: `${EDITOR_WIDTH_PX}px`, height: `${A5_HEIGHT_MM * EDITOR_SCALE}px`, ...paddingStyle };
    const usefulAreaClass = `w-full h-full relative ${showMargins ? 'outline outline-1 outline-dashed outline-indigo-300' : ''}`;

    if (config.layoutType === '1_per_page') {
        return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(null, true, true)}</div></div>;
    }
    if (config.layoutType === '2_per_page') {
        return (
            <div className={containerClass} style={containerStyle}>
                <div className={`${usefulAreaClass} flex flex-col`}>
                    <div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(null, true, true)}<div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA 1</div></div>
                    <div className="flex-1 relative overflow-hidden">{renderTemplate(null, true, false)}<div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA 2</div></div>
                </div>
            </div>
        );
    }
    if (config.layoutType === '1_per_page_weekend_shared') {
        if (editorViewMode === 'standard') {
             return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(null, true, true)}<div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DIA DE SEMANA</div></div></div>;
        } else {
            return (
                <div className={containerClass} style={containerStyle}>
                    <div className={`${usefulAreaClass} flex flex-col`}>
                        <div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(null, true, true)}<div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">SÁBADO</div></div>
                        <div className="flex-1 relative overflow-hidden">{renderTemplate(null, true, false)}<div className="absolute top-1 right-1 text-[8px] text-gray-300 pointer-events-none">DOMINGO</div></div>
                    </div>
                </div>
            );
        }
    }
    return null;
  };

  const renderPrintLayout = () => {
    const pages: React.ReactNode[] = [];
    const days = generatedData;
    const { margins, layoutType } = config;
    const pagePadding = `${margins.top}mm ${margins.right}mm ${margins.bottom}mm ${margins.left}mm`;
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';

    if (layoutType === '1_per_page') {
        days.forEach(day => { pages.push(<div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}><div className={`w-full h-full relative ${borderStyle} print:border-none`}>{renderTemplate(day, false)}</div></div>); });
    } else if (layoutType === '2_per_page') {
        for (let i = 0; i < days.length; i += 2) {
            pages.push(<div key={i} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}><div className={`flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(days[i], false)}</div></div><div className={`flex-1 relative pt-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>{days[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(days[i+1], false)}</div>) : null}</div></div>);
        }
    } else if (layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < days.length) {
            const day = days[i];
            const isWeekend = day.dayOfWeek === 6;
            if (isWeekend) {
                pages.push(<div key={`we-${i}`} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page flex flex-col box-border" style={{ padding: pagePadding }}><div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden"><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(day, false)}</div></div><div className="flex-1 relative pt-2 overflow-hidden">{days[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(days[i+1], false)}</div>) : null}</div></div>);
                i += 2;
            } else {
                pages.push(<div key={day.date.toISOString()} className="w-full h-[210mm] bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden" style={{ padding: pagePadding }}><div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(day, false)}</div></div>);
                i += 1;
            }
        }
    }
    return pages;
  };

  const selectedElement = config.elements.find(e => e.id === selectedId);
  const EDITOR_WIDTH_PX = 400; 
  const A5_WIDTH_MM = 148;
  const A5_HEIGHT_MM = 210;
  const EDITOR_SCALE = EDITOR_WIDTH_PX / A5_WIDTH_MM;

  return (
    <div className="h-screen flex flex-col bg-gray-100 overflow-hidden font-sans relative">
      {/* Variant Modal */}
      {variantModal && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/20 backdrop-blur-sm" onClick={() => setVariantModal(null)}>
              <div className="bg-white rounded-lg shadow-2xl border border-gray-200 w-[500px] max-w-full m-4 flex flex-col overflow-hidden" onClick={e => e.stopPropagation()}>
                  <div className="flex items-center justify-between p-4 border-b border-gray-100">
                      <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wide">Escolha o estilo de {variantModal.label}</h3>
                      <button onClick={() => setVariantModal(null)} className="text-gray-400 hover:text-red-500"><X className="w-5 h-5"/></button>
                  </div>
                  <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto max-h-[60vh]">
                      {ELEMENT_VARIANTS[variantModal.type]?.map((variant, idx) => (
                          <div 
                            key={idx}
                            onClick={() => addElement(variantModal.type, variantModal.label, variant.styleOverride, variant.defaultSize)}
                            className="border border-gray-200 rounded-lg p-4 hover:border-indigo-500 hover:bg-indigo-50 cursor-pointer transition-all flex flex-col items-center gap-3 group"
                          >
                              {/* Preview Box - Simplified Rendering just for the idea */}
                              <div className="w-full h-24 bg-white border border-gray-100 rounded flex items-center justify-center overflow-hidden relative shadow-sm">
                                  {/* We actually render a mini version of the element here if possible, or just a placeholder */}
                                  <div className="scale-75 origin-center">
                                     {/* Hacky preview: Rendering the element type with the style override */}
                                     {variantModal.type === 'day_number' && <span style={{ ...variant.styleOverride } as any}>24</span>}
                                     {variantModal.type === 'day_name' && <span style={{ ...variant.styleOverride } as any}>Sábado</span>}
                                     {variantModal.type === 'month_name' && <span style={{ ...variant.styleOverride } as any}>Julho</span>}
                                     {variantModal.type === 'moon' && (
                                         <div className="flex items-center gap-2">
                                            {(variant.styleOverride.variant !== 'icon_only') && <span style={{...variant.styleOverride} as any}>Lua cheia</span>}
                                            <Moon className="w-6 h-6" fill={variant.styleOverride.color} />
                                         </div>
                                     )}
                                     {variantModal.type === 'vector_flower' && (
                                         <div className="w-10 h-10">
                                            {variant.name === 'Flor' && <Flower className="w-full h-full" color={variant.styleOverride.color} fill={variant.styleOverride.backgroundColor} />}
                                            {variant.name === 'Estrela' && <Star className="w-full h-full" color={variant.styleOverride.color} fill={variant.styleOverride.backgroundColor} />}
                                            {variant.name === 'Coração' && <Heart className="w-full h-full" color={variant.styleOverride.color} fill={variant.styleOverride.backgroundColor} />}
                                            {variant.name === 'Folha' && <Leaf className="w-full h-full" color={variant.styleOverride.color} fill={variant.styleOverride.backgroundColor} />}
                                         </div>
                                     )}
                                     {variantModal.type === 'lines' && <div className="flex flex-col gap-2 w-20"><div className="h-px bg-gray-300 w-full"/><div className="h-px bg-gray-300 w-full"/><div className="h-px bg-gray-300 w-full"/></div>}
                                  </div>
                              </div>
                              <div className="text-center">
                                  <div className="text-sm font-bold text-gray-700 group-hover:text-indigo-700">{variant.name}</div>
                                  <div className="text-xs text-gray-400">{variant.description}</div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      {/* Top Bar */}
      <header className="bg-white border-b border-gray-200 h-14 flex items-center justify-between px-4 z-20 shrink-0">
        <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-1.5 rounded">
                <Calendar className="h-4 w-4 text-white" />
            </div>
            <span className="font-bold text-gray-800 hidden md:block">AgendaMaster AI</span>
            <span className="px-2 py-0.5 rounded-full bg-gray-100 text-xs text-gray-500 border border-gray-200">Editor</span>
        </div>

        <div className="flex items-center space-x-2 bg-gray-100 p-1 rounded-lg">
            <button 
                onClick={() => setActiveTab('editor')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'editor' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Editar Template
            </button>
            <button 
                onClick={() => setActiveTab('preview')}
                className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${activeTab === 'preview' ? 'bg-white shadow text-indigo-600' : 'text-gray-500 hover:text-gray-700'}`}
            >
                Visualizar & Imprimir
            </button>
        </div>

        <div className="flex items-center space-x-3">
             <button onClick={() => setShowMargins(!showMargins)} className={`p-1.5 rounded-md transition-all ${showMargins ? 'bg-indigo-50 text-indigo-600 ring-1 ring-indigo-200' : 'text-gray-400 hover:text-gray-600'}`} title={showMargins ? "Ocultar Guias de Margem" : "Mostrar Guias de Margem"}><ScanLine className="w-5 h-5" /></button>
             <div className="h-5 w-px bg-gray-200"></div>
             <button onClick={() => window.print()} className="flex items-center text-xs font-medium text-gray-700 hover:text-indigo-600 bg-gray-50 px-3 py-1.5 rounded border border-gray-200"><Printer className="w-4 h-4 mr-1" /> Imprimir</button>
             <button onClick={onLogout} className="text-gray-400 hover:text-red-500"><LogOut className="w-4 h-4" /></button>
        </div>
      </header>

      <div className="flex-1 flex overflow-hidden">

        {/* LEFT SIDEBAR: Tools & Config */}
        <aside className="w-72 bg-white border-r border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">

            {/* Page Setup */}
            <div className="p-4 border-b border-gray-100">
                <div className="flex items-center mb-3 text-gray-400">
                     <Settings2 className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Configuração</h3>
                </div>

                <div className="space-y-3 mb-6">
                    <div>
                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Ano da Agenda</label>
                        <input type="number" value={config.year} onChange={(e) => setConfig(prev => ({...prev, year: parseInt(e.target.value) || new Date().getFullYear()}))} className="w-full text-xs border border-gray-300 rounded-md shadow-sm p-2 bg-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500" />
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-gray-500 uppercase mb-1">Tipo de Layout</label>
                        <select value={config.layoutType} onChange={(e) => setConfig(c => ({...c, layoutType: e.target.value as PageLayoutType}))} className="w-full text-xs border border-gray-300 rounded-md shadow-sm p-2 bg-white focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500">
                            <option value="1_per_page">1 Dia por Página</option>
                            <option value="2_per_page">2 Dias por Página</option>
                            <option value="1_per_page_weekend_shared">1 Dia + FDS Dividido</option>
                        </select>
                    </div>
                    <div className="space-y-2 pt-2 border-t border-gray-100">
                        <label className="flex items-center space-x-2 cursor-pointer"><input type="checkbox" checked={config.includeHolidays} onChange={(e) => setConfig(prev => ({...prev, includeHolidays: e.target.checked}))} className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300" /><span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Feriados</span></label>
                        <label className="flex items-center space-x-2 cursor-pointer"><input type="checkbox" checked={config.includeMoonPhases} onChange={(e) => setConfig(prev => ({...prev, includeMoonPhases: e.target.checked}))} className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300" /><span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Fases da Lua</span></label>
                        <label className="flex items-center space-x-2 cursor-pointer"><input type="checkbox" checked={config.includeQuotes} onChange={(e) => setConfig(prev => ({...prev, includeQuotes: e.target.checked}))} className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300" /><span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Frases (IA)</span></label>
                    </div>
                </div>

                <div className="bg-gray-50 p-3 rounded border border-gray-200">
                     <div className="text-[10px] font-bold text-gray-500 mb-2 uppercase">Margens (mm)</div>
                     <div className="grid grid-cols-2 gap-2">
                        <div><label className="text-[10px] text-gray-400">Topo</label><input type="number" value={config.margins.top} onChange={(e) => updateConfig('margins.top', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" /></div>
                        <div><label className="text-[10px] text-gray-400">Base</label><input type="number" value={config.margins.bottom} onChange={(e) => updateConfig('margins.bottom', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" /></div>
                        <div><label className="text-[10px] text-gray-400">Esq</label><input type="number" value={config.margins.left} onChange={(e) => updateConfig('margins.left', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" /></div>
                        <div><label className="text-[10px] text-gray-400">Dir</label><input type="number" value={config.margins.right} onChange={(e) => updateConfig('margins.right', parseInt(e.target.value))} className="w-full text-xs p-1 border rounded" /></div>
                     </div>
                </div>
            </div>

            {/* Draggable Elements */}
            <div className="p-4 border-b border-gray-100">
                <div className="flex items-center mb-3 text-gray-400">
                     <Layout className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Adicionar Elemento</h3>
                </div>

                <div className="grid grid-cols-3 gap-2">
                    <button onClick={() => openElementSelector('day_number', 'Número do Dia')} title="Número do Dia" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><span className="text-lg font-bold text-gray-800">24</span></button>
                    <button onClick={() => openElementSelector('day_name', 'Dia da Semana')} title="Nome do Dia" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><span className="text-xs font-bold text-gray-600">Sábado</span></button>
                    <button onClick={() => openElementSelector('month_name', 'Mês')} title="Mês" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><span className="text-xs text-gray-500">Julho</span></button>
                    <button onClick={() => addElement('text', 'Texto')} title="Texto Livre" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Type className="w-5 h-5 text-gray-500" /></button>

                    <button onClick={() => addElement('box', 'Caixa')} title="Caixa" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Square className="w-5 h-5 text-gray-400" /></button>
                    <button onClick={() => addElement('circle', 'Círculo')} title="Círculo" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Circle className="w-5 h-5 text-gray-400" /></button>
                    <button onClick={() => openElementSelector('lines', 'Pautas')} title="Pauta" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><ListTodo className="w-5 h-5 text-gray-400" /></button>

                    <button onClick={() => addElement('note_grid', 'Grid')} title="Grid de Anotação" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Grid3X3 className="w-5 h-5 text-gray-400" /></button>
                    <button onClick={() => addElement('habit_tracker', 'Habit Tracker')} title="Habit Tracker" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><span className="text-[8px] text-gray-500 font-bold">HABITS</span></button>
                    <button onClick={() => openElementSelector('vector_flower', 'Vetor')} title="Flor/Vetor" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Flower className="w-5 h-5 text-gray-400" /></button>

                    <button onClick={() => addElement('holiday', 'Feriado')} title="Feriado" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Palmtree className="w-5 h-5 text-red-400" /></button>
                    <button onClick={() => openElementSelector('moon', 'Fase da Lua')} title="Fase da Lua" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><Moon className="w-5 h-5 text-gray-400" /></button>
                    <button onClick={() => addElement('quote', 'Frase IA')} title="Frase (IA)" className="h-14 flex flex-col items-center justify-center p-2 border border-gray-200 rounded hover:bg-indigo-50 hover:border-indigo-300 transition-all"><ArrowDownAZ className="w-5 h-5 text-indigo-400" /></button>
                </div>
            </div>

            {/* Layers List (Separate Elements) */}
            <div className="p-4 flex-1 overflow-y-auto">
                 <div className="flex items-center mb-3 text-gray-400">
                     <Layers className="w-4 h-4 mr-2" />
                     <h3 className="text-xs font-semibold uppercase tracking-wider">Camadas</h3>
                </div>
                <div className="space-y-1">
                    {config.elements.slice().reverse().map((el) => (
                        <div key={el.id} onClick={() => setSelectedId(el.id)} className={`flex items-center p-2 rounded text-xs cursor-pointer border ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}><span className="flex-1 truncate font-medium">{el.name || el.type}</span><button onClick={(e) => { e.stopPropagation(); removeElement(el.id); }} className="text-gray-400 hover:text-red-500 p-1"><Trash2 className="w-3 h-3" /></button></div>
                    ))}
                    {config.elements.length === 0 && (<p className="text-center text-gray-400 text-xs py-4 italic">Sem elementos</p>)}
                </div>
            </div>
        </aside>

        {/* MAIN AREA */}
        <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">

            {activeTab === 'editor' && (
                <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden">
                    {config.layoutType === '1_per_page_weekend_shared' && (
                        <div className="mb-4 bg-white p-1 rounded-lg shadow-sm flex space-x-1">
                            <button onClick={() => setEditorViewMode('standard')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'standard' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Dias da Semana (Pág Inteira)</button>
                            <button onClick={() => setEditorViewMode('weekend')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'weekend' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Fim de Semana (Dividido)</button>
                        </div>
                    )}
                    <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar">
                        <div className="flex flex-col items-center">
                             <div className="text-xs text-gray-500 mb-2 font-mono uppercase tracking-wide">{config.layoutType === '2_per_page' ? 'Visualização: 2 Dias / Pág' : config.layoutType === '1_per_page_weekend_shared' && editorViewMode === 'weekend' ? 'Visualização: Fim de Semana' : 'Visualização: Pág Inteira'}</div>
                             {renderEditorPage()}
                            <div className="text-xs text-gray-400 mt-4 text-center max-w-md">{config.layoutType === '2_per_page' ? 'As alterações são espelhadas nos dois blocos.' : 'Edite o layout do dia.'}</div>
                        </div>
                    </div>
                </div>
            )}

            {activeTab === 'preview' && (
                <div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500">
                    <div className="max-w-[210mm] mx-auto">
                        <div id="print-area">
                             {generatedData.length === 0 ? (<div className="text-center py-20 text-white">Carregando visualização...</div>) : (
                                 <div className="space-y-8">
                                    <div className="p-4 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 text-sm mb-4 no-print shadow-lg"><p className="font-bold">Modo de Pré-visualização</p><p>Mostrando as primeiras 4 páginas. Clique em "Imprimir" para gerar o PDF completo de 365 dias.</p></div>
                                    <div className="print-only hidden">{renderPrintLayout()}</div>
                                    <div className="no-print">{renderPrintLayout().slice(0, 4)}</div>
                                 </div>
                             )}
                        </div>
                    </div>
                </div>
            )}
        </main>

        {/* RIGHT SIDEBAR: Properties */}
        {activeTab === 'editor' && (
            <aside className="w-72 bg-white border-l border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">
                <div className="p-4 border-b border-gray-100 bg-gray-50"><h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Propriedades</h3></div>

                {selectedElement ? (
                    <div className="p-4 space-y-5">
                         <div className="space-y-2">
                             <label className="block text-[10px] font-bold text-gray-500 uppercase">Nome da Camada</label>
                             <input type="text" value={selectedElement.name || selectedElement.type} onChange={(e) => updateElementName(selectedElement.id, e.target.value)} className="w-full text-xs p-2 border border-gray-200 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500" />
                         </div>
                         <div className="h-px bg-gray-100"></div>

                         {/* Position & Size */}
                         <div className="grid grid-cols-2 gap-3">
                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Largura %</label><div className="flex items-center"><input type="range" min="5" max="100" value={Math.round(selectedElement.w)} onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el)}))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.w)}</span></div></div>
                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Altura %</label><div className="flex items-center"><input type="range" min="2" max="100" value={Math.round(selectedElement.h)} onChange={(e) => setConfig(prev => ({...prev, elements: prev.elements.map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el)}))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.h)}</span></div></div>
                         </div>

                         {/* Typography */}
                         {['day_number', 'day_name', 'month_name', 'year', 'quote', 'text', 'holiday', 'moon'].includes(selectedElement.type) && (
                             <div className="space-y-3 pt-3 border-t border-gray-100">
                                 <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Fonte</label>
                                    <div className="relative">
                                        <select value={selectedElement.style.fontFamily || 'Inter'} onChange={(e) => updateElementStyle(selectedElement.id, { fontFamily: e.target.value })} className="w-full text-xs p-2 border border-gray-200 rounded appearance-none bg-white" style={{ fontFamily: selectedElement.style.fontFamily }}>
                                            <optgroup label="Padrão">{AVAILABLE_FONTS.map(font => (<option key={font} value={font} style={{ fontFamily: font }}>{font}</option>))}</optgroup>
                                            {customFonts.length > 0 && (<optgroup label="Minhas Fontes">{customFonts.map(font => (<option key={font} value={font} style={{ fontFamily: font }}>{font}</option>))}</optgroup>)}
                                        </select>
                                        <ChevronDown className="w-3 h-3 text-gray-400 absolute right-2 top-2.5 pointer-events-none" />
                                    </div>
                                    <button onClick={() => fileInputRef.current?.click()} className="mt-2 w-full flex items-center justify-center px-2 py-1.5 border border-dashed border-gray-300 rounded text-[10px] text-gray-500 hover:bg-gray-50 hover:text-indigo-600 transition-colors"><Upload className="w-3 h-3 mr-1.5" /> Carregar Fonte (.ttf/.otf)</button>
                                    <input type="file" accept=".ttf,.otf,.woff,.woff2" ref={fileInputRef} className="hidden" onChange={handleFontUpload} />
                                 </div>

                                 <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Tamanho</label><input type="range" min="8" max="120" value={selectedElement.style.fontSize} onChange={(e) => updateElementStyle(selectedElement.id, { fontSize: parseInt(e.target.value) })} className="w-full" /></div>

                                 <div>
                                     <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Alinhamento</label>
                                     <div className="flex border border-gray-200 rounded overflow-hidden">
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'left' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'left' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignLeft className="w-4 h-4 mx-auto"/></button>
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'center' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'center' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignCenter className="w-4 h-4 mx-auto"/></button>
                                         <button onClick={() => updateElementStyle(selectedElement.id, { textAlign: 'right' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${selectedElement.style.textAlign === 'right' ? 'bg-indigo-50 text-indigo-600' : ''}`}><AlignRight className="w-4 h-4 mx-auto"/></button>
                                     </div>
                                 </div>
                             </div>
                         )}

                         {/* Colors & Appearance */}
                         <div className="space-y-3 pt-3 border-t border-gray-100">
                             <div>
                                 <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">{selectedElement.type === 'vector_flower' ? 'Cor do Contorno' : 'Cor Principal'}</label>
                                 <div className="flex space-x-2">
                                     <input type="color" value={selectedElement.style.color || '#000000'} onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })} className="h-8 w-8 rounded cursor-pointer p-0 border-0" />
                                     <input type="text" value={selectedElement.style.color} onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })} className="flex-1 border border-gray-200 rounded px-2 text-xs uppercase" />
                                 </div>
                             </div>

                             {(selectedElement.type === 'box' || selectedElement.type === 'circle' || selectedElement.type === 'vector_flower' || selectedElement.type === 'day_number') && (
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">{selectedElement.type === 'vector_flower' ? 'Cor do Preenchimento' : 'Cor de Fundo'}</label>
                                    <div className="flex space-x-2">
                                        <input type="color" value={selectedElement.style.backgroundColor || '#ffffff'} onChange={(e) => updateElementStyle(selectedElement.id, { backgroundColor: e.target.value })} className="h-8 w-8 rounded cursor-pointer p-0 border-0" />
                                        <button onClick={() => updateElementStyle(selectedElement.id, { backgroundColor: 'transparent' })} className="text-xs px-2 border border-gray-200 rounded hover:bg-gray-50">Transparente</button>
                                    </div>
                                </div>
                             )}

                             <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Opacidade</label><input type="range" min="0" max="1" step="0.1" value={selectedElement.style.opacity ?? 1} onChange={(e) => updateElementStyle(selectedElement.id, { opacity: parseFloat(e.target.value) })} className="w-full" /></div>

                             {/* Transformations */}
                             <div className="pt-3 border-t border-gray-100">
                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Transformação</label>
                                <div className="mb-2"><span className="text-[10px] text-gray-400">Rotação</span><input type="range" min="0" max="360" value={selectedElement.style.rotation || 0} onChange={(e) => updateElementStyle(selectedElement.id, { rotation: parseInt(e.target.value) })} className="w-full" /></div>
                                <div className="flex gap-2">
                                    <button onClick={() => updateElementStyle(selectedElement.id, { flipX: !selectedElement.style.flipX })} className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipX ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`} title="Espelhar Horizontalmente"><FlipHorizontal className="w-4 h-4 mr-1" /> Horiz.</button>
                                    <button onClick={() => updateElementStyle(selectedElement.id, { flipY: !selectedElement.style.flipY })} className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipY ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`} title="Espelhar Verticalmente"><FlipVertical className="w-4 h-4 mr-1" /> Vert.</button>
                                </div>
                             </div>
                         </div>

                         {/* Specifics */}
                         {selectedElement.type === 'lines' && (
                             <div className="pt-3 border-t border-gray-100 space-y-3">
                                <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Espaçamento das Linhas</label><input type="range" min="10" max="60" value={selectedElement.style.lineSpacing} onChange={(e) => updateElementStyle(selectedElement.id, { lineSpacing: parseInt(e.target.value) })} className="w-full" /></div>
                                <div className="bg-gray-50 p-2 rounded border border-gray-200">
                                    <div className="flex items-center justify-between mb-2"><label className="text-[10px] font-bold text-gray-500 uppercase flex items-center"><Clock className="w-3 h-3 mr-1" /> Horários</label><input type="checkbox" checked={selectedElement.style.showTimes || false} onChange={(e) => updateElementStyle(selectedElement.id, { showTimes: e.target.checked })} className="h-4 w-4 text-indigo-600 rounded" /></div>
                                    {selectedElement.style.showTimes && (<div className="flex items-center space-x-2"><label className="text-[10px] text-gray-400">Início (h)</label><input type="number" min="0" max="23" value={selectedElement.style.startHour || 7} onChange={(e) => updateElementStyle(selectedElement.id, { startHour: parseInt(e.target.value) })} className="w-16 text-xs p-1 border rounded" /></div>)}
                                </div>
                             </div>
                         )}

                         <div className="pt-6">
                            <button onClick={() => removeElement(selectedElement.id)} className="w-full py-2 px-4 bg-white border border-red-200 text-red-600 rounded hover:bg-red-50 flex items-center justify-center text-sm transition-colors"><Trash2 className="w-4 h-4 mr-2" /> Excluir Elemento</button>
                         </div>
                    </div>
                ) : (
                    <div className="p-8 text-center text-gray-400 flex flex-col items-center justify-center h-full">
                        <Move className="w-12 h-12 mb-4 opacity-20" />
                        <p className="text-sm font-medium">Nenhum elemento selecionado</p>
                        <p className="text-xs mt-2 opacity-70">Clique em um elemento na lista de camadas ou no layout para editar.</p>
                    </div>
                )}
            </aside>
        )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Login from './components/Login';
import { Dashboard } from './components/Dashboard';
import { User, AppState } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.LOGIN);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setAppState(AppState.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAppState(AppState.LOGIN);
  };

  return (
    <>
      {appState === AppState.LOGIN && (
        <Login onLogin={handleLogin} />
      )}

      {appState === AppState.DASHBOARD && currentUser && (
        <Dashboard user={currentUser} onLogout={handleLogout} />
      )}
    </>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType } from '../types';
import { generateCalendarYear, getMonthName, getDayName } from '../services/calendarService';
import { generateMonthlyQuotes } from '../services/geminiService';
import { 
  Calendar, Printer, LogOut, Moon, Type, 
  Trash2, Move, AlignLeft, AlignCenter, AlignRight, Layout,
  Square, Circle, Flower, ListTodo, Grid3X3, ArrowDownAZ,
  Maximize, Minimize, Settings2, ScanLine, FlipHorizontal, FlipVertical,
  Layers, Upload, ChevronRight, ChevronDown, Plus, FontInput, Clock,
  CalendarDays, Palmtree, X, Star, Heart, Leaf
} from 'lucide-react';

interface DashboardProps {
