import { GoogleGenAI, Type } from "@google/genai";

const getClient = () => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) return null;
    return new GoogleGenAI({ apiKey });
}

export const generateMonthlyQuotes = async (year: number): Promise<string[]> => {
  const ai = getClient();
  if (!ai) return Array(12).fill("A criatividade requer coragem.");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Gere 12 frases motivacionais para ${year}. Array JSON de strings.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } }
      }
    });

    const jsonStr = response.text;
    if (jsonStr) {
      const parsed = JSON.parse(jsonStr);
      if (Array.isArray(parsed)) return parsed.slice(0, 12);
    }
    return Array(12).fill("Planeje hoje para colher amanhã.");
  } catch (error) {
    return Array(12).fill("A persistência é o caminho do êxito.");
  }
};

// --- INTERACTION MATH ---
// Cálculos de geometria para o editor visual.

export const snap = (val: number) => Math.round(val * 2) / 2;

export const calculateDragPosition = (
    deltaX: number, 
    deltaY: number, 
    initialX: number, 
    initialY: number, 
    containerWidth: number, 
    containerHeight: number
) => {
    const dX = (deltaX / containerWidth) * 100;
    const dY = (deltaY / containerHeight) * 100;

    return {
        x: snap(initialX + dX),
        y: snap(initialY + dY)
    };
};

export const calculateResize = (
    deltaX: number,
    deltaY: number,
    initialX: number,
    initialY: number,
    initialW: number,
    initialH: number,
    containerWidth: number,
    containerHeight: number,
    direction: string
) => {
    const dX = (deltaX / containerWidth) * 100;
    const dY = (deltaY / containerHeight) * 100;

    let newX = initialX;
    let newY = initialY;
    let newW = initialW;
    let newH = initialH;

    // Horizontal
    if (direction.includes('e')) {
        newW = Math.max(2, snap(initialW + dX));
    }
    if (direction.includes('w')) {
        const desiredW = Math.max(2, snap(initialW - dX));
        const deltaW = desiredW - initialW;
        if (desiredW !== initialW) {
            newX = snap(initialX - deltaW);
            newW = desiredW;
        }
    }

    // Vertical
    if (direction.includes('s')) {
        newH = Math.max(2, snap(initialH + dY));
    }
    if (direction.includes('n')) {
         const desiredH = Math.max(2, snap(initialH - dY));
         const deltaH = desiredH - initialH;
         if (desiredH !== initialH) {
             newY = snap(initialY - deltaH);
             newH = desiredH;
         }
    }

    return { x: newX, y: newY, w: newW, h: newH };
};

