            {/* Elementos (Toolbox) */}
            <div className="p-4 border-b border-gray-100">
                <div className="flex items-center mb-3 text-gray-400"><Layout className="w-4 h-4 mr-2" /><h3 className="text-xs font-semibold uppercase tracking-wider">Elementos</h3></div>
