                        <>
                            <button onClick={() => setVariantModal({type: 'day_number', label: 'Número'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="font-bold">24</span></button>
                            <button onClick={() => setVariantModal({type: 'day_name', label: 'Dia'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-xs font-bold">SEG</span></button>
                            <button onClick={() => setVariantModal({type: 'month_name', label: 'Mês'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-xs">MÊS</span></button>
                        </>
                    )}
                    <button onClick={() => addElement('text', 'Texto')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Type className="w-5 h-5"/></button>
                    <button onClick={() => addElement('box', 'Caixa')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Square className="w-5 h-5"/></button>
                    <button onClick={() => addElement('circle', 'Círculo')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Circle className="w-5 h-5"/></button>
                    <button onClick={() => setVariantModal({type: 'lines', label: 'Pautas'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><ListTodo className="w-5 h-5"/></button>
                    <button onClick={() => setVariantModal({type: 'mini_calendar', label: 'Calendário'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><CalendarDays className="w-5 h-5"/></button>
                    <button onClick={() => setVariantModal({type: 'vector_flower', label: 'Vetor'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Flower className="w-5 h-5"/></button>
                </div>
                {editMode === 'intro' && <p className="text-[10px] text-gray-400 mt-2 italic">Alguns elementos de data (Dia, Mês) não estão disponíveis em páginas estáticas.</p>}
            </div>

            {/* Camadas */}
            <div className="p-4 flex-1 overflow-y-auto">
                <div className="flex items-center mb-3 text-gray-400"><Layers className="w-4 h-4 mr-2" /><h3 className="text-xs font-semibold uppercase tracking-wider">Camadas ({editMode === 'daily' ? 'Miolo' : 'Página'})</h3></div>
                <div className="space-y-1">
                    {getActiveElements().slice().reverse().map((el) => (
                        <div key={el.id} onClick={() => setSelectedId(el.id)} className={`flex items-center p-2 rounded text-xs cursor-pointer border group/layer ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}>
                            <span className="flex-1 truncate font-medium">{el.name || el.type}</span>
                            <div className="flex items-center opacity-0 group-hover/layer:opacity-100 transition-opacity">
                                <button onClick={(e) => moveLayer(el.id, 'up')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-0.5" title="Mover para Frente">
                                    <ChevronUp className="w-3 h-3" />
                                </button>
                                <button onClick={(e) => moveLayer(el.id, 'down')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-1" title="Mover para Trás">
                                    <ChevronDown className="w-3 h-3" />
                                </button>
                                <button onClick={(e) => { e.stopPropagation(); removeElement(el.id); }} className="text-gray-400 hover:text-red-500 p-1 hover:bg-red-50 rounded">
                                    <Trash2 className="w-3 h-3" />
                                </button>
                            </div>
                        </div>
                    ))}
                    {getActiveElements().length === 0 && (<p className="text-center text-gray-400 text-xs py-4 italic">Sem elementos</p>)}
                </div>
            </div>
        </aside>

        <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">
            {activeTab === 'editor' && (
                <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden">
                    {config.layoutType === '1_per_page_weekend_shared' && editMode === 'daily' && (
                        <div className="mb-4 bg-white p-1 rounded-lg shadow-sm flex space-x-1 z-10">
                            <button onClick={() => setEditorViewMode('standard')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'standard' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Dias da Semana</button>
                            <button onClick={() => setEditorViewMode('weekend')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'weekend' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Fim de Semana</button>
                        </div>
                    )}
                    {editMode === 'intro' && (
                        <div className="mb-4 bg-indigo-100 text-indigo-800 px-3 py-1 rounded text-xs font-bold uppercase tracking-wide z-10 shadow-sm border border-indigo-200">
                            Editando: {config.introPages.find(p => p.id === currentIntroPageId)?.name || 'Página'}
                        </div>
                    )}
                    <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar">
                        <div className="flex flex-col items-center">{renderEditorPage()}</div>
                    </div>
                </div>
            )}
            {activeTab === 'preview' && (<div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500"><div className="max-w-[210mm] mx-auto"><div id="print-area">{generatedData.length === 0 ? (<div className="text-center py-20 text-white">Carregando visualização...</div>) : (<div className="space-y-8"><div className="p-4 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 text-sm mb-4 no-print shadow-lg"><p className="font-bold">Pré-visualização (Início + 4 Pág Miolo)</p></div><div className="no-print">{renderPrintLayout().slice(0, config.introPages.length + 4)}</div></div>)}</div></div></div>)}
        </main>

        {activeTab === 'editor' && (
            <aside className="w-72 bg-white border-l border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">
                <div className="p-4 border-b border-gray-100 bg-gray-50"><h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Propriedades</h3></div>
                {selectedElement ? (
                    <div className="p-4 space-y-5">
                         <div><label className="block text-[10px] font-bold text-gray-500 uppercase">Nome</label><input type="text" value={selectedElement.name || selectedElement.type} onChange={(e) => updateElementName(selectedElement.id, e.target.value)} className="w-full text-xs p-2 border border-gray-200 rounded" /></div>
                         <div className="grid grid-cols-2 gap-3"><div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Largura %</label><input type="range" min="5" max="100" value={Math.round(selectedElement.w)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el))} className="w-full" /></div><div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Altura %</label><input type="range" min="2" max="100" value={Math.round(selectedElement.h)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el))} className="w-full" /></div></div>
                         <div className="pt-6"><button onClick={() => removeElement(selectedElement.id)} className="w-full py-2 px-4 bg-white border border-red-200 text-red-600 rounded hover:bg-red-50 flex items-center justify-center text-sm"><Trash2 className="w-4 h-4 mr-2" /> Excluir</button></div>
                    </div>
                ) : <div className="p-8 text-center text-gray-400"><Move className="w-12 h-12 mb-4 opacity-20 mx-auto" /><p className="text-sm">Selecione um elemento</p></div>}
            </aside>
        )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
