                                                 />
                                                 Destacar Domingos
                                             </label>
                                             <label className="flex items-center text-xs text-gray-600 cursor-pointer">
                                                 <input 
                                                    type="checkbox" 
                                                    checked={selectedElement.style.fullCalendar.specialDays?.highlightHolidays || false} 
                                                    onChange={(e) => updateFullCalendarSpecialFlags(selectedElement.id, { highlightHolidays: e.target.checked })}
