                    {editMode === 'daily' && (<><button onClick={() => setVariantModal({type: 'day_number', label: 'Número'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="font-bold">24</span></button><button onClick={() => setVariantModal({type: 'day_name', label: 'Dia'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-xs font-bold">SEG</span></button><button onClick={() => setVariantModal({type: 'month_name', label: 'Mês'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><span className="text-xs">MÊS</span></button></>)}
                    <button onClick={() => addElement('text', 'Texto')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Type className="w-5 h-5"/></button><button onClick={() => addElement('box', 'Caixa')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Square className="w-5 h-5"/></button><button onClick={() => addElement('circle', 'Círculo')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Circle className="w-5 h-5"/></button><button onClick={() => setVariantModal({type: 'lines', label: 'Pautas'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><ListTodo className="w-5 h-5"/></button><button onClick={() => addElement('mini_calendar', 'Calendário')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><CalendarDays className="w-5 h-5"/></button><button onClick={() => setVariantModal({type: 'vector_flower', label: 'Vetor'})} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50"><Flower className="w-5 h-5"/></button>
                    {editMode === 'intro' && (<><button onClick={() => addElement('full_calendar', 'Calendário Anual')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50" title="Calendário Anual (Grid)"><Grid className="w-5 h-5 mr-1" /><span className="text-[10px]">Anual</span></button><button onClick={() => addElement('holiday_list', 'Lista Feriados')} className="h-14 flex items-center justify-center border rounded hover:bg-indigo-50" title="Lista de Feriados"><List className="w-5 h-5 mr-1" /><span className="text-[10px]">Feriados</span></button></>)}
                </div>
            </div>
            <div className="p-4 flex-1 overflow-y-auto">
                <div className="flex items-center mb-3 text-gray-400"><Layers className="w-4 h-4 mr-2" /><h3 className="text-xs font-semibold uppercase tracking-wider">Camadas ({editMode === 'daily' ? 'Miolo' : 'Página'})</h3></div>
                <div className="space-y-1">
                    {getActiveElements().slice().reverse().map((el) => (<div key={el.id} onClick={() => setSelectedId(el.id)} className={`flex items-center p-2 rounded text-xs cursor-pointer border group/layer ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}><span className="flex-1 truncate font-medium">{el.name || el.type}</span><div className="flex items-center opacity-0 group-hover/layer:opacity-100 transition-opacity"><button onClick={(e) => moveLayer(el.id, 'up')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-0.5"><ChevronUp className="w-3 h-3" /></button><button onClick={(e) => moveLayer(el.id, 'down')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-1"><ChevronDown className="w-3 h-3" /></button><button onClick={(e) => { e.stopPropagation(); removeElement(el.id); }} className="text-gray-400 hover:text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 className="w-3 h-3" /></button></div></div>))}
                </div>
            </div>
        </aside>

        <main className="flex-1 bg-gray-200 overflow-hidden relative flex flex-col items-center">
            {activeTab === 'editor' && (
                <div className="flex-1 w-full flex flex-col items-center p-4 overflow-hidden">
                    {config.layoutType === '1_per_page_weekend_shared' && editMode === 'daily' && (<div className="mb-4 bg-white p-1 rounded-lg shadow-sm flex space-x-1 z-10"><button onClick={() => setEditorViewMode('standard')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'standard' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Dias da Semana</button><button onClick={() => setEditorViewMode('weekend')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'weekend' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Fim de Semana</button></div>)}
                    {editMode === 'intro' && (<div className="mb-4 bg-indigo-100 text-indigo-800 px-3 py-1 rounded text-xs font-bold uppercase tracking-wide z-10 shadow-sm border border-indigo-200">Editando: {config.introPages.find(p => p.id === currentIntroPageId)?.name || 'Página'}</div>)}
                    <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar"><div className="flex flex-col items-center">{renderEditorPage()}</div></div>
                </div>
            )}
            {activeTab === 'preview' && (<div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500"><div className="max-w-[210mm] mx-auto"><div id="print-area">{generatedData.length === 0 ? (<div className="text-center py-20 text-white">Carregando visualização...</div>) : (<div className="space-y-8"><div className="p-4 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 text-sm mb-4 no-print shadow-lg"><p className="font-bold">Pré-visualização (Início + 4 Pág Miolo)</p><p className="text-xs font-normal mt-1 text-yellow-800">Tamanho: {config.pageSize} ({PAGE_WIDTH_MM}mm x {PAGE_HEIGHT_MM}mm) - {config.orientation === 'portrait' ? 'Retrato' : 'Paisagem'}</p></div><div className="no-print">{renderPrintLayout().slice(0, config.introPages.length + 4)}</div></div>)}</div></div></div>)}
        </main>

        {activeTab === 'editor' && (
            <aside className="w-72 bg-white border-l border-gray-200 flex flex-col shrink-0 z-10 no-print overflow-y-auto custom-scrollbar">
                <div className="p-4 border-b border-gray-100 bg-gray-50"><h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Propriedades</h3></div>

                {selectedElement ? (
                    <div className="p-4 space-y-5">
                         <div className="space-y-2">
                             <label className="block text-[10px] font-bold text-gray-500 uppercase">Nome da Camada</label>
                             <input type="text" value={selectedElement.name || selectedElement.type} onChange={(e) => updateElementName(selectedElement.id, e.target.value)} className="w-full text-xs p-2 border border-gray-200 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500" />
                         </div>
                         <div className="h-px bg-gray-100"></div>

                         <div className="grid grid-cols-2 gap-3">
                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Largura %</label><div className="flex items-center"><input type="range" min="5" max="100" value={Math.round(selectedElement.w)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.w)}</span></div></div>
                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Altura %</label><div className="flex items-center"><input type="range" min="2" max="100" value={Math.round(selectedElement.h)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.h)}</span></div></div>
                         </div>

                         {(selectedElement.type === 'full_calendar' || selectedElement.type === 'mini_calendar') && selectedElement.style.fullCalendar && (
                             <div className="pt-3 border-t border-gray-100">
                                 <div className="space-y-3 mb-3">
                                     <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Configuração do Grid</h4>

                                     {selectedElement.type === 'full_calendar' && (
                                         <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Meses por Linha ({selectedElement.style.monthsPerRow})</label><input type="range" min="1" max="12" value={selectedElement.style.monthsPerRow || 3} onChange={(e) => updateElementStyle(selectedElement.id, { monthsPerRow: parseInt(e.target.value) })} className="w-full" /></div>
                                     )}

                                     {selectedElement.type === 'mini_calendar' && (
                                         <div>
                                             <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Mês Exibido</label>
                                             <div className="flex rounded border border-gray-200 overflow-hidden">
                                                 <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: -1 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === -1 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Anterior</button>
                                                 <div className="w-px bg-gray-200"></div>
                                                 <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: 0 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === 0 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Atual</button>
                                                 <div className="w-px bg-gray-200"></div>
                                                 <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: 1 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === 1 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Próximo</button>
                                             </div>
                                         </div>
                                     )}

                                     {selectedElement.type === 'full_calendar' && (
                                         <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Espaçamento (Gap)</label><input type="range" min="0" max="50" value={selectedElement.style.gap || 10} onChange={(e) => updateElementStyle(selectedElement.id, { gap: parseInt(e.target.value) })} className="w-full" /></div>
                                     )}
                                 </div>

                                 {selectedElement.style.fullCalendar.grid && (
                                     <div className="space-y-3 mb-3 bg-gray-50 p-2 rounded border border-gray-200">
                                         <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Bordas da Tabela</h4>
                                         <div className="grid grid-cols-3 gap-1 mb-2">
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.top || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, top: !selectedElement.style.fullCalendar?.grid?.borders?.top } }), <PanelTop className="w-4 h-4"/>, "Topo")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.headerSeparator || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, headerSeparator: !selectedElement.style.fullCalendar?.grid?.borders?.headerSeparator } }), <Minus className="w-4 h-4"/>, "Separador")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.bottom || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, bottom: !selectedElement.style.fullCalendar?.grid?.borders?.bottom } }), <PanelBottom className="w-4 h-4"/>, "Base")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.left || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, left: !selectedElement.style.fullCalendar?.grid?.borders?.left } }), <PanelLeft className="w-4 h-4"/>, "Esquerda")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.insideVertical || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, insideVertical: !selectedElement.style.fullCalendar?.grid?.borders?.insideVertical } }), <Columns className="w-4 h-4"/>, "Internas Vert.")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.right || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, right: !selectedElement.style.fullCalendar?.grid?.borders?.right } }), <PanelRight className="w-4 h-4"/>, "Direita")}
                                             {renderBorderToggle(selectedElement.style.fullCalendar.grid.borders?.insideHorizontal || false, () => updateFullCalendarGrid(selectedElement.id, { borders: { ...selectedElement.style.fullCalendar?.grid?.borders, insideHorizontal: !selectedElement.style.fullCalendar?.grid?.borders?.insideHorizontal } }), <Rows className="w-4 h-4"/>, "Internas Horiz.")}
                                         </div>
                                         <div className="space-y-2">
                                            <div className="flex gap-2 items-center">
                                                <div className="flex-1"><label className="block text-[9px] text-gray-400 mb-0.5">Cor</label><div className="flex h-5 border border-gray-200 rounded overflow-hidden"><input type="color" value={selectedElement.style.fullCalendar.grid.borderColor} onChange={(e) => updateFullCalendarGrid(selectedElement.id, { borderColor: e.target.value })} className="w-full h-full p-0 border-0 cursor-pointer" /></div></div>
                                                <div className="flex-1"><label className="block text-[9px] text-gray-400 mb-0.5">Espessura</label><input type="number" min="0.5" max="5" step="0.5" value={selectedElement.style.fullCalendar.grid.borderWidth} onChange={(e) => updateFullCalendarGrid(selectedElement.id, { borderWidth: parseFloat(e.target.value) })} className="w-full text-xs p-0.5 border rounded" /></div>
                                            </div>
                                         </div>
                                         <div className="grid grid-cols-2 gap-2 mt-2 pt-2 border-t border-gray-200">
                                             <div><label className="block text-[9px] text-gray-400 mb-0.5">Fundo Célula</label><div className="flex h-5 border border-gray-200 rounded overflow-hidden"><input type="color" value={selectedElement.style.fullCalendar.grid.cellBackgroundColor} onChange={(e) => updateFullCalendarGrid(selectedElement.id, { cellBackgroundColor: e.target.value })} className="w-5 h-full p-0 border-0 cursor-pointer" /><button onClick={() => updateFullCalendarGrid(selectedElement.id, { cellBackgroundColor: 'transparent' })} className="text-[8px] flex-1 bg-white hover:bg-gray-50 text-gray-500">Limpar</button></div></div>
                                             <div><label className="block text-[9px] text-gray-400 mb-0.5">Fundo Header</label><div className="flex h-5 border border-gray-200 rounded overflow-hidden"><input type="color" value={selectedElement.style.fullCalendar.grid.headerBackgroundColor} onChange={(e) => updateFullCalendarGrid(selectedElement.id, { headerBackgroundColor: e.target.value })} className="w-5 h-full p-0 border-0 cursor-pointer" /><button onClick={() => updateFullCalendarGrid(selectedElement.id, { headerBackgroundColor: 'transparent' })} className="text-[8px] flex-1 bg-white hover:bg-gray-50 text-gray-500">Limpar</button></div></div>
                                         </div>
                                     </div>
                                 )}

                                 <div className="h-px bg-gray-100 mb-3"></div>

                                 <div className="flex bg-gray-100 p-1 rounded mb-3 overflow-x-auto">
                                     <button onClick={() => setFontControlTab('title')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'title' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Título</button>
                                     <button onClick={() => setFontControlTab('weekDays')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'weekDays' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Semana</button>
                                     <button onClick={() => setFontControlTab('days')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'days' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Dias</button>
                                     <button onClick={() => setFontControlTab('highlight')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'highlight' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Destaques</button>
                                 </div>

                                 {fontControlTab === 'highlight' && (
                                     <div className="bg-white rounded border border-gray-100 p-2 shadow-sm mb-2">
                                         <div className="flex flex-col gap-2 mb-3">
                                             <label className="flex items-center text-xs text-gray-600 cursor-pointer"><input type="checkbox" checked={selectedElement.style.fullCalendar.specialDays?.highlightSundays || false} onChange={(e) => updateFullCalendarSpecialFlags(selectedElement.id, { highlightSundays: e.target.checked })} className="mr-2 rounded text-indigo-600 focus:ring-indigo-500" />Destacar Domingos</label>
                                             <label className="flex items-center text-xs text-gray-600 cursor-pointer"><input type="checkbox" checked={selectedElement.style.fullCalendar.specialDays?.highlightHolidays || false} onChange={(e) => updateFullCalendarSpecialFlags(selectedElement.id, { highlightHolidays: e.target.checked })} className="mr-2 rounded text-indigo-600 focus:ring-indigo-500" />Destacar Feriados</label>
                                         </div>
                                         <div className="h-px bg-gray-100 mb-2"></div>
                                         <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Estilo do Destaque</p>
                                     </div>
                                 )}

                                 <div className="bg-white rounded border border-gray-100 p-2 shadow-sm">
                                    {renderTypographyControls(
                                        fontControlTab === 'highlight' ? selectedElement.style.fullCalendar.specialDays?.style : selectedElement.style.fullCalendar[fontControlTab],
                                        (updates) => updateFullCalendarStyle(selectedElement.id, fontControlTab, updates)
                                    )}
                                 </div>
                             </div>
                         )}

                         {(selectedElement.type === 'text' || selectedElement.type === 'holiday_list') && (
                             <div className="pt-3 border-t border-gray-100">
                                 <label className="block text-[10px] font-bold text-gray-500 mb-2 uppercase">Conteúdo ({selectedElement.type === 'holiday_list' ? 'Editável' : 'Texto'})</label>
                                 <textarea className="w-full h-32 text-xs p-2 border border-gray-300 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 font-mono" value={selectedElement.content || ''} onChange={(e) => updateElementContent(selectedElement.id, e.target.value)} />
                                 {selectedElement.type === 'holiday_list' && <p className="text-[10px] text-gray-400 mt-1 italic">Edite a lista acima para personalizar os nomes ou datas.</p>}
                             </div>
                         )}

                         {['day_number', 'day_name', 'month_name', 'year', 'quote', 'text', 'holiday', 'moon', 'holiday_list'].includes(selectedElement.type) && !selectedElement.style.fullCalendar && (
                             <div className="space-y-3 pt-3 border-t border-gray-100">
                                 {renderTypographyControls({
                                     fontFamily: selectedElement.style.fontFamily || 'Inter',
                                     fontSize: selectedElement.style.fontSize || 12,
                                     fontWeight: selectedElement.style.fontWeight || 'normal',
                                     color: selectedElement.style.color || '#000000',
                                     textAlign: selectedElement.style.textAlign || 'left',
                                     textTransform: 'none', 
                                     letterSpacing: 0,
                                     backgroundColor: selectedElement.style.backgroundColor
                                 } as TextStyleConfig, (updates) => updateElementStyle(selectedElement.id, updates))}
                             </div>
                         )}

                         {['box', 'circle', 'vector_flower'].includes(selectedElement.type) && (
                             <div className="space-y-3 pt-3 border-t border-gray-100">
                                 <div>
                                     <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">{selectedElement.type === 'vector_flower' ? 'Cor do Contorno' : 'Cor Principal'}</label>
                                     <div className="flex space-x-2">
                                         <input type="color" value={selectedElement.style.color || '#000000'} onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })} className="h-8 w-8 rounded cursor-pointer p-0 border-0" />
                                         <input type="text" value={selectedElement.style.color} onChange={(e) => updateElementStyle(selectedElement.id, { color: e.target.value })} className="flex-1 border border-gray-200 rounded px-2 text-xs uppercase" />
                                     </div>
                                 </div>
                                <div>
                                    <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">{selectedElement.type === 'vector_flower' ? 'Cor do Preenchimento' : 'Cor de Fundo'}</label>
                                    <div className="flex space-x-2">
                                        <input type="color" value={selectedElement.style.backgroundColor || '#ffffff'} onChange={(e) => updateElementStyle(selectedElement.id, { backgroundColor: e.target.value })} className="h-8 w-8 rounded cursor-pointer p-0 border-0" />
                                        <button onClick={() => updateElementStyle(selectedElement.id, { backgroundColor: 'transparent' })} className="text-xs px-2 border border-gray-200 rounded hover:bg-gray-50">Transparente</button>
                                    </div>
                                </div>
                                <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Opacidade</label><input type="range" min="0" max="1" step="0.1" value={selectedElement.style.opacity ?? 1} onChange={(e) => updateElementStyle(selectedElement.id, { opacity: parseFloat(e.target.value) })} className="w-full" /></div>
                             </div>
                         )}

                         {!['full_calendar', 'mini_calendar'].includes(selectedElement.type) && (
                             <div className="pt-3 border-t border-gray-100">
                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Transformação</label>
                                <div className="mb-2"><span className="text-[10px] text-gray-400">Rotação</span><input type="range" min="0" max="360" value={selectedElement.style.rotation || 0} onChange={(e) => updateElementStyle(selectedElement.id, { rotation: parseInt(e.target.value) })} className="w-full" /></div>
                                <div className="flex gap-2">
                                    <button onClick={() => updateElementStyle(selectedElement.id, { flipX: !selectedElement.style.flipX })} className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipX ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`} title="Espelhar Horizontalmente"><FlipHorizontal className="w-4 h-4 mr-1" /> Horiz.</button>
                                    <button onClick={() => updateElementStyle(selectedElement.id, { flipY: !selectedElement.style.flipY })} className={`flex-1 py-1.5 px-2 border rounded flex items-center justify-center text-xs transition-colors ${selectedElement.style.flipY ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-gray-200 text-gray-600 hover:bg-gray-50'}`} title="Espelhar Verticalmente"><FlipVertical className="w-4 h-4 mr-1" /> Vert.</button>
                                </div>
                             </div>
                         )}

                         <div className="pt-6">
                            <button onClick={() => removeElement(selectedElement.id)} className="w-full py-2 px-4 bg-white border border-red-200 text-red-600 rounded hover:bg-red-50 flex items-center justify-center text-sm transition-colors"><Trash2 className="w-4 h-4 mr-2" /> Excluir Elemento</button>
                         </div>
                    </div>
                ) : <div className="p-8 text-center text-gray-400"><Move className="w-12 h-12 mb-4 opacity-20 mx-auto" /><p className="text-sm">Selecione um elemento</p></div>}
            </aside>
        )}
    </div>
  );
};

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados para a página
export type ElementType = 
  | 'text'
  | 'day_number' 
  | 'day_name' 
  | 'month_name' 
  | 'year' 
  | 'lines' 
  | 'box' 
  | 'circle' 
  | 'quote' 
  | 'moon' 
  | 'holiday' 
  | 'habit_tracker' 
  | 'vector_flower' 
  | 'note_grid'
  | 'mini_calendar'
  | 'full_calendar' // Calendário Anual
  | 'holiday_list' // Lista de Feriados Editável
  | 'table'; // Nova Tabela

export interface TextStyleConfig {
    fontFamily: string;
    fontSize: number;
    fontWeight: string;
    color: string;
    textAlign: 'left' | 'center' | 'right';
    textTransform: 'none' | 'uppercase' | 'lowercase' | 'capitalize';
    letterSpacing: number; // Tracking
    backgroundColor?: string; // Usado para destaques
}

export interface LayoutElement {
  id: string;
  name?: string; // Nome legível para a camada
  type: ElementType;
  content?: string; // Conteúdo de texto editável (para holiday_list e text)
  x: number; // Posição X em % (0-100) relativo à área útil da página
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  zIndex: number;
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string; // Cor do texto ou contorno (Stroke para vetores)
    backgroundColor?: string; // Preenchimento (Fill para vetores)
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    lineSpacing?: number; // Para pautas
    showTimes?: boolean; // Para pautas com horário
    startHour?: number; // Hora inicial para pautas
    rotation?: number; // Em graus
    flipX?: boolean; // Espelhar horizontalmente
    flipY?: boolean; // Espelhar verticalmente
    variant?: string;
    calendarOffset?: number; // -1 (mês anterior), 0 (atual), 1 (próximo)
    monthsPerRow?: number; // Para full_calendar: quantos meses por linha
    gap?: number; // Espaçamento entre meses

    // Configurações para Tabela
    table?: {
        rows: number;
        cols: number;
        borderColor: string;
        borderWidth: number;
        headerRow: boolean;
        rowHeight?: number; // Optional override
    };

    // Configurações granulares para o Calendário Completo
    fullCalendar?: {
        title: TextStyleConfig;
        weekDays: TextStyleConfig;
        days: TextStyleConfig;
        // Estilo de Tabela (Grid)
        grid?: {
            borderColor: string;
            borderWidth: number;
            cellBackgroundColor: string; // Fundo do dia
            headerBackgroundColor: string; // Fundo da barra de dias da semana
            borders: {
                top: boolean;
                bottom: boolean;
                left: boolean;
                right: boolean;
                insideHorizontal: boolean;
                insideVertical: boolean;
                headerSeparator: boolean; // Nova propriedade
            }
        };
        specialDays?: {
            highlightSundays: boolean;
            highlightHolidays: boolean;
            style: TextStyleConfig; // Estilo para dias destacados
        }
    }
  };
}

export interface IntroPage {
    id: string;
    name: string;
    elements: LayoutElement[];
}

export interface PageMargins {
  top: number;    // mm
  bottom: number; // mm
  inside: number; // mm (Encadernação/Espinha) - Substitui Left em páginas ímpares
  outside: number;// mm (Corte) - Substitui Right em páginas ímpares
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_weekend_shared';
export type PageSize = 'A4' | 'A5' | 'Letter';
export type PageOrientation = 'portrait' | 'landscape';

export interface AgendaConfig {
  year: number;
  layoutType: PageLayoutType;
  pageSize: PageSize;
  orientation: PageOrientation;
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  mirrorEvenPages: boolean; // Nova flag para ativar espelhamento automático
  margins: PageMargins;
  elements: LayoutElement[]; // Lista de elementos que compõem o template do dia (MIOLO)
  introPages: IntroPage[]; // Lista de páginas iniciais (DADOS, CALENDARIOS, ETC)
}

export enum AppState {
  LOGIN,
  DASHBOARD,
  PREVIEW
}

import React, { useState, useEffect, useRef } from 'react';
import { AgendaConfig, User, DayData, LayoutElement, ElementType, PageLayoutType, IntroPage, TextStyleConfig, PageSize, PageOrientation } from '../../types';
import { generateCalendarYear } from '../../core/backend/calendar';
import { generateMonthlyQuotes } from '../../core/backend/ai';
import { calculateDragPosition, calculateResize } from '../../core/logic/interaction';
import { ELEMENT_VARIANTS, AVAILABLE_FONTS } from '../../core/constants/elements';
import { ElementRenderer } from './components/ElementRenderer';

import { 
  Calendar, Printer, LogOut, Moon, Type, 
  Trash2, Move, AlignLeft, AlignCenter, AlignRight, Layout,
  Square, Circle, Flower, ListTodo, Grid3X3, ArrowDownAZ,
  Settings2, ScanLine, FlipHorizontal, FlipVertical,
  Layers, Upload, ChevronDown, Clock,
  CalendarDays, Palmtree, X, Star, Heart, Leaf,
  ChevronUp, Book, Plus, FileText, Grid, List,
  Type as TypeIcon, Bold, Italic, CaseUpper, CaseLower,
  PanelTop, PanelBottom, PanelLeft, PanelRight, Columns, Rows, Minus,
  Smartphone, Monitor, File, BookOpen, Table as TableIcon
} from 'lucide-react';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const PAGE_SIZES_MM: Record<PageSize, { width: number; height: number }> = {
    'A4': { width: 210, height: 297 },
    'A5': { width: 148, height: 210 },
    'Letter': { width: 215.9, height: 279.4 }
};

export const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const getDefaultElements = (): LayoutElement[] => [
      { id: '1', name: 'Número do Dia', type: 'day_number', x: 5, y: 3, w: 15, h: 8, zIndex: 10, style: { fontSize: 42, fontWeight: 'bold', color: '#1f2937', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '2', name: 'Dia da Semana', type: 'day_name', x: 22, y: 5, w: 40, h: 5, zIndex: 10, style: { fontSize: 14, fontWeight: '600', color: '#4b5563', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '3', name: 'Mês', type: 'month_name', x: 22, y: 8, w: 30, h: 4, zIndex: 10, style: { fontSize: 12, fontWeight: 'normal', color: '#9ca3af', textAlign: 'left', fontFamily: 'Inter' } },
      { id: '4', name: 'Pautas', type: 'lines', x: 5, y: 18, w: 90, h: 75, zIndex: 5, style: { color: '#e5e7eb', lineSpacing: 24, showTimes: false, startHour: 7 } }
  ];

  const [config, setConfig] = useState<AgendaConfig>({
    year: new Date().getFullYear() + 1,
    layoutType: '1_per_page',
    pageSize: 'A5',
    orientation: 'portrait',
    includeHolidays: true,
    includeMoonPhases: false,
    includeQuotes: false,
    mirrorEvenPages: true,
    margins: { top: 15, bottom: 15, inside: 20, outside: 10 },
    elements: getDefaultElements(),
    introPages: [
        { id: 'intro-1', name: 'Dados Pessoais', elements: [{ id: 'ip1', type: 'text', content: 'DADOS PESSOAIS', name: 'Título', x: 10, y: 10, w: 80, h: 10, zIndex: 1, style: { fontSize: 24, fontWeight: 'bold', textAlign: 'center', color: '#333' } }] }
    ]
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showMargins, setShowMargins] = useState(true);
  const [customFonts, setCustomFonts] = useState<string[]>([]);
  const [variantModal, setVariantModal] = useState<{type: ElementType, label: string} | null>(null);
  const [editorViewMode, setEditorViewMode] = useState<'standard' | 'weekend'>('standard');
  const [isDragging, setIsDragging] = useState(false);
  const [resizeDir, setResizeDir] = useState<string | null>(null);

  // State for Advanced Font Control Tabs (Full & Mini Calendar)
  const [fontControlTab, setFontControlTab] = useState<'title' | 'weekDays' | 'days' | 'highlight'>('title');

  const [editMode, setEditMode] = useState<'daily' | 'intro'>('daily');
  const [currentIntroPageId, setCurrentIntroPageId] = useState<string | null>(config.introPages[0]?.id || null);

  const dragRef = useRef<any>(null);
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Derived Page Dimensions
  const getPageDimensions = () => {
      const base = PAGE_SIZES_MM[config.pageSize];
      if (config.orientation === 'portrait') return base;
      return { width: base.height, height: base.width };
  };

  const { width: PAGE_WIDTH_MM, height: PAGE_HEIGHT_MM } = getPageDimensions();

  const EDITOR_WIDTH_PX = 400; 
  const EDITOR_SCALE = EDITOR_WIDTH_PX / PAGE_WIDTH_MM;
  const EDITOR_HEIGHT_PX = PAGE_HEIGHT_MM * EDITOR_SCALE;

  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  useEffect(() => {
    if (config.includeQuotes && quotes.length === 0) {
       generateMonthlyQuotes(config.year).then(setQuotes);
    }
  }, [config.includeQuotes, config.year]);

  const getActiveElements = () => {
      if (editMode === 'daily') return config.elements;
      if (editMode === 'intro' && currentIntroPageId) {
          return config.introPages.find(p => p.id === currentIntroPageId)?.elements || [];
      }
      return [];
  };

  const updateActiveElements = (newElements: LayoutElement[]) => {
      if (editMode === 'daily') {
          setConfig(prev => ({ ...prev, elements: newElements }));
      } else if (editMode === 'intro' && currentIntroPageId) {
          setConfig(prev => ({
              ...prev,
              introPages: prev.introPages.map(p => p.id === currentIntroPageId ? { ...p, elements: newElements } : p)
          }));
      }
  };

  const addIntroPage = () => {
      const newPage: IntroPage = {
          id: Math.random().toString(36).substr(2, 9),
          name: `Página ${config.introPages.length + 1}`,
          elements: []
      };
      setConfig(prev => ({ ...prev, introPages: [...prev.introPages, newPage] }));
      setCurrentIntroPageId(newPage.id);
  };

  const renameIntroPage = (id: string, name: string) => {
      setConfig(prev => ({
          ...prev,
          introPages: prev.introPages.map(p => p.id === id ? { ...p, name } : p)
      }));
  };

  const deleteIntroPage = (id: string) => {
      setConfig(prev => {
          const newPages = prev.introPages.filter(p => p.id !== id);
          if (currentIntroPageId === id) {
              setCurrentIntroPageId(newPages[0]?.id || null);
          }
          return { ...prev, introPages: newPages };
      });
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          const fontData = event.target?.result as string;
          const fontName = file.name.split('.')[0].replace(/[^a-zA-Z0-9]/g, '');
          const newFont = new FontFace(fontName, `url(${fontData})`);
          newFont.load().then((loadedFont) => {
              (document.fonts as any).add(loadedFont);
              setCustomFonts(prev => [...prev, fontName]);
              if (selectedId) updateElementStyle(selectedId, { fontFamily: fontName });
          }).catch(err => alert("Erro ao carregar a fonte."));
      };
      reader.readAsDataURL(file);
  };

  const generateHolidayListText = () => {
      const holidays = generatedData.filter(d => d.holiday).sort((a,b) => a.date.getTime() - b.date.getTime());
      return holidays.map(h => {
          const day = String(h.dayOfMonth).padStart(2, '0');
          const month = String(h.month + 1).padStart(2, '0');
          return `${day}/${month} - ${h.holiday}`;
      }).join('\n');
  };

  const addElement = (type: ElementType, label: string, styleOverride: any = {}, sizeOverride: any = {}) => {
    const activeList = getActiveElements();
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      name: `${label} ${activeList.length + 1}`,
      x: 35, y: 40, w: sizeOverride.w || 20, h: sizeOverride.h || 10, zIndex: activeList.length + 1,
      style: { fontSize: 14, color: '#000000', textAlign: 'left', lineSpacing: 24, borderColor: '#000000', borderWidth: 1, backgroundColor: 'transparent', rotation: 0, opacity: 1, flipX: false, flipY: false, fontFamily: 'Inter', showTimes: false, startHour: 7, ...styleOverride }
    };

    if (type === 'text') { newElement.content = "Novo Texto"; }

    // Defaults for complex elements
    const defaultCalendarStyle = {
        title: { fontSize: 10, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 1 },
        weekDays: { fontSize: 7, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 0 },
        days: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0 },
        grid: { 
            borderColor: '#dddddd', borderWidth: 0.5, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent',
            borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: true }
        },
        specialDays: {
            highlightSundays: true,
            highlightHolidays: false,
            style: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#dc2626', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0, backgroundColor: 'transparent' }
        }
    };

    if (!sizeOverride.w) {
        if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
        if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
        if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
        if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
        if (type === 'text') { newElement.w = 30; newElement.h = 8; newElement.style.fontSize = 16; newElement.style.borderWidth = 0; }
        if (type === 'holiday') { newElement.w = 40; newElement.h = 5; newElement.style.fontSize = 10; newElement.style.color = '#ef4444'; newElement.style.borderWidth = 0; newElement.style.fontWeight = '500'; }
        if (type === 'moon') { newElement.w = 20; newElement.h = 5; newElement.style.fontSize = 12; newElement.style.color = '#6b7280'; newElement.style.borderWidth = 0; }
        if (type === 'vector_flower') { newElement.w = 20; newElement.h = 20; newElement.style.color = '#1f2937'; newElement.style.backgroundColor = '#e5e7eb'; newElement.style.borderWidth = 0; }
        if (type === 'habit_tracker') { newElement.w = 40; newElement.h = 15; newElement.style.borderWidth = 1; newElement.style.borderColor = '#d1d5db'; }
        if (type === 'note_grid') { newElement.w = 40; newElement.h = 20; newElement.style.opacity = 0.5; newElement.style.borderWidth = 0; }

        if (type === 'mini_calendar') { 
            newElement.w = 25; newElement.h = 18; 
            newElement.style.calendarOffset = 0;
            newElement.style.borderWidth = 0;
            newElement.style.fullCalendar = defaultCalendarStyle;
        }

        if (type === 'full_calendar') { 
            newElement.w = 90; newElement.h = 80; newElement.x = 5; newElement.y = 10; 
            newElement.style.borderWidth = 0; newElement.style.monthsPerRow = 3; newElement.style.gap = 15; 
            newElement.style.fullCalendar = {
                ...defaultCalendarStyle,
                title: { ...defaultCalendarStyle.title, fontSize: 14 },
                weekDays: { ...defaultCalendarStyle.weekDays, fontSize: 9 },
                days: { ...defaultCalendarStyle.days, fontSize: 10 },
                specialDays: { ...defaultCalendarStyle.specialDays, style: { ...defaultCalendarStyle.specialDays.style, fontSize: 10, backgroundColor: '#fee2e2' } }
            };
        }

        if (type === 'holiday_list') {
            newElement.w = 40; newElement.h = 60; newElement.x = 10; newElement.y = 10;
            newElement.style.fontSize = 10; newElement.style.color = '#333';
            newElement.content = generateHolidayListText();
        }

        if (type === 'table') {
            newElement.w = 80; newElement.h = 40; newElement.x = 10;
            newElement.style.borderWidth = 1;
            newElement.style.borderColor = '#d1d5db';
            newElement.style.table = {
                rows: 10,
                cols: 2,
                borderColor: '#d1d5db',
                borderWidth: 1,
                headerRow: true
            };
        }
    }

    if (type === 'holiday') setConfig(prev => ({ ...prev, includeHolidays: true }));
    if (type === 'moon') setConfig(prev => ({ ...prev, includeMoonPhases: true }));
    if (type === 'quote') setConfig(prev => ({ ...prev, includeQuotes: true }));

    updateActiveElements([...activeList, newElement]);
    setSelectedId(newElement.id);
    setVariantModal(null);
  };

  const removeElement = (id: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.filter(e => e.id !== id));
    setSelectedId(null);
  };

  const moveLayer = (id: string, direction: 'up' | 'down') => {
      const activeList = getActiveElements();
      const index = activeList.findIndex(e => e.id === id);
      if (index === -1) return;
      if (direction === 'up' && index === activeList.length - 1) return;
      if (direction === 'down' && index === 0) return;
      const newElements = [...activeList];
      const swapIndex = direction === 'up' ? index + 1 : index - 1;
      [newElements[index], newElements[swapIndex]] = [newElements[swapIndex], newElements[index]];
      const updatedElements = newElements.map((el, i) => ({ ...el, zIndex: i + 1 }));
      updateActiveElements(updatedElements);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e));
  };

  const updateElementContent = (id: string, content: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, content } : e));
  };

  const updateTableConfig = (id: string, tableUpdate: any) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;
      const newTableStyle = { ...element.style.table, ...tableUpdate };
      updateElementStyle(id, { table: newTableStyle });
  }

  const updateFullCalendarStyle = (id: string, section: 'title' | 'weekDays' | 'days' | 'highlight', styleUpdate: Partial<TextStyleConfig>) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;

      if (section === 'highlight') {
          const newSpecialDays = {
              ...element.style.fullCalendar.specialDays,
              style: { ...element.style.fullCalendar.specialDays?.style, ...styleUpdate }
          };
          updateElementStyle(id, { fullCalendar: { ...element.style.fullCalendar, specialDays: newSpecialDays } });
          return;
      }

      const newFullCalendar = {
          ...element.style.fullCalendar,
          [section]: { ...element.style.fullCalendar[section], ...styleUpdate }
      };
      updateElementStyle(id, { fullCalendar: newFullCalendar });
  };

  const updateFullCalendarGrid = (id: string, gridUpdate: any) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;
      const newFullCalendar = {
          ...element.style.fullCalendar,
          grid: { ...element.style.fullCalendar.grid, ...gridUpdate }
      };
      updateElementStyle(id, { fullCalendar: newFullCalendar });
  }

  const updateFullCalendarSpecialFlags = (id: string, flags: { highlightSundays?: boolean, highlightHolidays?: boolean }) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;
      const newSpecialDays = { ...element.style.fullCalendar.specialDays, ...flags };
      updateElementStyle(id, { fullCalendar: { ...element.style.fullCalendar, specialDays: newSpecialDays } });
  }

  const updateElementName = (id: string, name: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, name } : e));
  };

  // Interaction handlers
  const handleInteractionStart = (e: React.MouseEvent, id: string, dir: string | null = null) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const activeList = getActiveElements();
    const element = activeList.find(el => el.id === id);
    if (!element) return;
    setSelectedId(id);
    dragRef.current = { startX: e.clientX, startY: e.clientY, initialX: element.x, initialY: element.y, initialW: element.w, initialH: element.h };
    if (dir) setResizeDir(dir); else setIsDragging(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if ((!isDragging && !resizeDir) || !dragRef.current || !selectedId || !editorRef.current) return;
    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaX = e.clientX - dragRef.current.startX;
    const deltaY = e.clientY - dragRef.current.startY;

    const activeList = getActiveElements();
    let newElementConfig = { ...activeList.find(el => el.id === selectedId)! };

    if (isDragging) {
        const { x, y } = calculateDragPosition(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, editorRect.width, editorRect.height);
        newElementConfig.x = x; newElementConfig.y = y;
    } else if (resizeDir) {
        const { x, y, w, h } = calculateResize(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, dragRef.current.initialW, dragRef.current.initialH, editorRect.width, editorRect.height, resizeDir);
        newElementConfig.x = x; newElementConfig.y = y; newElementConfig.w = w; newElementConfig.h = h;
    }

    updateActiveElements(activeList.map(el => el.id === selectedId ? newElementConfig : el));
  };

  const handleMouseUp = () => { setIsDragging(false); setResizeDir(null); dragRef.current = null; };

  const renderResizeHandle = (cursor: string, dir: string) => {
      const pos: React.CSSProperties = { position: 'absolute', width: '8px', height: '8px', backgroundColor: 'white', border: '1px solid #4f46e5', borderRadius: '50%', zIndex: 50 };
      switch(dir) {
          case 'nw': pos.top = '-4px'; pos.left = '-4px'; break;
          case 'n':  pos.top = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'ne': pos.top = '-4px'; pos.right = '-4px'; break;
          case 'e':  pos.top = '50%'; pos.right = '-4px'; pos.transform = 'translateY(-50%)'; break;
          case 'se': pos.bottom = '-4px'; pos.right = '-4px'; break;
          case 's':  pos.bottom = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'sw': pos.bottom = '-4px'; pos.left = '-4px'; break;
          case 'w':  pos.top = '50%'; pos.left = '-4px'; pos.transform = 'translateY(-50%)'; break;
      }
      return <div className="no-print" style={{ ...pos, cursor }} onMouseDown={(e) => handleInteractionStart(e, selectedId!, dir)} />;
  }

  const renderTemplate = (elements: LayoutElement[], day: DayData | null, isEditor: boolean = false, attachRef: boolean = false) => {
    const d = day || { dayOfMonth: 24, month: 7, year: config.year, dayOfWeek: 3, holiday: 'Feriado', moonPhase: 'Lua cheia', date: new Date() } as DayData;
    return (
      <div ref={attachRef ? editorRef : null} className={`relative overflow-hidden ${isEditor ? 'w-full h-full' : 'w-full h-full'}`} onMouseMove={isEditor ? handleMouseMove : undefined} onMouseUp={isEditor ? handleMouseUp : undefined} onMouseLeave={isEditor ? handleMouseUp : undefined}>
        {elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;
          const wrapperStyle: React.CSSProperties = { left: `${el.x}%`, top: `${el.y}%`, width: `${el.w}%`, height: `${el.h}%`, zIndex: el.zIndex, transform: `rotate(${el.style.rotation || 0}deg) scaleX(${el.style.flipX ? -1 : 1}) scaleY(${el.style.flipY ? -1 : 1})` };
          const containerClass = `absolute group ${isSelected ? 'ring-2 ring-indigo-500 z-50' : 'hover:ring-1 hover:ring-indigo-300'}`;
          const isWrapperType = ['lines','box','circle','vector_flower','note_grid','habit_tracker','mini_calendar','full_calendar','table'].includes(el.type);

          return (
            <div key={el.id} onMouseDown={(e) => handleInteractionStart(e, el.id)} className={containerClass} style={wrapperStyle} title={el.name}>
                {isSelected && <>{['nw','n','ne','e','se','s','sw','w'].map(d => renderResizeHandle(d+'-resize', d))}</>}
                <div className={`w-full h-full relative ${isWrapperType ? 'overflow-hidden flex flex-col' : 'flex items-center'}`} style={{ justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start'), ...(!isWrapperType ? el.style : {}) }}>
                    {isWrapperType ? <ElementRenderer element={el} dayData={d} quote={quotes[d.month]} isEditor={isEditor} /> : <span style={{ pointerEvents: 'none' }}><ElementRenderer element={el} dayData={d} quote={quotes[d.month]} isEditor={isEditor} /></span>}
                </div>
            </div>
          );
        })}
      </div>
    );
  };

  const getMirroredElements = (elements: LayoutElement[]): LayoutElement[] => {
      if (!config.mirrorEvenPages) return elements;
      return elements.map(el => {
          const newX = 100 - el.x - el.w;
          let newTextAlign = el.style.textAlign;
          if (newTextAlign === 'left') newTextAlign = 'right';
          else if (newTextAlign === 'right') newTextAlign = 'left';
          return { ...el, x: newX, style: { ...el.style, textAlign: newTextAlign } };
      });
  };

  const renderEditorPage = () => {
    const paddingStyle = { 
        paddingTop: `${config.margins.top * EDITOR_SCALE}px`, 
        paddingBottom: `${config.margins.bottom * EDITOR_SCALE}px`, 
        paddingLeft: `${config.margins.inside * EDITOR_SCALE}px`, 
        paddingRight: `${config.margins.outside * EDITOR_SCALE}px` 
    };
    const containerClass = `bg-white shadow-2xl relative transition-all duration-300 ease-in-out flex flex-col`;
    const containerStyle = { width: `${EDITOR_WIDTH_PX}px`, height: `${EDITOR_HEIGHT_PX}px`, ...paddingStyle };
    const usefulAreaClass = `w-full h-full relative ${showMargins ? 'outline outline-1 outline-dashed outline-indigo-300' : ''}`;

    if (editMode === 'intro') {
        return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(getActiveElements(), null, true, true)}</div></div>;
    }

    const activeElements = config.elements;
    if (config.layoutType === '1_per_page') return <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div>;
    if (config.layoutType === '2_per_page') return <div className={containerClass} style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    if (config.layoutType === '1_per_page_weekend_shared') return editorViewMode === 'standard' ? <div className={containerClass} style={containerStyle}><div className={usefulAreaClass}>{renderTemplate(activeElements, null, true, true)}</div></div> : <div className={containerClass} style={containerStyle}><div className={`${usefulAreaClass} flex flex-col`}><div className="flex-1 border-b border-dashed border-indigo-200 relative overflow-hidden">{renderTemplate(activeElements, null, true, true)}</div><div className="flex-1 relative overflow-hidden">{renderTemplate(activeElements, null, true, false)}</div></div></div>;
    return null;
  };

  const renderPrintLayout = () => {
    // ... (unchanged logic for print layout)
    const pages: React.ReactNode[] = [];
    const pageStyle = { width: `${PAGE_WIDTH_MM}mm`, height: `${PAGE_HEIGHT_MM}mm` };
    const borderStyle = showMargins ? 'border border-indigo-200 border-dashed' : '';
    let pageCount = 0;

    const renderPageContainer = (children: React.ReactNode, key: string | number) => {
        pageCount++;
        const isEven = pageCount % 2 === 0;
        const marginLeft = isEven ? config.margins.outside : config.margins.inside;
        const marginRight = isEven ? config.margins.inside : config.margins.outside;
        const pagePadding = `${config.margins.top}mm ${marginRight}mm ${config.margins.bottom}mm ${marginLeft}mm`;

        return (
            <div key={key} className="bg-white shadow print:shadow-none print:break-after-page relative box-border overflow-hidden mx-auto mb-8 print:mb-0" style={{ ...pageStyle, padding: pagePadding }}>
                <div className={`w-full h-full relative ${borderStyle} print:border-none`}>
                    {children}
                </div>
                <div className={`absolute bottom-1 text-[8px] text-gray-300 no-print ${isEven ? 'left-2' : 'right-2'}`}>Pág {pageCount} ({isEven ? 'Par/Verso' : 'Ímpar/Frente'})</div>
            </div>
        );
    };

    config.introPages.forEach(page => {
        const isEven = (pageCount + 1) % 2 === 0;
        const elementsToRender = isEven ? getMirroredElements(page.elements) : page.elements;
        pages.push(renderPageContainer(renderTemplate(elementsToRender, null, false), page.id));
    });

    const days = generatedData;
    const { layoutType } = config;

    if (layoutType === '1_per_page') {
        days.forEach(day => { 
            const isEven = (pageCount + 1) % 2 === 0;
            const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements;
            pages.push(renderPageContainer(renderTemplate(elementsToRender, day, false), day.date.toISOString())); 
        });
    } else if (layoutType === '2_per_page') {
        for (let i = 0; i < days.length; i += 2) {
            const isEven = (pageCount + 1) % 2 === 0;
            const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements;
            pages.push(renderPageContainer(
                <div className="flex flex-col h-full">
                    <div className={`flex-1 relative border-b border-dashed border-gray-200 pb-2 mb-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>
                        <div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, days[i], false)}</div>
                    </div>
                    <div className={`flex-1 relative pt-2 overflow-hidden ${showMargins ? 'px-2' : ''}`}>
                        {days[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, days[i+1], false)}</div>) : null}
                    </div>
                </div>
            , i));
        }
    } else if (layoutType === '1_per_page_weekend_shared') {
        let i = 0;
        while (i < days.length) {
            const day = days[i];
            const isWeekend = day.dayOfWeek === 6;
            const isEven = (pageCount + 1) % 2 === 0;
            const elementsToRender = isEven ? getMirroredElements(config.elements) : config.elements;
            if (isWeekend) {
                pages.push(renderPageContainer(
                    <div className="flex flex-col h-full">
                        <div className="flex-1 relative border-b border-dashed border-gray-300 pb-2 mb-2 overflow-hidden">
                            <div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, day, false)}</div>
                        </div>
                        <div className="flex-1 relative pt-2 overflow-hidden">
                            {days[i+1] ? (<div className={`w-full h-full ${borderStyle} print:border-none`}>{renderTemplate(elementsToRender, days[i+1], false)}</div>) : null}
                        </div>
                    </div>
                , `we-${i}`));
                i += 2;
            } else {
                pages.push(renderPageContainer(renderTemplate(elementsToRender, day, false), day.date.toISOString()));
                i += 1;
            }
        }
    }
    return pages;
  };

  const renderTypographyControls = (values: TextStyleConfig, onChange: (update: Partial<TextStyleConfig>) => void) => (
