                            <label className="flex items-center space-x-2 cursor-pointer"><input type="checkbox" checked={config.includeQuotes} onChange={(e) => setConfig(prev => ({...prev, includeQuotes: e.target.checked}))} className="text-indigo-600 rounded focus:ring-indigo-500 border-gray-300" /><span className="text-[10px] text-gray-600 uppercase font-bold">Incluir Frases (IA)</span></label>
                        </div>
                    </div>
                    <div className="bg-white p-3 rounded border border-gray-200 mt-4">
