                         <div className="grid grid-cols-2 gap-2 mb-3">
                            <div><label className="text-[10px] text-gray-400">Topo</label><input type="number" value={config.margins.top} onChange={(e) => setConfig(prev => ({...prev, margins: {...prev.margins, top: parseInt(e.target.value)}}))} className="w-full text-xs p-1 border rounded" /></div>
