                            <div><label className="text-[10px] text-gray-800 font-semibold flex items-center gap-1"><BookOpen className="w-3 h-3"/> Interna</label><input type="number" value={config.margins.inside} onChange={(e) => setConfig(prev => ({...prev, margins: {...prev.margins, inside: parseInt(e.target.value)}}))} className="w-full text-xs p-1 border border-indigo-200 rounded bg-indigo-50" title="Margem da encadernação/espinha" /></div>
                            <div><label className="text-[10px] text-gray-400">Externa</label><input type="number" value={config.margins.outside} onChange={(e) => setConfig(prev => ({...prev, margins: {...prev.margins, outside: parseInt(e.target.value)}}))} className="w-full text-xs p-1 border rounded" title="Margem de corte/borda" /></div>
                         </div>
                         <label className="flex items-center gap-2 cursor-pointer border-t pt-2 border-gray-100"><input type="checkbox" checked={config.mirrorEvenPages} onChange={(e) => setConfig(c => ({...c, mirrorEvenPages: e.target.checked}))} className="rounded text-indigo-600 focus:ring-indigo-500" /><span className="text-[10px] font-medium text-gray-700">Espelhar Elementos nas Páginas Pares</span></label>
                    </div>
                </div>
