import React from 'react';
import { LayoutElement, DayData, TextStyleConfig } from '../../../types';
import { getMonthName, getDayName, generateMonthGrid, checkIsHoliday } from '../../../core/backend/calendar';
import { 
  Moon, Square, Circle, Flower, Star, Heart, Leaf
} from 'lucide-react';

interface ElementRendererProps {
  element: LayoutElement;
  dayData: DayData;
  quote?: string;
  isEditor: boolean;
  onTableResizeStart?: (e: React.MouseEvent, elementId: string, colIndex: number) => void;
  onTableCellChange?: (elementId: string, row: number, col: number, text: string) => void;
}

export const ElementRenderer: React.FC<ElementRendererProps> = ({ 
    element, 
    dayData, 
    quote, 
    isEditor, 
    onTableResizeStart,
    onTableCellChange
}) => {
  const d = dayData;
  const style = element.style;

  const renderMoonIcon = (phase: string, color: string) => {
      const p = phase.toLowerCase();
      if (p.includes('nova')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
      if (p.includes('cheia')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><circle cx="12" cy="12" r="10"/></svg>;
      if (p.includes('crescente')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a9 9 0 1 0 0 18 7 7 0 0 1 0-14 7 7 0 0 1 0-4z" /></svg>;
      if (p.includes('minguante')) return <svg viewBox="0 0 24 24" className="w-full h-full" fill={color} stroke="none"><path d="M12 3a7 7 0 0 0 0 14 7 7 0 0 0 0 4 9 9 0 1 1 0-18z" /></svg>;
      return <svg viewBox="0 0 24 24" className="w-full h-full" fill="none" stroke={color} strokeWidth="2"><circle cx="12" cy="12" r="9"/></svg>;
  }

  const renderVector = () => {
      const variant = style.variant || 'flower_1';
      let path = "M12 2C9.5 2 8 4 8 6C8 4 6.5 2 4 2C1.5 2 0 4.5 0 7.5C0 10.5 3 14 12 22C21 14 24 10.5 24 7.5C24 4.5 22.5 2 20 2C17.5 2 16 4 16 6C16 4 14.5 2 12 2Z";
      if (variant === 'star') path = "M12 2L15.09 8.26L22 9.27L17 14.14L18.18 21.02L12 17.77L5.82 21.02L7 14.14L2 9.27L8.91 8.26L12 2Z";
      else if (variant === 'heart') path = "M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z";
      else if (variant === 'leaf') path = "M17 8C8 10 5.9 16.17 3.82 21.34 9.17 19.8 15 17 17 8zm-7.05 5.55A3.99 3.99 0 0 0 12 13a4 4 0 0 0 0 8C9.5 16.5 9.5 16 9.95 13.55zM12 2C9.5 2 8 4 8 6c0 4 6 7 4 7s4-3 4-7c0-2-1.5-4-4-4z";
      return (
          <svg viewBox="0 0 24 24" className="w-full h-full" style={{ overflow: 'visible' }}>
              <path d={path} fill={style.backgroundColor || 'transparent'} stroke={style.color || 'none'} strokeWidth="1.5" strokeLinejoin="round"/>
          </svg>
      ); 
  }

  // --- Shared Grid Renderer ---
  const renderSingleMonth = (monthIndex: number, year: number) => {
      const grid = generateMonthGrid(year, monthIndex);

      const titleStyle = style.fullCalendar?.title || { 
          fontSize: 12, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center', textTransform: 'uppercase', letterSpacing: 0 
      } as TextStyleConfig;

      const weekStyle = style.fullCalendar?.weekDays || { 
          fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center', textTransform: 'none', letterSpacing: 0 
      } as TextStyleConfig;

      const dayStyle = style.fullCalendar?.days || { 
          fontSize: 10, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center', textTransform: 'none', letterSpacing: 0 
      } as TextStyleConfig;

      const gridConfig = style.fullCalendar?.grid || {
          borderColor: '#ddd', borderWidth: 1, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent',
          borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: false }
      };

      const specialDaysConfig = style.fullCalendar?.specialDays || {
          highlightSundays: false, highlightHolidays: false, style: { color: '#ff0000', fontWeight: 'bold', fontSize: 10, fontFamily: 'Inter', textAlign: 'center', textTransform: 'none', letterSpacing: 0 }
      };

      const baseBorderStyle = `${gridConfig.borderWidth}px solid ${gridConfig.borderColor}`;
      const noBorder = 'none';

      const flatGrid = grid.flat();
      const totalRows = grid.length + 1; // +1 for Header

      return (
          <div key={monthIndex} className="flex flex-col w-full h-full">
              {/* Título do Mês */}
              <div 
                className="mb-1 pb-0.5" 
                style={{ 
                    fontSize: titleStyle.fontSize,
                    fontFamily: titleStyle.fontFamily,
                    fontWeight: titleStyle.fontWeight,
                    color: titleStyle.color,
                    textAlign: titleStyle.textAlign,
                    textTransform: titleStyle.textTransform,
                    letterSpacing: `${titleStyle.letterSpacing}px`,
                }}
              >
                  {getMonthName(monthIndex)} {element.type === 'mini_calendar' ? year : ''}
              </div>

              {/* Grid Container */}
              <div className="grid grid-cols-7 gap-0 flex-1">
                  {/* Dias da Semana (Header - Row 0) */}
                  {['D','S','T','Q','Q','S','S'].map((wd, colIndex) => (
                      <div 
                        key={`h-${colIndex}`} 
                        className="flex items-center justify-center" 
                        style={{ 
                            fontSize: weekStyle.fontSize,
                            fontFamily: weekStyle.fontFamily,
                            fontWeight: weekStyle.fontWeight,
                            color: weekStyle.color,
                            textTransform: weekStyle.textTransform,
                            letterSpacing: `${weekStyle.letterSpacing}px`,
                            backgroundColor: gridConfig.headerBackgroundColor,

                            // Header Borders
                            borderTop: gridConfig.borders?.top ? baseBorderStyle : noBorder,
                            // Priority: Header Separator overrides Inside Horizontal
                            borderBottom: gridConfig.borders?.headerSeparator ? baseBorderStyle : (gridConfig.borders?.insideHorizontal ? baseBorderStyle : noBorder),
                            borderLeft: (colIndex === 0 && gridConfig.borders?.left) ? baseBorderStyle : (colIndex > 0 && gridConfig.borders?.insideVertical ? baseBorderStyle : noBorder),
                            borderRight: (colIndex === 6 && gridConfig.borders?.right) ? baseBorderStyle : noBorder
                        }}
                      >
                          {wd}
                      </div>
                  ))}

                  {/* Dias do Mês (Rows 1 to N) */}
                  {flatGrid.map((dayNum, i) => {
                      const colIndex = i % 7;
                      const rowIndex = Math.floor(i / 7) + 1; 
                      const isLastRow = rowIndex === totalRows - 1;

                      const isSunday = colIndex === 0;
                      const isHoliday = dayNum ? !!checkIsHoliday(year, monthIndex, dayNum) : false;
                      const isSpecial = (isSunday && specialDaysConfig.highlightSundays) || (isHoliday && specialDaysConfig.highlightHolidays);

                      // For mini calendar, also highlight the current page day if offset is 0
                      const isCurrentDayPage = element.type === 'mini_calendar' && style.calendarOffset === 0 && dayNum === d.dayOfMonth;

                      const activeStyle = isSpecial ? specialDaysConfig.style : dayStyle;

                      return (
                        <div 
                            key={`d-${i}`} 
                            className={`flex items-center justify-center ${isCurrentDayPage ? 'bg-indigo-600 text-white rounded-sm font-bold' : ''}`}
                            style={{ 
                                fontSize: activeStyle.fontSize,
                                fontFamily: activeStyle.fontFamily,
                                fontWeight: isCurrentDayPage ? 'bold' : activeStyle.fontWeight,
                                color: isCurrentDayPage ? '#ffffff' : activeStyle.color,
                                letterSpacing: `${activeStyle.letterSpacing}px`,
                                backgroundColor: isCurrentDayPage ? undefined : (isSpecial && activeStyle.backgroundColor ? activeStyle.backgroundColor : (dayNum ? gridConfig.cellBackgroundColor : 'transparent')),

                                // Cell Borders
                                borderBottom: isLastRow ? (gridConfig.borders?.bottom ? baseBorderStyle : noBorder) : (gridConfig.borders?.insideHorizontal ? baseBorderStyle : noBorder),
                                borderLeft: (colIndex === 0 && gridConfig.borders?.left) ? baseBorderStyle : (colIndex > 0 && gridConfig.borders?.insideVertical ? baseBorderStyle : noBorder),
                                borderRight: (colIndex === 6 && gridConfig.borders?.right) ? baseBorderStyle : noBorder
                            }}
                        >
                            {dayNum || ''}
                        </div>
                      );
                  })}
              </div>
          </div>
      );
  };

  switch (element.type) {
    case 'day_number': return <div style={{...style, display: 'block', width: '100%'}}>{d.dayOfMonth}</div>;
    case 'month_name': return <div style={{...style, display: 'block', width: '100%'}}>{getMonthName(d.month)}</div>;
    case 'day_name': return <div style={{...style, display: 'block', width: '100%'}}>{getDayName(d.dayOfWeek)}</div>;
    case 'year': return <div style={{...style, display: 'block', width: '100%'}}>{d.year}</div>;
    case 'holiday': return <div style={{...style, display: 'block', width: '100%'}}>{d.holiday || (isEditor ? 'Nome do Feriado' : '')}</div>;
    case 'text': return <div style={{...style, display: 'block', width: '100%', whiteSpace: 'pre-wrap'}}>{element.content || (isEditor ? 'Texto Livre' : '')}</div>;
    case 'quote': return <div style={{...style, display: 'block', width: '100%'}}>{quote || (isEditor ? '"Frase Inspiradora"' : '')}</div>;
    case 'vector_flower': return renderVector();
    case 'moon': 
        const phase = d.moonPhase || (isEditor ? 'Lua cheia' : '');
        if (phase) {
            const variant = style.variant || 'full_info';
            if (variant === 'icon_only') return <div className="w-full h-full flex items-center justify-center">{renderMoonIcon(phase, style.color || '#000')}</div>;
            return <div className="flex items-center gap-1.5 h-full"><div className="shrink-0" style={{ width: style.fontSize, height: style.fontSize }}>{renderMoonIcon(phase, style.color || '#000')}</div><span className="whitespace-nowrap" style={{ fontSize: style.fontSize, fontFamily: style.fontFamily, color: style.color }}>{phase}</span></div>;
        }
        return null;
    case 'lines': 
        const lineCount = Math.floor((element.h / 100 * (isEditor ? 600 : 800)) / (style.lineSpacing || 24)); 
        // Dotted check
        const isDotted = style.variant === 'dotted';
        const lineStyle: React.CSSProperties = {
            height: style.lineSpacing,
            borderColor: style.color,
            borderBottomStyle: isDotted ? 'dotted' : 'solid',
            borderBottomWidth: '1px'
        };

        return (
          <>
            {Array(Math.max(2, lineCount)).fill(0).map((_, i) => (
              <div key={i} className="w-full relative" style={lineStyle}>
                   {style.showTimes && <span className="absolute -top-2 left-0 text-[10px] font-mono text-gray-500 bg-white/50 pr-1" style={{ fontSize: (style.fontSize ? style.fontSize * 0.7 : 10) }}>{String((style.startHour || 7) + i).padStart(2, '0')}:00</span>}
              </div>
            ))}
          </>
        );
    case 'box': return <div className="w-full h-full" style={{ backgroundColor: style.backgroundColor, border: `${style.borderWidth}px solid ${style.borderColor}`, borderRadius: style.borderRadius }}></div>;
    case 'circle': return <div className="w-full h-full rounded-full" style={{ backgroundColor: style.backgroundColor, border: `${style.borderWidth}px solid ${style.borderColor}` }}></div>;
    case 'habit_tracker':
       const habitCount = Math.max(1, Math.floor((Math.max(0, (element.h / 100 * (isEditor ? 600 : 800)) - 20)) / 20));
       return <div className="w-full h-full flex flex-col" style={{ opacity: style.opacity }}><div className="text-[10px] text-gray-500 mb-1 font-bold tracking-wider uppercase">Hábitos</div><div className="flex-1 flex flex-col gap-1 overflow-hidden">{Array(habitCount).fill(0).map((_, i) => (<div key={i} className="flex items-center border-b border-gray-200 h-5 shrink-0"><div className="w-4 h-4 border border-gray-300 rounded mr-2"></div><div className="h-2 w-full bg-gray-100 rounded"></div></div>))}</div></div>;
    case 'note_grid':
        return <div className="w-full h-full" style={{ backgroundImage: `radial-gradient(${style.color || '#ccc'} 1px, transparent 1px)`, backgroundSize: '15px 15px', opacity: style.opacity }}></div>;

    // --- UPDATED MINI CALENDAR USING SHARED LOGIC ---
    case 'mini_calendar':
        let targetMonth = d.month + (style.calendarOffset || 0);
        let targetYear = d.year;
        // Handle Rollover
        if (targetMonth < 0) { targetMonth = 11; targetYear -= 1; }
        else if (targetMonth > 11) { targetMonth = 0; targetYear += 1; }

        return (
            <div className="w-full h-full flex flex-col" style={{ backgroundColor: style.backgroundColor || 'transparent' }}>
                 {renderSingleMonth(targetMonth, targetYear)}
            </div>
        );

    case 'full_calendar':
        // Renders all 12 months in a grid
        const months = Array.from({ length: 12 }, (_, i) => i);
        const cols = style.monthsPerRow || 3;
        const gap = style.gap !== undefined ? style.gap : 10;

        return (
            <div 
                className="w-full h-full" 
                style={{ 
                    display: 'grid', 
                    gridTemplateColumns: `repeat(${cols}, 1fr)`, 
                    gap: `${gap}px`,
                    backgroundColor: style.backgroundColor || 'transparent',
                    padding: '4px'
                }}
            >
                {months.map(m => (
                    <div key={m} className="overflow-hidden">
                        {renderSingleMonth(m, d.year)}
                    </div>
                ))}
            </div>
        );
    case 'holiday_list':
        return (
            <div className="w-full h-full whitespace-pre-wrap" style={{ 
                fontSize: style.fontSize, 
                fontFamily: style.fontFamily, 
                color: style.color, 
                textAlign: style.textAlign, 
                lineHeight: 1.5
            }}>
                {element.content || "Feriados Nacionais (Editável)"}
            </div>
        );
    case 'table':
        const rows = style.table?.rows || 10;
        const columns = style.table?.cols || 2;
        const hasHeader = style.table?.headerRow;

        // Default widths to equal distribution if undefined
        const columnWidths = style.table?.columnWidths || Array(columns).fill(100 / columns);

        // Destructure table text style
        const tStyle = style.table?.textStyle || {
            fontFamily: 'Inter',
            fontSize: 10,
            fontWeight: 'normal',
            color: '#666',
            textAlign: 'left',
            textTransform: 'none',
            letterSpacing: 0,
            backgroundColor: 'transparent'
        };

        return (
            <div 
                className="w-full h-full flex flex-col" 
                style={{ 
                    borderColor: style.table?.borderColor, 
                    borderWidth: `${style.table?.borderWidth}px`, 
                    borderStyle: 'solid',
                    overflow: 'hidden'
                }}
            >
                {Array(rows).fill(0).map((_, r) => (
                    <div key={r} className="flex w-full flex-1 relative" style={{ minHeight: style.table?.rowHeight || 'auto' }}>
                        {Array(columns).fill(0).map((_, c) => {
                            const isLastCol = c === columns - 1;
                            const cellKey = `${r}-${c}`;
                            const content = style.table?.cellContent?.[cellKey] || '';
                            const isHeaderCell = hasHeader && r === 0;

                            const cellStyle: React.CSSProperties = {
                                width: `${columnWidths[c]}%`,
                                borderColor: style.table?.borderColor, 
                                borderBottomWidth: (r === rows - 1) ? 0 : `${style.table?.borderWidth}px`,
                                borderBottomStyle: 'solid',
                                borderRightWidth: isLastCol ? 0 : `${style.table?.borderWidth}px`,
                                borderRightStyle: 'solid',
                                backgroundColor: isHeaderCell ? '#f3f4f6' : (tStyle.backgroundColor || 'transparent'),
                                display: 'flex',
                                alignItems: 'stretch',
                                // Apply typography settings
                                fontFamily: tStyle.fontFamily,
                                fontSize: tStyle.fontSize,
                                fontWeight: isHeaderCell ? 'bold' : tStyle.fontWeight,
                                color: tStyle.color,
                                textAlign: tStyle.textAlign as any,
                                textTransform: tStyle.textTransform as any,
                                letterSpacing: `${tStyle.letterSpacing}px`,
                            };

                            return (
                                <div key={c} className="relative flex-shrink-0" style={cellStyle}>
                                    {isEditor ? (
                                        <textarea 
                                            value={content}
                                            onChange={(e) => onTableCellChange && onTableCellChange(element.id, r, c, e.target.value)}
                                            className="w-full h-full bg-transparent border-none resize-none p-1 focus:ring-1 focus:ring-indigo-300 focus:bg-white/50 leading-tight"
                                            style={{
                                                // Inherit styles for the editor input to match look
                                                fontFamily: 'inherit',
                                                fontSize: 'inherit',
                                                fontWeight: 'inherit',
                                                color: 'inherit',
                                                textAlign: 'inherit',
                                                textTransform: 'inherit',
                                                letterSpacing: 'inherit',
                                            }}
                                            placeholder={isHeaderCell ? "Título" : ""}
                                            onMouseDown={(e) => e.stopPropagation()} 
                                        />
                                    ) : (
                                        <div className="w-full h-full p-1 whitespace-pre-wrap leading-tight">{content}</div>
                                    )}

                                    {/* Column Resizer Handle */}
                                    {isEditor && !isLastCol && (
                                        <div 
                                            className="absolute top-0 right-[-3px] h-full w-[6px] cursor-col-resize hover:bg-indigo-400 opacity-0 hover:opacity-50 z-20 transition-opacity"
                                            onMouseDown={(e) => onTableResizeStart && onTableResizeStart(e, element.id, c)}
                                        />
                                    )}
                                </div>
                            );
                        })}
                    </div>
                ))}
            </div>
        );
    default: return null;
  }
};

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados para a página
export type ElementType = 
  | 'text'
  | 'day_number' 
  | 'day_name' 
  | 'month_name' 
  | 'year' 
  | 'lines' 
  | 'box' 
  | 'circle' 
  | 'quote' 
  | 'moon' 
  | 'holiday' 
  | 'habit_tracker' 
  | 'vector_flower' 
  | 'note_grid'
  | 'mini_calendar'
  | 'full_calendar' // Calendário Anual
  | 'holiday_list' // Lista de Feriados Editável
  | 'table'; // Nova Tabela

export interface TextStyleConfig {
    fontFamily: string;
    fontSize: number;
    fontWeight: string;
    color: string;
    textAlign: 'left' | 'center' | 'right';
    verticalAlign?: 'top' | 'middle' | 'bottom'; // Novo alinhamento vertical
    textTransform: 'none' | 'uppercase' | 'lowercase' | 'capitalize';
    letterSpacing: number; // Tracking
    backgroundColor?: string; // Usado para destaques
}

export interface LayoutElement {
  id: string;
  name?: string; // Nome legível para a camada
  type: ElementType;
  content?: string; // Conteúdo de texto editável (para holiday_list e text)
  x: number; // Posição X em % (0-100) relativo à área útil da página
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  zIndex: number;
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string; // Cor do texto ou contorno (Stroke para vetores)
    backgroundColor?: string; // Preenchimento (Fill para vetores)
    borderColor?: string;
    borderWidth?: number;
    borderRadius?: number;
    textAlign?: 'left' | 'center' | 'right';
    opacity?: number;
    lineSpacing?: number; // Para pautas
    showTimes?: boolean; // Para pautas com horário
    startHour?: number; // Hora inicial para pautas
    rotation?: number; // Em graus
    flipX?: boolean; // Espelhar horizontalmente
    flipY?: boolean; // Espelhar verticalmente
    variant?: string;
    calendarOffset?: number; // -1 (mês anterior), 0 (atual), 1 (próximo)
    monthsPerRow?: number; // Para full_calendar: quantos meses por linha
    gap?: number; // Espaçamento entre meses

    // Configurações para Tabela
    table?: {
        rows: number;
        cols: number;
        borderColor: string;
        borderWidth: number;
        headerRow: boolean;
        rowHeight?: number; // Optional override
        columnWidths?: number[]; // Array de porcentagens para largura das colunas
        cellContent?: Record<string, string>; // Mapa "row-col" -> "texto"
        textStyle?: TextStyleConfig; // Estilo de texto global da tabela
        rowStyles?: Record<number, TextStyleConfig>; // Estilos específicos por índice de linha
        colStyles?: Record<number, TextStyleConfig>; // Estilos específicos por índice de coluna
    };

    // Configurações granulares para o Calendário Completo
    fullCalendar?: {
        title: TextStyleConfig;
        weekDays: TextStyleConfig;
        days: TextStyleConfig;
        // Estilo de Tabela (Grid)
        grid?: {
            borderColor: string;
            borderWidth: number;
            cellBackgroundColor: string; // Fundo do dia
            headerBackgroundColor: string; // Fundo da barra de dias da semana
            borders: {
                top: boolean;
                bottom: boolean;
                left: boolean;
                right: boolean;
                insideHorizontal: boolean;
                insideVertical: boolean;
                headerSeparator: boolean; // Nova propriedade
            }
        };
        specialDays?: {
            highlightSundays: boolean;
            highlightHolidays: boolean;
            style: TextStyleConfig; // Estilo para dias destacados
        }
    }
  };
}

export interface IntroPage {
    id: string;
    name: string;
    elements: LayoutElement[];
}

export interface PageMargins {
  top: number;    // mm
  bottom: number; // mm
  inside: number; // mm (Encadernação/Espinha) - Substitui Left em páginas ímpares
  outside: number;// mm (Corte) - Substitui Right em páginas ímpares
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_weekend_shared';
export type PageSize = 'A4' | 'A5' | 'Letter';
export type PageOrientation = 'portrait' | 'landscape';

export interface AgendaConfig {
  year: number;
  layoutType: PageLayoutType;
  pageSize: PageSize;
  orientation: PageOrientation;
  includeHolidays: boolean;
  includeMoonPhases: boolean;
  includeQuotes: boolean;
  mirrorEvenPages: boolean; // Nova flag para ativar espelhamento automático
  margins: PageMargins;
  elements: LayoutElement[]; // Lista de elementos que compõem o template do dia (MIOLO)
  introPages: IntroPage[]; // Lista de páginas iniciais (DADOS, CALENDARIOS, ETC)
}

