               <div className="flex border border-gray-200 rounded overflow-hidden divide-x divide-gray-100"><button onClick={() => onChange({ textTransform: 'none' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${values.textTransform === 'none' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`} title="Normal"><TypeIcon className="w-3.5 h-3.5 mx-auto"/></button><button onClick={() => onChange({ textTransform: 'uppercase' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${values.textTransform === 'uppercase' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`} title="Maiúsculas"><CaseUpper className="w-3.5 h-3.5 mx-auto"/></button><button onClick={() => onChange({ textTransform: 'lowercase' })} className={`flex-1 p-1.5 hover:bg-gray-50 ${values.textTransform === 'lowercase' ? 'bg-indigo-50 text-indigo-600' : 'text-gray-500'}`} title="Minúsculas"><CaseLower className="w-3.5 h-3.5 mx-auto"/></button></div>
