                                                        <div className="flex gap-2">
                                                            <div className="flex-1">
                                                                <label className="text-[9px] text-gray-400">Tipo</label>
                                                                <select value={selectedElement.style.borderStyle || 'solid'} onChange={(e) => updateElementStyle(selectedElement.id, { borderStyle: e.target.value })} className="w-full text-xs p-1 border rounded bg-white">
                                                                    <option value="solid">Sólido</option>
                                                                    <option value="dashed">Tracejado</option>
                                                                    <option value="dotted">Pontilhado</option>
                                                                    <option value="double">Duplo</option>
