                >
                    {/* Margins Visualization */}
                    <div className="absolute border border-dashed border-indigo-300"
                        style={{
                            top: `${margins.top/2}px`,
                            bottom: `${margins.bottom/2}px`,
                            left: `${margins.inside/2}px`,
                            right: `${margins.outside/2}px`
                        }}
                    ></div>
                    <div className="absolute inset-0 flex items-center justify-center text-gray-300 text-[10px] font-mono">
