            )}
            {activeTab === 'preview' && (<div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500"><div className="max-w-[210mm] mx-auto"><div id="print-area">{generatedData.length === 0 ? (<div className="text-center py-20 text-white">Carregando visualização...</div>) : (<div className="space-y-8"><div className="p-4 bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 text-sm mb-4 no-print shadow-lg"><p className="font-bold">Pré-visualização (Início + 4 Pág Miolo)</p><p className="text-xs font-normal mt-1 text-yellow-800">Tamanho: {config.pageSize} ({PAGE_WIDTH_MM}mm x {PAGE_HEIGHT_MM}mm) - {config.orientation === 'portrait' ? 'Retrato' : 'Paisagem'}</p></div><div className="no-print">{renderPrintLayout().slice(0, config.introPages.length + 4)}</div></div>)}</div></div></div>)}
        </main>
    </div>
  );
};

import React, { useState } from 'react';
import Login from './modules/auth/Login';
import { Dashboard } from './modules/editor/Dashboard';
import { InitialSetup } from './modules/editor/InitialSetup';
import { User, AppState, AgendaConfig } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [appState, setAppState] = useState<AppState>(AppState.LOGIN);
  const [initialConfig, setInitialConfig] = useState<Partial<AgendaConfig> | undefined>(undefined);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setAppState(AppState.INITIAL_SETUP);
  };

  const handleInitialSetupComplete = (config: Partial<AgendaConfig>) => {
      setInitialConfig(config);
      setAppState(AppState.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAppState(AppState.LOGIN);
    setInitialConfig(undefined);
  };

  return (
    <>
      {appState === AppState.LOGIN && (
        <Login onLogin={handleLogin} />
      )}

      {appState === AppState.INITIAL_SETUP && currentUser && (
          <InitialSetup onComplete={handleInitialSetupComplete} userEmail={currentUser.email} />
      )}

      {appState === AppState.DASHBOARD && currentUser && (
        <Dashboard user={currentUser} initialConfig={initialConfig} onLogout={handleLogout} />
      )}
    </>
  );
};

export default App;

