                {/* Tamanho e Orientação */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="flex items-center text-sm font-bold text-gray-700 uppercase mb-3 gap-2">
                            <FileText className="w-4 h-4 text-indigo-500" /> Tamanho da Página
                        </label>
                        <div className="space-y-2">
                            {(Object.keys(PAGE_SIZES) as PageSize[]).map((size) => (
                                <label key={size} className={`flex items-center p-3 border rounded-lg cursor-pointer transition-all ${pageSize === size ? 'border-indigo-500 bg-indigo-50 ring-1 ring-indigo-500' : 'border-gray-200 hover:border-indigo-300'}`}>
