                                                    // Approximate jump to month (approx 30 pages per month)
                                                    const monthIndex = parseInt(e.target.value);
                                                    const approxPage = config.introPages.length + (monthIndex * 30);
                                                    setPreviewPage(Math.floor(approxPage / ITEMS_PER_PAGE));
                                                }}
                                            >
                                                <option value="">Pular para Mês...</option>
                                                {Array.from({length: 12}).map((_, i) => (
                                                    <option key={i} value={i}>{getMonthName(i)}</option>
                                                ))}
                                            </select>

                                            <button 
                                                onClick={() => setPreviewPage(previewPage + 1)} 
                                                disabled={currentPreviewEnd >= totalPages}
                                                className="p-2 border rounded hover:bg-gray-100 disabled:opacity-50 disabled:cursor-not-allowed"
                                                title="Próximas Páginas"
                                            >
                                                <ChevronRight className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>

                                    {/* Preview Content (Spread View) */}
                                    <div className="no-print flex flex-wrap justify-center gap-4 pb-20">
                                        {renderPrintLayout(currentPreviewStart, currentPreviewEnd)}
                                    </div>
                                 </div>
                             )}
                        </div>
                    </div>
                </div>
            )}
        </main>
    </div>
  );
};

