      */}
      {printStatus !== 'idle' && (
          <div className="print-only">
              {renderPrintLayout(undefined, undefined, renderedDaysCount)}
          </div>
      )}

      {/* Printing Overlay Status with Real Progress */}
      {printStatus !== 'idle' && (
