                                                             <label className="flex items-center text-xs text-gray-600 cursor-pointer"><input type="checkbox" checked={selectedElement.style.fullCalendar.specialDays?.highlightHolidays || false} onChange={(e) => updateFullCalendarSpecialFlags(selectedElement.id, { highlightHolidays: e.target.checked })} className="mr-2 rounded text-indigo-600 focus:ring-indigo-500" />Destacar Feriados</label>
                                                         </div>
                                                         <div className="h-px bg-gray-100 mb-2"></div>
                                                         <p className="text-[10px] font-bold text-gray-400 uppercase mb-1">Estilo do Destaque</p>
                                                     </div>
