                                </div>
                                <div className="p-2 grid grid-cols-3 gap-1">
                                    <button onClick={() => alignElement('left')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Esquerda"><AlignStartHorizontal className="w-4 h-4 mx-auto" /></button>
                                    <button onClick={() => alignElement('center')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Horizontalmente"><AlignCenterHorizontal className="w-4 h-4 mx-auto" /></button>
                                    <button onClick={() => alignElement('right')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Direita"><AlignEndHorizontal className="w-4 h-4 mx-auto" /></button>

                                    <button onClick={() => alignElement('top')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar ao Topo"><ArrowUpToLine className="w-4 h-4 mx-auto" /></button>
                                    <button onClick={() => alignElement('middle')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Centralizar Verticalmente"><AlignCenterVertical className="w-4 h-4 mx-auto" /></button>
                                    <button onClick={() => alignElement('bottom')} className="p-1.5 hover:bg-indigo-50 rounded text-gray-600 hover:text-indigo-600" title="Alinhar à Base"><ArrowDownToLine className="w-4 h-4 mx-auto" /></button>
                                </div>
                            </div>
                        )}

                        {showLayers && (
                            <div className="absolute left-4 top-20 w-64 bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col max-h-[50vh] z-40 no-print animate-in fade-in zoom-in-95 duration-200">
                                <div className="flex items-center justify-between p-3 border-b border-gray-100 bg-gray-50 rounded-t-lg">
                                    <div className="flex items-center text-gray-500 font-bold text-xs uppercase tracking-wide"><Layers className="w-3 h-3 mr-1.5" /> Camadas</div>
                                    <button onClick={() => setShowLayers(false)} className="text-gray-400 hover:text-red-500"><X className="w-4 h-4" /></button>
                                </div>
                                <div className="p-2 overflow-y-auto custom-scrollbar">
                                    {getActiveElements().slice().reverse().map((el) => (<div key={el.id} onClick={() => setSelectedId(el.id)} className={`flex items-center p-2 rounded text-xs cursor-pointer border group/layer mb-1 ${selectedId === el.id ? 'bg-indigo-50 border-indigo-300 text-indigo-700' : 'bg-white border-gray-100 text-gray-600 hover:bg-gray-50'}`}><span className="flex-1 truncate font-medium">{el.name || el.type}</span><div className="flex items-center opacity-0 group-hover/layer:opacity-100 transition-opacity"><button onClick={(e) => moveLayer(el.id, 'up')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-0.5"><ChevronUp className="w-3 h-3" /></button><button onClick={(e) => moveLayer(el.id, 'down')} className="p-1 hover:text-indigo-600 hover:bg-indigo-100 rounded mr-1"><ChevronDown className="w-3 h-3" /></button><button onClick={(e) => { e.stopPropagation(); removeElement(el.id); }} className="text-gray-400 hover:text-red-500 p-1 hover:bg-red-50 rounded"><Trash2 className="w-3 h-3" /></button></div></div>))}
                                    {getActiveElements().length === 0 && <div className="text-center text-gray-400 text-xs py-4">Sem camadas</div>}
                                </div>
                            </div>
                        )}

                        {/* Floating Properties Panel */}
                        {showProperties && activeTab === 'editor' && (
                            <div className="absolute right-4 top-4 w-72 bg-white rounded-lg shadow-xl border border-gray-200 flex flex-col max-h-[85vh] z-40 no-print animate-in slide-in-from-right-5 duration-200">
                                <div className="flex items-center justify-between p-3 border-b border-gray-100 bg-gray-50 rounded-t-lg cursor-move" onDoubleClick={() => setShowProperties(false)}>
                                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Propriedades</h3>
                                    <div className="flex items-center gap-1">
                                        <button onClick={() => setShowProperties(false)} className="text-gray-400 hover:text-gray-600"><Minimize2 className="w-3 h-3" /></button>
                                    </div>
                                </div>
                                <div className="overflow-y-auto custom-scrollbar flex-1">
                                    {selectedElement ? (
                                        <div className="p-4 space-y-5">
                                            {/* ... Properties Content ... */}
                                            <div className="space-y-2">
                                                <label className="block text-[10px] font-bold text-gray-500 uppercase">Nome da Camada</label>
                                                <input type="text" value={selectedElement.name || selectedElement.type} onChange={(e) => updateElementName(selectedElement.id, e.target.value)} className="w-full text-xs p-2 border border-gray-200 rounded focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500" />
                                            </div>
                                            <div className="h-px bg-gray-100"></div>

                                            <div className="grid grid-cols-2 gap-3">
                                                <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Largura %</label><div className="flex items-center"><input type="range" min="5" max="100" value={Math.round(selectedElement.w)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, w: parseInt(e.target.value)} : el))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.w)}</span></div></div>
                                                <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Altura %</label><div className="flex items-center"><input type="range" min="2" max="100" value={Math.round(selectedElement.h)} onChange={(e) => updateActiveElements(getActiveElements().map(el => el.id === selectedId ? {...el, h: parseInt(e.target.value)} : el))} className="w-full mr-2" /><span className="text-xs w-6">{Math.round(selectedElement.h)}</span></div></div>
                                            </div>

                                            {/* ... (Rest of properties panel logic unchanged) ... */}
                                            {selectedElement.type === 'table' && selectedElement.style.table && (
                                                <div className="pt-3 border-t border-gray-100">
                                                    <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-3">Configuração da Tabela</h4>
                                                    <div className="space-y-3">
                                                        <div className="grid grid-cols-2 gap-2">
                                                            <div><label className="block text-[10px] text-gray-500 mb-1">Linhas ({selectedElement.style.table.rows})</label><input type="range" min="1" max="50" value={selectedElement.style.table.rows} onChange={(e) => updateTableConfig(selectedElement.id, { rows: parseInt(e.target.value) })} className="w-full" /></div>
                                                            <div><label className="block text-[10px] text-gray-500 mb-1">Colunas ({selectedElement.style.table.cols})</label><input type="range" min="1" max="10" value={selectedElement.style.table.cols} onChange={(e) => updateTableConfig(selectedElement.id, { cols: parseInt(e.target.value) })} className="w-full" /></div>
                                                        </div>
                                                        <div className="flex items-center justify-between"><label className="text-[10px] font-bold text-gray-500">Borda (px)</label><input type="number" min="0" max="5" step="0.25" value={selectedElement.style.table.borderWidth} onChange={(e) => updateTableConfig(selectedElement.id, { borderWidth: parseFloat(e.target.value) })} className="w-16 text-xs p-1 border rounded" /></div>
                                                        <div className="flex items-center justify-between"><label className="text-[10px] font-bold text-gray-500">Cor Borda</label><div className="flex h-6 border border-gray-200 rounded overflow-hidden"><input type="color" value={selectedElement.style.table.borderColor} onChange={(e) => updateTableConfig(selectedElement.id, { borderColor: e.target.value })} className="w-8 h-full p-0 border-0 cursor-pointer" /></div></div>
                                                        <label className="flex items-center gap-2 cursor-pointer"><input type="checkbox" checked={selectedElement.style.table.headerRow} onChange={(e) => updateTableConfig(selectedElement.id, { headerRow: e.target.checked })} className="rounded text-indigo-600" /><span className="text-[10px] text-gray-600">Linha de Cabeçalho</span></label>
                                                    </div>
                                                    <div className="pt-3 mt-3 border-t border-gray-100 bg-gray-50 p-2 rounded">
                                                        <h4 className="text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-2">Bordas do Grid</h4>
                                                        <div className="grid grid-cols-3 gap-1 mb-2">
                                                            {renderBorderToggle(selectedElement.style.table.borders?.top ?? true, () => toggleTableBorder('top'), <PanelTop className="w-4 h-4"/>, "Topo")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.headerSeparator ?? true, () => toggleTableBorder('headerSeparator'), <Minus className="w-4 h-4"/>, "Separador Header")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.bottom ?? true, () => toggleTableBorder('bottom'), <PanelBottom className="w-4 h-4"/>, "Base")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.left ?? true, () => toggleTableBorder('left'), <PanelLeft className="w-4 h-4"/>, "Esquerda")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.insideVertical ?? true, () => toggleTableBorder('insideVertical'), <Columns className="w-4 h-4"/>, "Internas Vert.")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.right ?? true, () => toggleTableBorder('right'), <PanelRight className="w-4 h-4"/>, "Direita")}
                                                            {renderBorderToggle(selectedElement.style.table.borders?.insideHorizontal ?? true, () => toggleTableBorder('insideHorizontal'), <Rows className="w-4 h-4"/>, "Internas Horiz.")}
                                                        </div>
                                                    </div>
                                                    <div className="pt-3 mt-3 border-t border-gray-100">
                                                        <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">Estilo de Texto</h4>
                                                        {renderTypographyControls(selectedElement.style.table.textStyle || { fontFamily: 'Inter', fontSize: 10, fontWeight: 'normal', color: '#666', textAlign: 'left', verticalAlign: 'top', textTransform: 'none', letterSpacing: 0, backgroundColor: 'transparent' }, (updates) => updateTableConfig(selectedElement.id, { textStyle: { ...selectedElement.style.table?.textStyle, ...updates } }))}
                                                    </div>
                                                </div>
                                            )}

                                            {(selectedElement.type === 'full_calendar' || selectedElement.type === 'mini_calendar') && selectedElement.style.fullCalendar && (
                                                <div className="pt-3 border-t border-gray-100">
                                                    <div className="space-y-3 mb-3">
                                                        <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Configuração do Grid</h4>
                                                        {selectedElement.type === 'full_calendar' && (
                                                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Meses por Linha ({selectedElement.style.monthsPerRow})</label><input type="range" min="1" max="12" value={selectedElement.style.monthsPerRow || 3} onChange={(e) => updateElementStyle(selectedElement.id, { monthsPerRow: parseInt(e.target.value) })} className="w-full" /></div>
                                                        )}
                                                        {selectedElement.type === 'mini_calendar' && (
                                                            <div>
                                                                <label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Mês Exibido</label>
                                                                <div className="flex rounded border border-gray-200 overflow-hidden">
                                                                    <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: -1 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === -1 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Anterior</button>
                                                                    <div className="w-px bg-gray-200"></div>
                                                                    <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: 0 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === 0 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Atual</button>
                                                                    <div className="w-px bg-gray-200"></div>
                                                                    <button onClick={() => updateElementStyle(selectedElement.id, { calendarOffset: 1 })} className={`flex-1 py-1 text-[10px] ${selectedElement.style.calendarOffset === 1 ? 'bg-indigo-50 text-indigo-700 font-bold' : 'hover:bg-gray-50'}`}>Próximo</button>
                                                                </div>
                                                            </div>
                                                        )}
                                                        {selectedElement.type === 'full_calendar' && (
                                                            <div><label className="block text-[10px] font-bold text-gray-500 mb-1 uppercase">Espaçamento (Gap)</label><input type="range" min="0" max="50" value={selectedElement.style.gap || 10} onChange={(e) => updateElementStyle(selectedElement.id, { gap: parseInt(e.target.value) })} className="w-full" /></div>
                                                        )}
                                                    </div>
                                                    <div className="flex bg-gray-100 p-1 rounded mb-3 overflow-x-auto">
                                                        <button onClick={() => setFontControlTab('title')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'title' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Título</button>
                                                        <button onClick={() => setFontControlTab('weekDays')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'weekDays' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Semana</button>
                                                        <button onClick={() => setFontControlTab('days')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'days' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Dias</button>
                                                        <button onClick={() => setFontControlTab('highlight')} className={`flex-1 min-w-[50px] py-1 text-[10px] font-bold uppercase rounded whitespace-nowrap ${fontControlTab === 'highlight' ? 'bg-white shadow text-indigo-600' : 'text-gray-500'}`}>Destaques</button>
                                                    </div>
                                                    <div className="bg-white rounded border border-gray-100 p-2 shadow-sm">
                                                        {renderTypographyControls(
                                                            fontControlTab === 'highlight' ? selectedElement.style.fullCalendar.specialDays?.style : selectedElement.style.fullCalendar[fontControlTab],
                                                            (updates) => updateFullCalendarStyle(selectedElement.id, fontControlTab, updates)
                                                        )}
                                                    </div>
                                                </div>
                                            )}

                                            {['day_number', 'day_name', 'month_name', 'year', 'quote', 'text', 'holiday', 'moon', 'holiday_list'].includes(selectedElement.type) && !selectedElement.style.fullCalendar && (
                                                <div className="space-y-3 pt-3 border-t border-gray-100">
                                                    {selectedElement.type === 'text' && (
                                                        <button onClick={fitToText} className="w-full mb-2 py-1.5 px-3 bg-indigo-50 text-indigo-700 text-xs font-bold rounded border border-indigo-200 hover:bg-indigo-100 transition-colors flex items-center justify-center"><BoxSelect className="w-3 h-3 mr-1.5"/> Ajustar Quadro ao Texto</button>
                                                    )}
                                                    {renderTypographyControls({
                                                        fontFamily: selectedElement.style.fontFamily || 'Inter',
                                                        fontSize: selectedElement.style.fontSize || 12,
                                                        fontWeight: selectedElement.style.fontWeight || 'normal',
                                                        color: selectedElement.style.color || '#000000',
                                                        textAlign: selectedElement.style.textAlign || 'left',
                                                        textTransform: 'none', 
                                                        letterSpacing: 0,
                                                        backgroundColor: selectedElement.style.backgroundColor
                                                    } as TextStyleConfig, (updates) => updateElementStyle(selectedElement.id, updates))}
                                                </div>
                                            )}

                                            <div className="pt-6">
                                                <button onClick={() => removeElement(selectedElement.id)} className="w-full py-2 px-4 bg-white border border-red-200 text-red-600 rounded hover:bg-red-50 flex items-center justify-center text-sm transition-colors"><Trash2 className="w-4 h-4 mr-2" /> Excluir Elemento</button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="p-8 text-center text-gray-400 flex flex-col items-center justify-center h-full">
                                            <Move className="w-12 h-12 mb-4 opacity-20" />
                                            <p className="text-sm font-medium">Nenhum elemento selecionado</p>
                                            <p className="text-xs mt-2 opacity-70">Clique em um elemento para editar.</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {config.layoutType === '1_per_page_weekend_shared' && editMode === 'daily' && (<div className="mb-4 bg-white p-1 rounded-lg shadow-sm flex space-x-1 z-10"><button onClick={() => setEditorViewMode('standard')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'standard' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Dias da Semana</button><button onClick={() => setEditorViewMode('weekend')} className={`px-3 py-1 text-xs font-medium rounded ${editorViewMode === 'weekend' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-600 hover:bg-gray-50'}`}>Fim de Semana</button></div>)}
                        {editMode === 'intro' && (<div className="mb-4 bg-indigo-100 text-indigo-800 px-3 py-1 rounded text-xs font-bold uppercase tracking-wide z-10 shadow-sm border border-indigo-200">Editando: {config.introPages.find(p => p.id === currentIntroPageId)?.name || 'Página'}</div>)}
                        <div className="flex-1 w-full flex items-center justify-center overflow-auto custom-scrollbar"><div className="flex flex-col items-center">{renderEditorPage()}</div></div>
                    </div>
                )}
                {activeTab === 'preview' && (
                    <div className="flex-1 w-full overflow-y-auto p-8 custom-scrollbar bg-gray-500">
                        <div className="max-w-[95vw] md:max-w-6xl mx-auto">
                            <div id="print-area">
                                {generatedData.length === 0 ? (<div className="text-center py-20 text-white">Carregando visualização...</div>) : (
                                    <div className="space-y-4">
                                        <div className="p-4 bg-white rounded shadow-lg sticky top-0 z-50 flex items-center justify-between no-print border-l-4 border-indigo-600">
                                            <div className="flex flex-col">
                                                <span className="text-xs font-bold text-gray-500 uppercase tracking-wide">Pré-visualização</span>
                                                <span className="text-sm font-semibold text-gray-800">
                                                    Mostrando {renderedPreviewCount < generatedData.length ? 'carregando...' : 'todas as páginas'}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <div className="relative">
                                                    <Search className="w-4 h-4 absolute left-2 top-2.5 text-gray-400 pointer-events-none" />
                                                    <select 
                                                        className="text-xs pl-8 pr-4 py-2 border border-gray-300 rounded bg-gray-50 focus:ring-2 focus:ring-indigo-500 outline-none" 
                                                        onChange={(e) => handleScrollToMonth(parseInt(e.target.value))}
                                                    >
                                                        <option value="">Pular para Mês...</option>
                                                        {Array.from({length: 12}).map((_, i) => (<option key={i} value={i}>{getMonthName(i)}</option>))}
                                                    </select>
                                                </div>
                                            </div>
                                        </div>
                                        {/* Container ajustado para exibir páginas lado a lado (wrap) */}
                                        <div className="no-print flex flex-wrap justify-center content-start gap-8 pb-20">
                                            {renderPrintLayout(undefined, undefined, renderedPreviewCount)}
                                        </div>
                                        {renderedPreviewCount < generatedData.length && (
                                            <div className="no-print flex justify-center pb-20">
                                                <div className="flex items-center gap-2 bg-white/20 text-white px-4 py-2 rounded-full backdrop-blur-sm">
                                                    <Loader2 className="w-4 h-4 animate-spin" />
                                                    <span className="text-xs font-medium">Carregando mais páginas...</span>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
      </div>
    </div>
  );
};

export interface User {
  email: string;
  name: string;
  plan: 'free' | 'pro';
}

export interface Holiday {
  date: string; // ISO format YYYY-MM-DD
  name: string;
  type: 'national' | 'optional';
}

export interface DayData {
  date: Date;
  dayOfWeek: number; // 0-6
  dayOfMonth: number;
  month: number; // 0-11
  year: number;
  holiday?: string;
  moonPhase?: string;
  quote?: string;
}

// Tipos de elementos que podem ser arrastados para a página
export type ElementType = 
  | 'text'
  | 'day_number' 
  | 'day_name' 
  | 'month_name' 
  | 'year' 
  | 'lines' 
  | 'box' 
  | 'circle' 
  | 'quote' 
  | 'moon' 
  | 'holiday' 
  | 'habit_tracker' 
  | 'vector_flower' 
  | 'note_grid'
  | 'mini_calendar'
  | 'full_calendar' // Calendário Anual
  | 'holiday_list' // Lista de Feriados Editável
  | 'table'; // Nova Tabela

export interface TextStyleConfig {
    fontFamily: string;
    fontSize: number;
    fontWeight: string;
    color: string;
    textAlign: 'left' | 'center' | 'right' | 'justify'; // Adicionado justify
    verticalAlign?: 'top' | 'middle' | 'bottom'; 
    textTransform: 'none' | 'uppercase' | 'lowercase' | 'capitalize';
    letterSpacing: number; // Tracking
    backgroundColor?: string; // Usado para destaques
}

export interface LayoutElement {
  id: string;
  name?: string; // Nome legível para a camada
  type: ElementType;
  content?: string; // Conteúdo de texto editável (para holiday_list e text)
  x: number; // Posição X em % (0-100) relativo à área útil da página
  y: number; // Posição Y em % (0-100)
  w: number; // Largura em %
  h: number; // Altura em %
  zIndex: number;
  style: {
    fontFamily?: string;
    fontSize?: number;
    fontWeight?: string;
    color?: string; // Cor do texto ou contorno (Stroke para vetores)
    backgroundColor?: string; // Preenchimento (Fill para vetores)
    borderColor?: string;
    borderWidth?: number;
    borderStyle?: 'solid' | 'dashed' | 'dotted' | 'double' | 'groove' | 'ridge'; // Novo: Estilo de linha
    borderRadius?: number;
    textAlign?: 'left' | 'center' | 'right' | 'justify';
    verticalAlign?: 'top' | 'middle' | 'bottom'; // Novo
    textTransform?: 'none' | 'uppercase' | 'lowercase' | 'capitalize';
    letterSpacing?: number;
    opacity?: number;
    lineSpacing?: number; // Para pautas
    showTimes?: boolean; // Para pautas com horário
    startHour?: number; // Hora inicial para pautas
    rotation?: number; // Em graus
    flipX?: boolean; // Espelhar horizontalmente
    flipY?: boolean; // Espelhar verticalmente
    variant?: string;
    calendarOffset?: number; // -1 (mês anterior), 0 (atual), 1 (próximo)
    monthsPerRow?: number; // Para full_calendar: quantos meses por linha
    gap?: number; // Espaçamento entre meses

    // Configurações para Tabela
    table?: {
        rows: number;
        cols: number;
        borderColor: string;
        borderWidth: number;
        headerRow: boolean;
        rowHeight?: number; // Altura mínima da linha em px (no editor)
        columnWidths?: number[]; // Array de porcentagens para largura das colunas
        cellContent?: Record<string, string>; // Mapa "row-col" -> "texto"
        textStyle?: TextStyleConfig; // Estilo de texto global da tabela
        rowStyles?: Record<number, TextStyleConfig>; // Estilos específicos por índice de linha
        colStyles?: Record<number, TextStyleConfig>; // Estilos específicos por índice de coluna
        borders?: {
            top: boolean;
            bottom: boolean;
            left: boolean;
            right: boolean;
            insideHorizontal: boolean;
            insideVertical: boolean;
            headerSeparator: boolean;
        };
    };

    // Configurações granulares para o Calendário Completo
    fullCalendar?: {
        title: TextStyleConfig;
        weekDays: TextStyleConfig;
        days: TextStyleConfig;
        // Estilo de Tabela (Grid)
        grid?: {
            borderColor: string;
            borderWidth: number;
            cellBackgroundColor: string; // Fundo do dia
            headerBackgroundColor: string; // Fundo da barra de dias da semana
            borders: {
                top: boolean;
                bottom: boolean;
                left: boolean;
                right: boolean;
                insideHorizontal: boolean;
                insideVertical: boolean;
                headerSeparator: boolean; // Nova propriedade
            }
        };
        specialDays?: {
            highlightSundays: boolean;
            highlightHolidays: boolean;
            style: TextStyleConfig; // Estilo para dias destacados
        }
    }
  };
}

export interface IntroPage {
    id: string;
    name: string;
    elements: LayoutElement[];
}

export interface PageMargins {
  top: number;    // mm
  bottom: number; // mm
  inside: number; // mm (Encadernação/Espinha) - Substitui Left em páginas ímpares
  outside: number;// mm (Corte) - Substitui Right em páginas ímpares
}

export type PageLayoutType = '1_per_page' | '2_per_page' | '1_per_page_weekend_shared';
