                elements.forEach(el => {
                    const halfH_El = { ...el, h: el.h / 2, y: el.y / 2 };
                    renderElementToPDF(doc, halfH_El, day, quotes[day.month], pageW, pageH);
                });

                // Bottom Half: Sunday (if exists)
                const nextDay = generatedDays[i+1];
                if (nextDay) {
                    elements.forEach(el => {
                        const halfH_El = { ...el, h: el.h / 2, y: (el.y / 2) + 50 };
                        renderElementToPDF(doc, halfH_El, nextDay, quotes[nextDay.month], pageW, pageH);
                    });

                    // Separator
                    doc.setDrawColor(200, 200, 200);
                    doc.setLineDash([2, 2], 0);
                    doc.line(0, pageH / 2, pageW, pageH / 2);
                    doc.setLineDash([], 0);
                }

                i += 2; // Skip next day as it's handled here
            } else {
                // Full Page for Weekdays
                elements.forEach(el => renderElementToPDF(doc, el, day, quotes[day.month], pageW, pageH));
                i += 1;
            }

            if (globalPageCount % 10 === 0) {
                onProgress(Math.round((globalPageCount / totalPages) * 100));
                await new Promise(r => setTimeout(r, 0));
            }
        }
    }

    onProgress(100);
    doc.save(`Agenda_${config.year}.pdf`);
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
