} from 'lucide-react';

interface DashboardProps {
  user: User;
  initialConfig?: Partial<AgendaConfig>;
  onLogout: () => void;
  onConfigure?: () => void;
}

const PAGE_SIZES_MM: Record<PageSize, { width: number; height: number }> = {
    'A4': { width: 210, height: 297 },
    'A5': { width: 148, height: 210 },
    'Letter': { width: 215.9, height: 279.4 }
};

export const Dashboard: React.FC<DashboardProps> = ({ user, initialConfig, onLogout, onConfigure }) => {
  const getDefaultElements = (): LayoutElement[] => [
      { 
          id: '1', 
          name: 'Texto Livre', 
          type: 'text', 
          content: 'Seu texto aqui', 
          x: 10, 
          y: 10, 
          w: 80, 
          h: 10, 
          zIndex: 10, 
          style: { fontSize: 14, fontWeight: 'normal', color: '#000000', textAlign: 'left', fontFamily: 'Inter' } 
      }
  ];

  const [config, setConfig] = useState<AgendaConfig>({
    year: initialConfig?.year || new Date().getFullYear() + 1,
    layoutType: initialConfig?.layoutType || '1_per_page',
    pageSize: initialConfig?.pageSize || 'A5',
    orientation: initialConfig?.orientation || 'portrait',
    includeHolidays: initialConfig?.includeHolidays ?? true,
    includeMoonPhases: initialConfig?.includeMoonPhases ?? false,
    includeQuotes: initialConfig?.includeQuotes ?? false,
    mirrorEvenPages: initialConfig?.mirrorEvenPages ?? true,
    margins: initialConfig?.margins || { top: 15, bottom: 15, inside: 20, outside: 10 },
    elements: initialConfig?.elements && initialConfig.elements.length > 0 ? initialConfig.elements : getDefaultElements(),
    introPages: initialConfig?.introPages || [
        { id: 'intro-1', name: 'Dados Pessoais', elements: [{ id: 'ip1', type: 'text', content: 'DADOS PESSOAIS', name: 'Título', x: 10, y: 10, w: 80, h: 10, zIndex: 1, style: { fontSize: 24, fontWeight: 'bold', textAlign: 'center', color: '#333' } }] }
    ]
  });

  const [generatedData, setGeneratedData] = useState<DayData[]>([]);
  const [quotes, setQuotes] = useState<string[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'editor' | 'preview'>('editor');
  const [showMargins, setShowMargins] = useState(true);
  const [customFonts, setCustomFonts] = useState<string[]>([]);
  const [variantModal, setVariantModal] = useState<{type: ElementType, label: string} | null>(null);
  const [editorViewMode, setEditorViewMode] = useState<'standard' | 'weekend'>('standard');

  // --- RENDERING STATE (Batching System) ---
  const [renderedPreviewCount, setRenderedPreviewCount] = useState(0); 
  // No longer needed for printing, but kept for preview logic

  const [printStatus, setPrintStatus] = useState<'idle' | 'generating' | 'downloading'>('idle');
  const [printProgress, setPrintProgress] = useState(0);

  // Panel States
  const [showLayers, setShowLayers] = useState(false);
  const [showProperties, setShowProperties] = useState(true);
  const [showAlignment, setShowAlignment] = useState(false);

  // Interaction States
  const [isDragging, setIsDragging] = useState(false);
  const [resizeDir, setResizeDir] = useState<string | null>(null);

  // Table Specific Interactions
  const [resizingTableCol, setResizingTableCol] = useState<{ elementId: string, colIndex: number } | null>(null);
  const [activeTableCell, setActiveTableCell] = useState<{ r: number, c: number } | null>(null);
  const [tableStyleScope, setTableStyleScope] = useState<'global' | 'row' | 'col'>('global');

  const [fontControlTab, setFontControlTab] = useState<'title' | 'weekDays' | 'days' | 'highlight'>('title');

  const [editMode, setEditMode] = useState<'daily' | 'intro'>('daily');
  const [currentIntroPageId, setCurrentIntroPageId] = useState<string | null>(config.introPages[0]?.id || null);

  const dragRef = useRef<any>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // -- PREVIEW BATCH RENDERER LOGIC --
  useEffect(() => {
      if (activeTab === 'preview') {
          if (renderedPreviewCount < generatedData.length) {
              const timer = setTimeout(() => {
                  setRenderedPreviewCount(prev => Math.min(prev + 20, generatedData.length));
              }, 10);
              return () => clearTimeout(timer);
          }
      } else {
          if (renderedPreviewCount > 0) setRenderedPreviewCount(0);
      }
  }, [activeTab, renderedPreviewCount, generatedData.length]);

  // -- NEW PDF GENERATION LOGIC --
  const handlePrintRequest = async () => {
      setPrintStatus('generating');
      setPrintProgress(0);

      try {
          await generateAndDownloadPDF(config, generatedData, quotes, (progress) => {
              setPrintProgress(progress);
          });
          setPrintStatus('downloading');
          // Short delay to show 100% then close
          setTimeout(() => {
              setPrintStatus('idle');
              setPrintProgress(0);
          }, 1000);
      } catch (error) {
          console.error("PDF Generation Error", error);
          alert("Ocorreu um erro ao gerar o PDF. Tente novamente.");
          setPrintStatus('idle');
      }
  };

  const cancelPrint = () => {
      // NOTE: JS execution is single threaded, so cancelling a running heavy async process 
      // without Web Workers is tricky. For this simpler implementation, we just reset state
      // but the background loop might finish. 
      setPrintStatus('idle');
      setPrintProgress(0);
  };

  // Keyboard Delete Logic
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Delete' || e.key === 'Backspace') {
            const activeElement = document.activeElement;
            const isInputActive = activeElement && (
                activeElement.tagName === 'INPUT' || 
                activeElement.tagName === 'TEXTAREA' || 
                (activeElement as HTMLElement).isContentEditable
            );

            if (!isInputActive && selectedId) {
                removeElement(selectedId);
            }
        }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedId, config]); 

  // Derived Page Dimensions
  const getPageDimensions = () => {
      const base = PAGE_SIZES_MM[config.pageSize];
      if (config.orientation === 'portrait') return base;
      return { width: base.height, height: base.width };
  };

  const { width: PAGE_WIDTH_MM, height: PAGE_HEIGHT_MM } = getPageDimensions();

  const EDITOR_WIDTH_PX = 400; 
  const EDITOR_SCALE = EDITOR_WIDTH_PX / PAGE_WIDTH_MM;
  const EDITOR_HEIGHT_PX = PAGE_HEIGHT_MM * EDITOR_SCALE;

  useEffect(() => {
    const data = generateCalendarYear(config.year, config.includeHolidays);
    setGeneratedData(data);
  }, [config.year, config.includeHolidays]);

  useEffect(() => {
    if (config.includeQuotes && quotes.length === 0) {
       generateMonthlyQuotes(config.year).then(setQuotes);
    }
  }, [config.includeQuotes, config.year]);

  // Open properties automatically when selecting an element
  useEffect(() => {
      if (selectedId) setShowProperties(true);
  }, [selectedId]);

  const getActiveElements = () => {
      if (editMode === 'daily') return config.elements;
      if (editMode === 'intro' && currentIntroPageId) {
          return config.introPages.find(p => p.id === currentIntroPageId)?.elements || [];
      }
      return [];
  };

  const updateActiveElements = (newElements: LayoutElement[]) => {
      if (editMode === 'daily') {
          setConfig(prev => ({ ...prev, elements: newElements }));
      } else if (editMode === 'intro' && currentIntroPageId) {
          setConfig(prev => ({
              ...prev,
              introPages: prev.introPages.map(p => p.id === currentIntroPageId ? { ...p, elements: newElements } : p)
          }));
      }
  };

  // ... (AlignElement, FitToText, IntroPage functions unchanged) ...
  const alignElement = (type: 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom') => {
      if (!selectedId) return;
      const activeList = getActiveElements();
      const element = activeList.find(el => el.id === selectedId);
      if (!element) return;

      const newEl = { ...element };

      switch(type) {
          case 'left': newEl.x = 0; break;
          case 'center': newEl.x = 50 - (newEl.w / 2); break;
          case 'right': newEl.x = 100 - newEl.w; break;
          case 'top': newEl.y = 0; break;
          case 'middle': newEl.y = 50 - (newEl.h / 2); break;
          case 'bottom': newEl.y = 100 - newEl.h; break;
      }
      updateActiveElements(activeList.map(el => el.id === selectedId ? newEl : el));
  };

  const fitToText = () => {
      if (!selectedId) return;
      const activeList = getActiveElements();
      const element = activeList.find(el => el.id === selectedId);
      if (!element || !element.content) return;

      const charCount = element.content.length;
      const fontSize = element.style.fontSize || 14;
      const estWidthPx = charCount * (fontSize * 0.6); 
      const estWidthPercent = (estWidthPx / EDITOR_WIDTH_PX) * 100;

      const newWidth = Math.min(90, Math.max(10, estWidthPercent));
      const newHeight = Math.max(5, (fontSize * 1.5 * (Math.ceil(estWidthPercent/90)) / EDITOR_HEIGHT_PX) * 100);

      updateActiveElements(activeList.map(el => el.id === selectedId ? { ...el, w: newWidth, h: newHeight } : el));
  };

  const addIntroPage = () => {
      const newPage = {
          id: Math.random().toString(36).substr(2, 9),
          name: `Página ${config.introPages.length + 1}`,
          elements: []
      };
      setConfig(prev => ({ ...prev, introPages: [...prev.introPages, newPage] }));
      setCurrentIntroPageId(newPage.id);
  };

  const renameIntroPage = (id: string, name: string) => {
      setConfig(prev => ({
          ...prev,
          introPages: prev.introPages.map(p => p.id === id ? { ...p, name } : p)
      }));
  };

  const deleteIntroPage = (id: string) => {
      setConfig(prev => {
          const newPages = prev.introPages.filter(p => p.id !== id);
          if (currentIntroPageId === id) {
              setCurrentIntroPageId(newPages[0]?.id || null);
          }
          return { ...prev, introPages: newPages };
      });
  };

  const handleFontUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          const fontData = event.target?.result as string;
          const fontName = file.name.split('.')[0].replace(/[^a-zA-Z0-9]/g, '');
          const newFont = new FontFace(fontName, `url(${fontData})`);
          newFont.load().then((loadedFont) => {
              (document.fonts as any).add(loadedFont);
              setCustomFonts(prev => [...prev, fontName]);
              if (selectedId) updateElementStyle(selectedId, { fontFamily: fontName });
          }).catch(err => alert("Erro ao carregar a fonte."));
      };
      reader.readAsDataURL(file);
  };

  const generateHolidayListText = () => {
      const holidays = generatedData.filter(d => d.holiday).sort((a,b) => a.date.getTime() - b.date.getTime());
      return holidays.map(h => {
          const day = String(h.dayOfMonth).padStart(2, '0');
          const month = String(h.month + 1).padStart(2, '0');
          return `${day}/${month} - ${h.holiday}`;
      }).join('\n');
  };

  // Scroll to approximate position for a month
  const handleScrollToMonth = (monthIndex: number) => {
      if (activeTab !== 'preview') return;

      // Calculate day index where month starts
      let dayIndex = 0;
      for (let i = 0; i < generatedData.length; i++) {
          if (generatedData[i].month === monthIndex) {
              dayIndex = i;
              break;
          }
      }

      // Estimate page number based on layout
      let pageNumber = config.introPages.length + 1; // Start after intro
      if (config.layoutType === '1_per_page') {
          pageNumber += dayIndex;
      } else if (config.layoutType === '2_per_page') {
          pageNumber += Math.floor(dayIndex / 2);
      } else if (config.layoutType === '1_per_page_weekend_shared') {
          // Simplification for scroll estimation
          let currentDay = 0;
          let p = config.introPages.length + 1;
          while (currentDay < dayIndex) {
              const day = generatedData[currentDay];
              if (!day) break;
              const isWeekend = day.dayOfWeek === 6;
              if (isWeekend) {
                  currentDay += 2; // Skips Sat and Sun (1 page)
              } else {
                  currentDay += 1;
              }
              p++;
          }
          pageNumber = p;
      }

      const element = document.getElementById(`preview-page-${pageNumber}`);
      if (element) {
          element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
  };

  const addElement = (type: ElementType, label: string, styleOverride: any = {}, sizeOverride: any = {}) => {
    const activeList = getActiveElements();
    const newElement: LayoutElement = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      name: `${label} ${activeList.length + 1}`,
      x: 35, y: 40, w: sizeOverride.w || 20, h: sizeOverride.h || 10, zIndex: activeList.length + 1,
      style: { fontSize: 14, color: '#000000', textAlign: 'left', lineSpacing: 24, borderColor: '#000000', borderWidth: 1, backgroundColor: 'transparent', rotation: 0, opacity: 1, flipX: false, flipY: false, fontFamily: 'Inter', showTimes: false, startHour: 7, borderStyle: 'solid', ...styleOverride }
    };

    if (type === 'text') { newElement.content = "Novo Texto"; }

    // Defaults for complex elements (unchanged)
    const defaultCalendarStyle = {
        title: { fontSize: 10, fontFamily: 'Inter', fontWeight: 'bold', color: '#000', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 1 },
        weekDays: { fontSize: 7, fontFamily: 'Inter', fontWeight: 'bold', color: '#666', textAlign: 'center' as const, textTransform: 'uppercase' as const, letterSpacing: 0 },
        days: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'normal', color: '#333', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0 },
        grid: { 
            borderColor: '#dddddd', borderWidth: 0.5, cellBackgroundColor: 'transparent', headerBackgroundColor: 'transparent',
            borders: { top: false, bottom: false, left: false, right: false, insideHorizontal: false, insideVertical: false, headerSeparator: true }
        },
        specialDays: {
            highlightSundays: true,
            highlightHolidays: false,
            style: { fontSize: 8, fontFamily: 'Inter', fontWeight: 'bold', color: '#dc2626', textAlign: 'center' as const, textTransform: 'none' as const, letterSpacing: 0, backgroundColor: 'transparent' }
        }
    };

    if (!sizeOverride.w) {
        if (type === 'lines') { newElement.w = 80; newElement.h = 40; newElement.x = 10; newElement.style.borderWidth = 0; }
        if (type === 'box') { newElement.w = 30; newElement.h = 15; newElement.style.backgroundColor = '#f3f4f6'; newElement.style.borderWidth = 0; }
        if (type === 'circle') { newElement.w = 15; newElement.h = 15; newElement.style.backgroundColor = '#e0e7ff'; newElement.style.borderRadius = 999; newElement.style.borderWidth = 0; }
        if (type === 'day_number') { newElement.w = 15; newElement.h = 10; newElement.style.fontSize = 32; newElement.style.fontWeight = 'bold'; newElement.style.borderWidth = 0; }
        if (type === 'text') { newElement.w = 30; newElement.h = 8; newElement.style.fontSize = 16; newElement.style.borderWidth = 0; }
        if (type === 'holiday') { newElement.w = 40; newElement.h = 5; newElement.style.fontSize = 10; newElement.style.color = '#ef4444'; newElement.style.borderWidth = 0; newElement.style.fontWeight = '500'; }
        if (type === 'moon') { newElement.w = 20; newElement.h = 5; newElement.style.fontSize = 12; newElement.style.color = '#6b7280'; newElement.style.borderWidth = 0; }
        if (type === 'vector_flower') { newElement.w = 20; newElement.h = 20; newElement.style.color = '#1f2937'; newElement.style.backgroundColor = '#e5e7eb'; newElement.style.borderWidth = 0; }
        if (type === 'habit_tracker') { newElement.w = 40; newElement.h = 15; newElement.style.borderWidth = 1; newElement.style.borderColor = '#d1d5db'; }
        if (type === 'note_grid') { newElement.w = 40; newElement.h = 20; newElement.style.opacity = 0.5; newElement.style.borderWidth = 0; }

        if (type === 'mini_calendar') { 
            newElement.w = 25; newElement.h = 18; 
            newElement.style.calendarOffset = 0;
            newElement.style.borderWidth = 0;
            newElement.style.fullCalendar = defaultCalendarStyle;
        }

        if (type === 'full_calendar') { 
            newElement.w = 90; newElement.h = 80; newElement.x = 5; newElement.y = 10; 
            newElement.style.borderWidth = 0; newElement.style.monthsPerRow = 3; newElement.style.gap = 15; 
            newElement.style.fullCalendar = {
                ...defaultCalendarStyle,
                title: { ...defaultCalendarStyle.title, fontSize: 14 },
                weekDays: { ...defaultCalendarStyle.weekDays, fontSize: 9 },
                days: { ...defaultCalendarStyle.days, fontSize: 10 },
                specialDays: { ...defaultCalendarStyle.specialDays, style: { ...defaultCalendarStyle.specialDays.style, fontSize: 10, backgroundColor: '#fee2e2' } }
            };
        }

        if (type === 'holiday_list') {
            newElement.w = 40; newElement.h = 60; newElement.x = 10; newElement.y = 10;
            newElement.style.fontSize = 10; newElement.style.color = '#333';
            newElement.content = generateHolidayListText();
        }

        if (type === 'table') {
            newElement.w = 80; newElement.h = 40; newElement.x = 10;
            newElement.style.borderWidth = 1;
            newElement.style.borderColor = '#d1d5db';
            newElement.style.table = {
                rows: 10,
                cols: 2,
                borderColor: '#d1d5db',
                borderWidth: 1,
                headerRow: true,
                columnWidths: [50, 50],
                cellContent: {},
                textStyle: {
                    fontFamily: 'Inter',
                    fontSize: 10,
                    fontWeight: 'normal',
                    color: '#4b5563',
                    textAlign: 'left',
                    verticalAlign: 'top',
                    textTransform: 'none',
                    letterSpacing: 0
                },
                rowStyles: {},
                colStyles: {},
                borders: {
                    top: true, bottom: true, left: true, right: true,
                    insideHorizontal: true, insideVertical: true, headerSeparator: true
                }
            };
        }
    }

    if (type === 'holiday') setConfig(prev => ({ ...prev, includeHolidays: true }));
    if (type === 'moon') setConfig(prev => ({ ...prev, includeMoonPhases: true }));
    if (type === 'quote') setConfig(prev => ({ ...prev, includeQuotes: true }));

    updateActiveElements([...activeList, newElement]);
    setSelectedId(newElement.id);
    setVariantModal(null);
  };

  const openElementSelector = (type: ElementType, label: string) => {
      if (ELEMENT_VARIANTS[type]) {
          setVariantModal({ type, label });
      } else {
          addElement(type, label);
      }
  };

  const removeElement = (id: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.filter(e => e.id !== id));
    setSelectedId(null);
  };

  const moveLayer = (id: string, direction: 'up' | 'down') => {
      const activeList = getActiveElements();
      const index = activeList.findIndex(e => e.id === id);
      if (index === -1) return;
      if (direction === 'up' && index === activeList.length - 1) return;
      if (direction === 'down' && index === 0) return;
      const newElements = [...activeList];
      const swapIndex = direction === 'up' ? index + 1 : index - 1;
      [newElements[index], newElements[swapIndex]] = [newElements[swapIndex], newElements[index]];
      const updatedElements = newElements.map((el, i) => ({ ...el, zIndex: i + 1 }));
      updateActiveElements(updatedElements);
  };

  const updateElementStyle = (id: string, styleUpdate: any) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, style: { ...e.style, ...styleUpdate } } : e));
  };

  const updateElementContent = (id: string, content: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, content } : e));
  };

  const updateTableConfig = (id: string, tableUpdate: any) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;

      let newTableStyle = { ...element.style.table, ...tableUpdate };

      if (tableUpdate.cols) {
          const newCols = tableUpdate.cols;
          const oldCols = element.style.table.cols;
          if (newCols > oldCols) {
              const baseWidth = 100 / newCols;
              newTableStyle.columnWidths = Array(newCols).fill(baseWidth);
          } else if (newCols < oldCols) {
              newTableStyle.columnWidths = newTableStyle.columnWidths?.slice(0, newCols) || Array(newCols).fill(100/newCols);
          }
      }

      updateElementStyle(id, { table: newTableStyle });
  }

  const toggleTableBorder = (borderKey: keyof NonNullable<Required<LayoutElement['style']['table']>['borders']>) => {
      const activeList = getActiveElements();
      const selectedElement = activeList.find(e => e.id === selectedId);
      if (!selectedElement || !selectedElement.style.table) return;

      const currentBorders = selectedElement.style.table.borders || { 
          top: true, bottom: true, left: true, right: true, 
          insideHorizontal: true, insideVertical: true, headerSeparator: true 
      };
      updateTableConfig(selectedElement.id, { 
          borders: { ...currentBorders, [borderKey]: !currentBorders[borderKey] } 
      });
  };

  const updateTableCell = (id: string, rowIndex: number, colIndex: number, text: string) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;

      const key = `${rowIndex}-${colIndex}`;
      const newContent = { ...(element.style.table.cellContent || {}), [key]: text };

      updateElementStyle(id, { table: { ...element.style.table, cellContent: newContent } });
  }

  const updateTableRowStyle = (id: string, rowIndex: number, styleUpdate: Partial<TextStyleConfig>) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;
      const currentStyles = element.style.table.rowStyles || {};
      const currentRowStyle = currentStyles[rowIndex] || {};
      const newStyles = { ...currentStyles, [rowIndex]: { ...currentRowStyle, ...styleUpdate } };
      updateElementStyle(id, { table: { ...element.style.table, rowStyles: newStyles } });
  }

  const updateTableColStyle = (id: string, colIndex: number, styleUpdate: Partial<TextStyleConfig>) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if (!element || !element.style.table) return;
      const currentStyles = element.style.table.colStyles || {};
      const currentColStyle = currentStyles[colIndex] || {};
      const newStyles = { ...currentStyles, [colIndex]: { ...currentColStyle, ...styleUpdate } };
      updateElementStyle(id, { table: { ...element.style.table, colStyles: newStyles } });
  }

  const handleTableColumnResizeStart = (e: React.MouseEvent, elementId: string, colIndex: number) => {
      e.stopPropagation();
      e.preventDefault();
      setSelectedId(elementId);
      setResizingTableCol({ elementId, colIndex });
      dragRef.current = { startX: e.clientX, startY: e.clientY };
  }

  const handleTableCellFocus = (elementId: string, r: number, c: number) => {
      if (selectedId !== elementId) setSelectedId(elementId);
      setActiveTableCell({ r, c });
  }

  // ... (FullCalendar updates unchanged) ...
  const updateFullCalendarStyle = (id: string, section: 'title' | 'weekDays' | 'days' | 'highlight', styleUpdate: Partial<TextStyleConfig>) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;

      if (section === 'highlight') {
          const newSpecialDays = {
              ...element.style.fullCalendar.specialDays,
              style: { ...element.style.fullCalendar.specialDays?.style, ...styleUpdate }
          };
          updateElementStyle(id, { fullCalendar: { ...element.style.fullCalendar, specialDays: newSpecialDays } });
          return;
      }

      const newFullCalendar = {
          ...element.style.fullCalendar,
          [section]: { ...element.style.fullCalendar[section], ...styleUpdate }
      };
      updateElementStyle(id, { fullCalendar: newFullCalendar });
  };

  const updateFullCalendarGrid = (id: string, gridUpdate: any) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;
      const newFullCalendar = {
          ...element.style.fullCalendar,
          grid: { ...element.style.fullCalendar.grid, ...gridUpdate }
      };
      updateElementStyle(id, { fullCalendar: newFullCalendar });
  }

  const updateFullCalendarSpecialFlags = (id: string, flags: { highlightSundays?: boolean, highlightHolidays?: boolean }) => {
      const activeList = getActiveElements();
      const element = activeList.find(e => e.id === id);
      if(!element || !element.style.fullCalendar) return;
      const newSpecialDays = { ...element.style.fullCalendar.specialDays, ...flags };
      updateElementStyle(id, { fullCalendar: { ...element.style.fullCalendar, specialDays: newSpecialDays } });
  }

  const updateElementName = (id: string, name: string) => {
    const activeList = getActiveElements();
    updateActiveElements(activeList.map(e => e.id === id ? { ...e, name } : e));
  };

  // Interaction handlers
  const handleInteractionStart = (e: React.MouseEvent, id: string, dir: string | null = null) => {
    if (activeTab === 'preview') return;
    e.stopPropagation();
    const activeList = getActiveElements();
    const element = activeList.find(el => el.id === id);
    if (!element) return;
    setSelectedId(id);
    dragRef.current = { startX: e.clientX, startY: e.clientY, initialX: element.x, initialY: element.y, initialW: element.w, initialH: element.h };
    if (dir) setResizeDir(dir); else setIsDragging(true);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (resizingTableCol && dragRef.current && selectedId) {
        // ... (Table resize logic unchanged)
        const { elementId, colIndex } = resizingTableCol;
        const activeList = getActiveElements();
        const element = activeList.find(el => el.id === elementId);

        if (element && element.style.table && element.style.table.columnWidths) {
            const tableWidthPx = (element.w / 100) * EDITOR_WIDTH_PX;
            const deltaX = e.clientX - dragRef.current.startX;
            const deltaPercent = (deltaX / tableWidthPx) * 100;

            const currentWidths = [...element.style.table.columnWidths];
            const nextColIndex = colIndex + 1;

            if (nextColIndex < currentWidths.length) {
                const newCurrentColWidth = Math.max(5, currentWidths[colIndex] + deltaPercent);
                const newNextColWidth = Math.max(5, currentWidths[nextColIndex] - deltaPercent);

                if (newCurrentColWidth >= 5 && newNextColWidth >= 5) {
                    currentWidths[colIndex] = newCurrentColWidth;
                    currentWidths[nextColIndex] = newNextColWidth;
                    const total = currentWidths.reduce((a, b) => a + b, 0);
                    const normalized = currentWidths.map(w => (w / total) * 100);
                    updateElementStyle(elementId, { table: { ...element.style.table, columnWidths: normalized } });
                    dragRef.current.startX = e.clientX;
                }
            }
        }
        return;
    }

    if ((!isDragging && !resizeDir) || !dragRef.current || !selectedId || !editorRef.current) return;
    const editorRect = editorRef.current.getBoundingClientRect();
    const deltaX = e.clientX - dragRef.current.startX;
    const deltaY = e.clientY - dragRef.current.startY;

    const activeList = getActiveElements();
    let newElementConfig = { ...activeList.find(el => el.id === selectedId)! };

    if (isDragging) {
        const { x, y } = calculateDragPosition(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, editorRect.width, editorRect.height);
        newElementConfig.x = x; newElementConfig.y = y;
    } else if (resizeDir) {
        const { x, y, w, h } = calculateResize(deltaX, deltaY, dragRef.current.initialX, dragRef.current.initialY, dragRef.current.initialW, dragRef.current.initialH, editorRect.width, editorRect.height, resizeDir);
        newElementConfig.x = x; newElementConfig.y = y; newElementConfig.w = w; newElementConfig.h = h;
    }

    updateActiveElements(activeList.map(el => el.id === selectedId ? newElementConfig : el));
  };

  const handleMouseUp = () => { 
      setIsDragging(false); 
      setResizeDir(null); 
      setResizingTableCol(null);
      dragRef.current = null; 
  };

  const renderResizeHandle = (cursor: string, dir: string) => {
      const pos: React.CSSProperties = { position: 'absolute', width: '8px', height: '8px', backgroundColor: 'white', border: '1px solid #4f46e5', borderRadius: '50%', zIndex: 50 };
      switch(dir) {
          case 'nw': pos.top = '-4px'; pos.left = '-4px'; break;
          case 'n':  pos.top = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'ne': pos.top = '-4px'; pos.right = '-4px'; break;
          case 'e':  pos.top = '50%'; pos.right = '-4px'; pos.transform = 'translateY(-50%)'; break;
          case 'se': pos.bottom = '-4px'; pos.right = '-4px'; break;
          case 's':  pos.bottom = '-4px'; pos.left = '50%'; pos.transform = 'translateX(-50%)'; break;
          case 'sw': pos.bottom = '-4px'; pos.left = '-4px'; break;
          case 'w':  pos.top = '50%'; pos.left = '-4px'; pos.transform = 'translateY(-50%)'; break;
      }
      return <div className="no-print" style={{ ...pos, cursor }} onMouseDown={(e) => handleInteractionStart(e, selectedId!, dir)} />;
  }

  const renderTemplate = (elements: LayoutElement[], day: DayData | null, isEditor: boolean = false, attachRef: boolean = false) => {
    // UPDATED: Using November 30th (Wednesday) as default editor data for max width testing
    // Month 10 = November (0-indexed), Day 3 = Wednesday
    const d = day || { dayOfMonth: 30, month: 10, year: config.year, dayOfWeek: 3, holiday: 'Feriado', moonPhase: 'Lua cheia', date: new Date() } as DayData;
    return (
      <div ref={attachRef ? editorRef : null} className={`relative overflow-hidden ${isEditor ? 'w-full h-full' : 'w-full h-full'}`} onMouseMove={isEditor ? handleMouseMove : undefined} onMouseUp={isEditor ? handleMouseUp : undefined} onMouseLeave={isEditor ? handleMouseUp : undefined}>
        {elements.map(el => {
          const isSelected = isEditor && selectedId === el.id;
          const wrapperStyle: React.CSSProperties = { left: `${el.x}%`, top: `${el.y}%`, width: `${el.w}%`, height: `${el.h}%`, zIndex: el.zIndex, transform: `rotate(${el.style.rotation || 0}deg) scaleX(${el.style.flipX ? -1 : 1}) scaleY(${el.style.flipY ? -1 : 1})` };
          const containerClass = `absolute group ${isSelected ? 'ring-2 ring-indigo-500 z-50' : 'hover:ring-1 hover:ring-indigo-300'}`;
          const isWrapperType = ['lines','box','circle','vector_flower','note_grid','habit_tracker','mini_calendar','full_calendar','table'].includes(el.type);

          return (
            <div key={el.id} onMouseDown={(e) => handleInteractionStart(e, el.id)} className={containerClass} style={wrapperStyle} title={el.name}>
                {isSelected && <>{['nw','n','ne','e','se','s','sw','w'].map(d => renderResizeHandle(d+'-resize', d))}</>}
                <div className={`w-full h-full relative ${isWrapperType ? 'overflow-hidden flex flex-col' : 'flex items-center'}`} style={{ justifyContent: el.style.textAlign === 'center' ? 'center' : (el.style.textAlign === 'right' ? 'flex-end' : 'flex-start'), ...(!isWrapperType ? el.style : {}) }}>
                    {isWrapperType ? (
                        <ElementRenderer 
                            element={el} 
                            dayData={d} 
                            quote={quotes[d.month]} 
                            isEditor={isEditor} 
                            isSelected={isSelected}
                            onContentChange={updateElementContent}
                            onTableResizeStart={handleTableColumnResizeStart}
                            onTableCellChange={updateTableCell}
                            onTableCellFocus={handleTableCellFocus}
                        />
                    ) : <span style={{ pointerEvents: 'none' }}><ElementRenderer element={el} dayData={d} quote={quotes[d.month]} isEditor={isEditor} isSelected={isSelected} onContentChange={updateElementContent} /></span>}
                </div>
            </div>
          );
        })}
      </div>
    );
  };
