import { jsPDF } from "jspdf";
import { AgendaConfig, DayData, LayoutElement, PageMargins } from "../types";
import { getMonthName, getDayName, generateMonthGrid } from "../core/backend/calendar";

// Helper to convert hex to RGB for jsPDF
const hexToRgb = (hex: string): { r: number, g: number, b: number } | null => {
  if (!hex || hex === 'transparent') return null;
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : null;
};

// Helper to map web fonts to standard PDF fonts
const getFont = (fontName: string | undefined, weight: string | number | undefined) => {
    let style = 'normal';
    if (weight === 'bold' || weight === '700' || (typeof weight === 'number' && weight > 600)) style = 'bold';

    if (fontName?.includes('Playfair') || fontName?.includes('Merriweather')) return { font: 'times', style };
    if (fontName?.includes('Courier') || fontName?.includes('Mono')) return { font: 'courier', style };
    return { font: 'helvetica', style };
};

const renderElementToPDF = (doc: jsPDF, el: LayoutElement, day: DayData | null, quote: string | undefined, pageW: number, pageH: number, year: number) => {
    const { x, y, w, h, style } = el;

    // Convert percentage positions to mm
    const absX = (x / 100) * pageW;
    const absY = (y / 100) * pageH;
    const absW = Math.max(0.1, (w / 100) * pageW);
    const absH = Math.max(0.1, (h / 100) * pageH);

    const rgb = hexToRgb(style.color || '#000000') || { r: 0, g: 0, b: 0 };
    const bgRgb = style.backgroundColor ? hexToRgb(style.backgroundColor) : null;
    const fontConfig = getFont(style.fontFamily, style.fontWeight);

    doc.setTextColor(rgb.r, rgb.g, rgb.b);
    doc.setFont(fontConfig.font, fontConfig.style);

    const fontSize = style.fontSize || 12;
    doc.setFontSize(fontSize); 

    let text = '';
    if (el.type === 'text') text = el.content || '';
    if (el.type === 'day_number' && day) text = day.dayOfMonth.toString();
    if (el.type === 'day_name' && day) text = getDayName(day.dayOfWeek);
    if (el.type === 'month_name' && day) text = getMonthName(day.month);
    if (el.type === 'year') text = day ? day.year.toString() : year.toString();
    if (el.type === 'quote') text = quote || '';
    if (el.type === 'holiday' && day) text = day.holiday || '';
    if (el.type === 'holiday_list') text = el.content || '';

    // Background/Shape
    if (el.type === 'box' || el.type === 'circle' || style.backgroundColor) {
        if (bgRgb) {
            doc.setFillColor(bgRgb.r, bgRgb.g, bgRgb.b);
            if (el.type === 'circle') {
                const r = Math.min(absW, absH) / 2;
                doc.circle(absX + absW/2, absY + absH/2, r, 'F');
            } else {
                doc.rect(absX, absY, absW, absH, 'F');
            }
        }
    }

    // Borders & Lines
    if ((style.borderWidth && style.borderWidth > 0) || el.type === 'lines') {
        const borderColor = (style.borderColor ? hexToRgb(style.borderColor) : null) || rgb;
        doc.setDrawColor(borderColor.r, borderColor.g, borderColor.b);
        doc.setLineWidth(style.borderWidth ? style.borderWidth * 0.2 : 0.1);

        if (el.type === 'lines') {
            const lineSpacingMm = Math.max(1, style.lineSpacing ? (style.lineSpacing / 3.78) : 6);
            const numLines = Math.floor(absH / lineSpacingMm);
            for(let i=1; i<=numLines; i++) {
                const ly = absY + (i * lineSpacingMm);
                doc.line(absX, ly, absX + absW, ly);
                if (style.showTimes) {
                    doc.setFontSize(fontSize * 0.6);
                    const hour = (style.startHour || 7) + (i - 1);
                    doc.text(`${hour}:00`, absX - 1, ly - 0.5, { align: 'right' });
                }
            }
            doc.setFontSize(fontSize); // Restore
        } else if (el.type === 'box' || el.type === 'habit_tracker') {
             doc.rect(absX, absY, absW, absH, 'D');
        } else if (el.type === 'circle') {
             const r = Math.min(absW, absH) / 2;
             doc.circle(absX + absW/2, absY + absH/2, r, 'D');
        }
    }

    // Text Content
    if (text) {
        let tx = absX;
        let align: 'left' | 'center' | 'right' = 'left';
        if (style.textAlign === 'center') { tx = absX + (absW / 2); align = 'center'; }
        else if (style.textAlign === 'right') { tx = absX + absW; align = 'right'; }

        let ty = absY + (fontSize * 0.352); // Basic baseline
        if (style.verticalAlign === 'middle' || (!style.verticalAlign && (el.type === 'day_number' || el.type === 'box'))) {
             ty = absY + (absH / 2) + (fontSize * 0.352 / 2);
        } else if (style.verticalAlign === 'bottom') {
             ty = absY + absH - 1;
        }

        if (style.textTransform === 'uppercase') text = text.toUpperCase();
        if (style.textTransform === 'lowercase') text = text.toLowerCase();

        if (el.type === 'text' || el.type === 'quote' || el.type === 'holiday_list' || el.type === 'holiday') {
            try {
                const splitText = doc.splitTextToSize(text, absW);
                doc.text(splitText, tx, absY + 2, { align, baseline: 'top' });
            } catch (e) {
                doc.text(text.substring(0, 20), tx, ty, { align });
            }
        } else {
            doc.text(text, tx, ty, { align });
        }
    }

    // Full Calendar Year Grid
    if (el.type === 'full_calendar') {
        const cols = style.monthsPerRow || 3;
        const rows = Math.ceil(12 / cols);
        const cellW = absW / cols;
        const cellH = absH / rows;

        for(let m=0; m<12; m++) {
            const c = m % cols;
            const r = Math.floor(m / cols);
            const mx = absX + (c * cellW);
            const my = absY + (r * cellH);
            doc.setFontSize(fontSize * 0.7);
            doc.text(getMonthName(m), mx + cellW/2, my + 3, { align: 'center' });
            doc.setDrawColor(200);
            doc.rect(mx + 1, my + 4, cellW - 2, cellH - 5);
        }
    }

    // Table
    if (el.type === 'table') {
        const rows = style.table?.rows || 5;
        const cols = style.table?.cols || 2;
        const rowH = absH / rows;
        const colWs = style.table?.columnWidths || Array(cols).fill(100/cols);
        let curY = absY;
        doc.setDrawColor(180);
        for (let r=0; r<rows; r++) {
            let curX = absX;
            for (let c=0; c<cols; c++) {
                const cW = (colWs[c] / 100) * absW;
                doc.rect(curX, curY, cW, rowH);
                const content = style.table?.cellContent?.[`${r}-${c}`];
                if (content) {
                    doc.setFontSize(fontSize * 0.6);
                    doc.text(content, curX + 1, curY + rowH/2 + 1);
                }
                curX += cW;
            }
            curY += rowH;
        }
    }
};

export const generateAndDownloadPDF = async (
    config: AgendaConfig, 
    generatedDays: DayData[], 
    quotes: string[],
    onProgress: (progress: number) => void
) => {
    const format = config.pageSize.toLowerCase();
    const orientation = config.orientation === 'portrait' ? 'p' : 'l';

    const doc = new jsPDF({
        orientation: orientation,
        unit: "mm",
        format: format,
        compress: true
    });

    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();

    const getElementsForPage = (elements: LayoutElement[], isEven: boolean): LayoutElement[] => {
        if (config.mirrorEvenPages && isEven) {
            return elements.map(el => {
                const newX = 100 - el.x - el.w;
                let newTextAlign = el.style.textAlign;
                if (newTextAlign === 'left') newTextAlign = 'right';
                else if (newTextAlign === 'right') newTextAlign = 'left';
                return { ...el, x: newX, style: { ...el.style, textAlign: newTextAlign } };
            });
        }
        return elements;
    };

    let globalPageCount = 0;
    const totalPhysicalPages = config.introPages.length + (
        config.layoutType === '1_per_page' ? generatedDays.length : 
        Math.ceil(generatedDays.length / 2)
    );

    // 1. Intro Pages
    for (const page of config.introPages) {
        if (globalPageCount > 0) doc.addPage(format, orientation);
        globalPageCount++;
        const isEven = globalPageCount % 2 === 0;
        getElementsForPage(page.elements, isEven).forEach(el => 
            renderElementToPDF(doc, el, null, undefined, pageW, pageH, config.year)
        );
        onProgress(Math.round((globalPageCount / totalPhysicalPages) * 100));
        await new Promise(r => setTimeout(r, 10));
    }

    // 2. Calendar Pages
    if (config.layoutType === '1_per_page') {
        for (const day of generatedDays) {
            if (globalPageCount > 0) doc.addPage(format, orientation);
            globalPageCount++;
            const isEven = globalPageCount % 2 === 0;
            getElementsForPage(config.elements, isEven).forEach(el => 
                renderElementToPDF(doc, el, day, quotes[day.month], pageW, pageH, config.year)
            );
            if (globalPageCount % 15 === 0) {
                onProgress(Math.round((globalPageCount / totalPhysicalPages) * 100));
                await new Promise(r => setTimeout(r, 5));
            }
        }
    } 
    else {
        // Shared Pages (2 per page or weekend shared)
        let i = 0;
        while (i < generatedDays.length) {
            if (globalPageCount > 0) doc.addPage(format, orientation);
            globalPageCount++;
            const isEven = globalPageCount % 2 === 0;
            const elements = getElementsForPage(config.elements, isEven);

            const day1 = generatedDays[i];
            const isWeekendShared = config.layoutType === '1_per_page_weekend_shared' && day1.dayOfWeek === 6;
            const isTwoPerPage = config.layoutType === '2_per_page';

            if (isTwoPerPage || isWeekendShared) {
                // Top Half
                elements.forEach(el => {
                    const halfEl = { ...el, h: el.h / 2, y: el.y / 2 };
                    renderElementToPDF(doc, halfEl, day1, quotes[day1.month], pageW, pageH, config.year);
                });
                // Bottom Half
                const day2 = generatedDays[i+1];
                if (day2) {
                    elements.forEach(el => {
                        const halfEl = { ...el, h: el.h / 2, y: (el.y / 2) + 50 };
                        renderElementToPDF(doc, halfEl, day2, quotes[day2.month], pageW, pageH, config.year);
                    });
                    doc.setDrawColor(220);
                    doc.setLineDash([1, 1], 0);
                    doc.line(0, pageH / 2, pageW, pageH / 2);
                    doc.setLineDash([], 0);
                }
                i += 2;
            } else {
                // Single day on page
                elements.forEach(el => renderElementToPDF(doc, el, day1, quotes[day1.month], pageW, pageH, config.year));
                i += 1;
            }

            if (globalPageCount % 10 === 0) {
                onProgress(Math.round((globalPageCount / totalPhysicalPages) * 100));
                await new Promise(r => setTimeout(r, 5));
            }
        }
    }

    onProgress(100);
    doc.save(`Agenda_${config.year}.pdf`);
};

import { jsPDF } from "jspdf";
import { AgendaConfig, DayData, LayoutElement } from "../types";
import { getMonthName, getDayName } from "../core/backend/calendar";

// Helper para converter Hex para RGB compatível com jsPDF
const hexToRgb = (hex: string | undefined): { r: number, g: number, b: number } => {
  if (!hex || hex === 'transparent' || hex === 'none') return { r: 0, g: 0, b: 0 };
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : { r: 0, g: 0, b: 0 };
};

// Mapeamento de fontes padrão do PDF
const getFont = (fontName: string | undefined, weight: string | number | undefined) => {
    let style = 'normal';
    if (weight === 'bold' || weight === '700' || (typeof weight === 'number' && weight > 600)) style = 'bold';
    if (fontName?.includes('Playfair') || fontName?.includes('Merriweather')) return { font: 'times', style };
    if (fontName?.includes('Courier') || fontName?.includes('Mono')) return { font: 'courier', style };
    return { font: 'helvetica', style };
};

const renderElementToPDF = (
    doc: jsPDF, 
    el: LayoutElement, 
    day: DayData | null, 
    quote: string | undefined, 
    pageW: number, 
    pageH: number, 
    configYear: number,
    isBottomHalf: boolean = false
) => {
    const { x, y, w, h, style } = el;

    // Coordenadas absolutas em mm
    // Se for a metade de baixo de uma página compartilhada, aplicamos o offset de 50% da altura da página
    const yOffset = isBottomHalf ? pageH / 2 : 0;

    // As porcentagens do elemento agora se referem à METADE da página se for layout compartilhado
    // mas o editor visual mostra eles em relação ao template total.
    // Portanto, dividimos a altura por 2 apenas se o layout for compartilhado na chamada externa.

    const absX = (x / 100) * pageW;
    const absY = (y / 100) * (isBottomHalf || yOffset > 0 ? pageH / 2 : pageH) + yOffset;
    const absW = (w / 100) * pageW;
    const absH = (h / 100) * (isBottomHalf || yOffset > 0 ? pageH / 2 : pageH);

    const rgb = hexToRgb(style.color);
    const bgRgb = style.backgroundColor ? hexToRgb(style.backgroundColor) : null;
    const fontConfig = getFont(style.fontFamily, style.fontWeight);

    doc.setTextColor(rgb.r, rgb.g, rgb.b);
    doc.setFont(fontConfig.font, fontConfig.style);
    doc.setFontSize(style.fontSize || 12); 

    let text = '';
    switch(el.type) {
        case 'text': text = el.content || ''; break;
        case 'day_number': text = day ? day.dayOfMonth.toString() : ''; break;
        case 'day_name': text = day ? getDayName(day.dayOfWeek) : ''; break;
        case 'month_name': text = day ? getMonthName(day.month) : ''; break;
        case 'year': text = day ? day.year.toString() : configYear.toString(); break;
        case 'quote': text = quote || ''; break;
        case 'holiday': text = day?.holiday || ''; break;
        case 'holiday_list': text = el.content || ''; break;
    }

    // Desenhar Fundo/Shapes
    if (bgRgb && (el.type === 'box' || el.type === 'circle' || style.backgroundColor !== 'transparent')) {
        doc.setFillColor(bgRgb.r, bgRgb.g, bgRgb.b);
        if (el.type === 'circle') {
            const r = Math.min(absW, absH) / 2;
            doc.circle(absX + absW/2, absY + absH/2, r, 'F');
        } else {
            doc.rect(absX, absY, absW, absH, 'F');
        }
    }

    // Bordas e Pautas
    if ((style.borderWidth && style.borderWidth > 0) || el.type === 'lines') {
        const bRgb = style.borderColor ? hexToRgb(style.borderColor) : rgb;
        doc.setDrawColor(bRgb.r, bRgb.g, bRgb.b);
        doc.setLineWidth(style.borderWidth ? style.borderWidth * 0.2 : 0.1);

        if (el.type === 'lines') {
            const spacing = style.lineSpacing ? (style.lineSpacing / 3.78) : 6;
            const lines = Math.floor(absH / spacing);
            for(let i=1; i<=lines; i++) {
                const ly = absY + (i * spacing);
                doc.line(absX, ly, absX + absW, ly);
                if (style.showTimes) {
                    doc.setFontSize((style.fontSize || 12) * 0.6);
                    const hour = (style.startHour || 7) + (i - 1);
                    doc.text(`${hour}:00`, absX - 1, ly - 0.5, { align: 'right' });
                }
            }
        } else {
            if (el.type === 'circle') {
                const r = Math.min(absW, absH) / 2;
                doc.circle(absX + absW/2, absY + absH/2, r, 'D');
            } else {
                doc.rect(absX, absY, absW, absH, 'D');
            }
        }
    }

    // Renderizar Texto
    if (text) {
        let tx = absX;
        let align: 'left' | 'center' | 'right' = 'left';
        if (style.textAlign === 'center') { tx = absX + (absW / 2); align = 'center'; }
        else if (style.textAlign === 'right') { tx = absX + absW; align = 'right'; }

        if (style.textTransform === 'uppercase') text = text.toUpperCase();
        if (style.textTransform === 'lowercase') text = text.toLowerCase();

        // Quebra automática para textos longos
        if (['text', 'quote', 'holiday_list', 'holiday'].includes(el.type)) {
            const split = doc.splitTextToSize(text, absW);
            doc.text(split, tx, absY + 1, { align, baseline: 'top' });
        } else {
            // Centralização vertical aproximada para números de dia e títulos
            const ty = absY + (absH / 2) + (doc.getFontSize() * 0.35 / 2);
            doc.text(text, tx, ty, { align });
        }
    }

    // Calendário Anual Especial
    if (el.type === 'full_calendar') {
        const cols = style.monthsPerRow || 3;
        const cW = absW / cols;
        const cH = absH / Math.ceil(12/cols);
        for(let m=0; m<12; m++) {
            const mx = absX + (m % cols) * cW;
            const my = absY + Math.floor(m / cols) * cH;
            doc.setFontSize((style.fontSize || 12) * 0.7);
            doc.text(getMonthName(m), mx + cW/2, my + 3, { align: 'center' });
            doc.setDrawColor(200);
            doc.rect(mx + 1, my + 4, cW - 2, cH - 5);
        }
    }

    // Tabelas
    if (el.type === 'table' && style.table) {
        const { rows, cols, columnWidths } = style.table;
        const rH = absH / rows;
        const cWs = columnWidths || Array(cols).fill(100/cols);
        let curY = absY;
        for (let r=0; r<rows; r++) {
            let curX = absX;
            for (let c=0; c<cols; c++) {
                const cellW = (cWs[c] / 100) * absW;
                doc.setDrawColor(180);
                doc.rect(curX, curY, cellW, rH);
                const content = style.table.cellContent?.[`${r}-${c}`];
                if (content) {
                    doc.setFontSize((style.fontSize || 12) * 0.6);
                    doc.text(content, curX + 1, curY + rH/2 + 1, { baseline: 'middle' });
                }
                curX += cellW;
            }
            curY += rH;
        }
    }
};

export const generateAndDownloadPDF = async (
    config: AgendaConfig, 
    generatedDays: DayData[], 
    quotes: string[],
    onProgress: (progress: number) => void
) => {
    const format = config.pageSize.toLowerCase();
    const orientation = config.orientation === 'portrait' ? 'p' : 'l';

    const doc = new jsPDF({
        orientation,
        unit: "mm",
        format,
        compress: true
    });

    const pW = doc.internal.pageSize.getWidth();
    const pH = doc.internal.pageSize.getHeight();

    const getElementsForPage = (elements: LayoutElement[], isEven: boolean): LayoutElement[] => {
        if (config.mirrorEvenPages && isEven) {
            return elements.map(el => {
                const newX = 100 - el.x - el.w;
                let newAlign = el.style.textAlign;
                if (newAlign === 'left') newAlign = 'right';
                else if (newAlign === 'right') newAlign = 'left';
                return { ...el, x: newX, style: { ...el.style, textAlign: newAlign } };
            });
        }
        return elements;
    };

    let pageCount = 0;
    const totalPhysicalPages = config.introPages.length + (
        config.layoutType === '1_per_page' ? generatedDays.length : Math.ceil(generatedDays.length / 2)
    );

    // 1. Páginas de Introdução
    for (const page of config.introPages) {
        if (pageCount > 0) doc.addPage(format, orientation);
        pageCount++;
        const isEven = pageCount % 2 === 0;
        getElementsForPage(page.elements, isEven).forEach(el => 
            renderElementToPDF(doc, el, null, undefined, pW, pH, config.year)
        );
        onProgress(Math.round((pageCount / totalPhysicalPages) * 100));
        await new Promise(r => setTimeout(r, 5));
    }

    // 2. Miolo da Agenda
    if (config.layoutType === '1_per_page') {
        for (const day of generatedDays) {
            if (pageCount > 0) doc.addPage(format, orientation);
            pageCount++;
            const isEven = pageCount % 2 === 0;
            getElementsForPage(config.elements, isEven).forEach(el => 
                renderElementToPDF(doc, el, day, quotes[day.month], pW, pH, config.year)
            );
            if (pageCount % 20 === 0) {
                onProgress(Math.round((pageCount / totalPhysicalPages) * 100));
                await new Promise(r => setTimeout(r, 5));
            }
        }
    } else {
        // Layouts Compartilhados (2 por página ou fim de semana)
        let i = 0;
        while (i < generatedDays.length) {
            if (pageCount > 0) doc.addPage(format, orientation);
            pageCount++;
            const isEven = pageCount % 2 === 0;
            const elements = getElementsForPage(config.elements, isEven);

            const day1 = generatedDays[i];
            const isWeekendShared = config.layoutType === '1_per_page_weekend_shared' && day1.dayOfWeek === 6;
            const isTwoPerPage = config.layoutType === '2_per_page';

            if (isTwoPerPage || isWeekendShared) {
                // Metade Superior
                elements.forEach(el => renderElementToPDF(doc, el, day1, quotes[day1.month], pW, pH, config.year, false));

                // Metade Inferior
                const day2 = generatedDays[i+1];
                if (day2) {
                    elements.forEach(el => renderElementToPDF(doc, el, day2, quotes[day2.month], pW, pH, config.year, true));
                    // Linha de corte/divisão
                    doc.setDrawColor(220);
                    doc.setLineDash([1, 1], 0);
                    doc.line(0, pH / 2, pW, pH / 2);
                    doc.setLineDash([], 0);
                }
                i += 2;
            } else {
                // Caso seja dia de semana em layout de fim de semana compartilhado
                elements.forEach(el => renderElementToPDF(doc, el, day1, quotes[day1.month], pW, pH, config.year, false));
                i += 1;
            }

            if (pageCount % 15 === 0) {
                onProgress(Math.round((pageCount / totalPhysicalPages) * 100));
                await new Promise(r => setTimeout(r, 5));
            }
        }
    }

    onProgress(100);
    doc.save(`AgendaMaster_${config.year}_${config.pageSize}.pdf`);
};

